/* ============================================

   🔥 إعلانات مقترحة لك (في شاشة الأقسام الرئيسية)

   ============================================ */

function renderSuggestedAds() {

  const section = document.getElementById("suggestedSection");

  const container = document.getElementById("suggestedAdsGrid");

  if (!section || !container) return;

  if (!Array.isArray(allPosts) || allPosts.length === 0) {

    section.style.display = "none";

    return;

  }

  // تصفية الإعلانات المعتمدة والصالحة وغير المباعة (باستثناء المطاعم)

  let items = allPosts.filter(p => {

    const st = getStatus(p);

    return st === "approved" && !isExpired(p) && !p.sold && !isRestaurantCategory(p.category);

  });

  if (items.length === 0) {

    section.style.display = "none";

    return;

  }

  // ترتيب: الإعلانات المميزة أولاً، ثم الأحدث

  items.sort((a, b) => {

    const af = isPostFeatured(a) ? 1 : 0;

    const bf = isPostFeatured(b) ? 1 : 0;

    if (bf !== af) return bf - af;

    return (b.createdAt || 0) - (a.createdAt || 0);

  });

  // اختيار ما يصل إلى 10 إعلانات مقترحة لشريط التمرير الأفقي

  const topItems = items.slice(0, 10);

  section.style.display = "block";

  container.innerHTML = topItems.map(p => {

    const imgs = getImages(p);

    const th = imgs[0] || "";

    const priceTxt = p.priceType === "contact" ? "📞 تواصل" : (p.price != null ? formatPrice(p.price) + " د.ل" : "");

    const city = p.city ? `📍 ${escapeHtml(p.city)}` : "";

    const isFeat = isPostFeatured(p);

    return `

      <div class="suggestedItem" onclick="openPost('${p.id}')">

        ${isFeat ? '<span class="sugFeatBadge">⭐ مميز</span>' : ''}

        <div class="sugThumbWrap">

          ${th ? `<img src="${escapeHtml(th)}" class="sugThumb" loading="lazy">` : `<div style="display:flex;align-items:center;justify-content:center;height:100%;font-size:24px;opacity:.4">🖼️</div>`}

        </div>

        <div class="sugInfo">

          <div class="sugTitle">${escapeHtml(p.title || "بدون عنوان")}</div>

          <div class="sugPrice">${priceTxt}</div>

          <div class="sugCity">${city}</div>

        </div>

      </div>

    `;

  }).join("");

}

window.renderSuggestedAds = renderSuggestedAds;

function renderRecentlyViewed(){

  if(typeof renderSuggestedAds === "function") renderSuggestedAds();

  if(typeof renderNearbyUsers === "function") renderNearbyUsers();

  if(typeof renderNearbyAds === "function") renderNearbyAds();

  const section=document.getElementById("recentSection");

  const box=document.getElementById("recentScroll");

  if(!section||!box)return;

  const ids=getRecentViews();

  const items=ids.map(id=>allPosts.find(p=>p.id===id)).filter(p=>p && getStatus(p)==="approved" && !isExpired(p) && !p.sold);

  if(items.length===0){section.classList.remove("hasItems");box.innerHTML="";return;}

  section.classList.add("hasItems");

  box.innerHTML=items.map(p=>{

    const imgs=getImages(p);const th=imgs[0]||"";

    const priceTxt=p.priceType==="contact"?"📞 تواصل":(p.price!=null?formatPrice(p.price)+" د.ل":"");

    return `<div class="recentItem" onclick="openPost('${p.id}')"><div style="width:100%;aspect-ratio:1/1;background:var(--teal-light);overflow:hidden">${th?`<img src="${escapeHtml(th)}" class="recentThumb">`:`<div style="display:flex;align-items:center;justify-content:center;height:100%;font-size:24px;opacity:.5">🖼️</div>`}</div><div class="recentInfo"><div class="recentName">${escapeHtml(p.title||"بدون عنوان")}</div><div class="recentPrice">${priceTxt}</div></div></div>`;

  }).join("");

}

/* ============================================

   البحث

   ============================================ */

const searchInputEl=document.getElementById("searchInput");

const clearSearchBtnEl=document.getElementById("clearSearchBtn");

try{const saved=localStorage.getItem('lastSearch');if(saved && searchInputEl){searchInputEl.value=saved;if(clearSearchBtnEl)clearSearchBtnEl.style.display='flex';if(saved.trim().length>=2)setTimeout(()=>searchServerPosts(saved.trim()),800);}}catch(e){}

let _searchDebounceTimer=null;

let _serverSearchCache={};

let _isSearchingServer=false;

window._matchedSearchUsers = [];

async function searchServerPosts(term){

  if(!term || term.trim().length < 2) {

    window._matchedSearchUsers = [];

    return;

  }

  const rawTerm = term.trim();

  const cleanTerm = rawTerm.replace(/^@/, '').toLowerCase();

  try {

    const sb = window.supabase || supabase;

    if(!sb) return;

    // 1) البحث الفوري في جدول profiles بالاسم أو المعرف (@username) أو رقم العضوية

    const num = parseInt(cleanTerm, 10);

    let userFilter = `name.ilike.%${cleanTerm}%,username.ilike.%${cleanTerm}%`;

    if(!isNaN(num) && num > 0){

      userFilter += `,member_no.eq.${num}`;

    }

    const { data: matchedUsers, error: uErr } = await sb

      .from('profiles')

      .select('id, name, username, member_no, phone')

      .or(userFilter)

      .limit(6);

    if(!uErr && matchedUsers && matchedUsers.length > 0){

      window._matchedSearchUsers = matchedUsers;

    } else {

      window._matchedSearchUsers = [];

    }

    // 2) البحث في جدول الإعلانات بالنص فقط (دون خلط إعلانات المستخدمين كإعلانات بالبحث)

    const seenIds = new Set(allPosts.map(p => p.id));

    let addedCount = 0;

    // 3) البحث في جدول الإعلانات بالنص

    const cacheKey = cleanTerm;

    if(!_serverSearchCache[cacheKey]){

      _serverSearchCache[cacheKey] = true;

      const { data, error } = await sb

        .from('posts')

        .select('*')

        .eq('status', 'approved')

        .or(`title.ilike.%${cleanTerm}%,description.ilike.%${cleanTerm}%,brand.ilike.%${cleanTerm}%,category.ilike.%${cleanTerm}%,city.ilike.%${cleanTerm}%,seller_name.ilike.%${cleanTerm}%,seller_username.ilike.%${cleanTerm}%`)

        .order('created_at', { ascending: false })

        .limit(30);

      if(!error && data && data.length > 0){

        data.forEach(raw => {

          const p = objectFromDb(raw);

          if(!seenIds.has(p.id)){

            seenIds.add(p.id);

            allPosts.push(p);

            addedCount++;

          }

        });

      }

    }

    if(addedCount > 0){

      allPosts = sortPosts(allPosts); window.allPosts = allPosts;

    }

    if(typeof renderPosts === 'function') renderPosts();

    if(typeof showSearchDropdown === 'function') showSearchDropdown();

  } catch(err){

    console.warn("Server search error:", err);

  }

}

window.searchServerPosts = searchServerPosts;

if(searchInputEl){

  searchInputEl.addEventListener('input',function(){

    const v=this.value||"";

    try{localStorage.setItem('lastSearch',v);}catch(e){}

    if(clearSearchBtnEl)clearSearchBtnEl.style.display=v.length>0?'flex':'none';

    if(typeof showSearchDropdown==='function')showSearchDropdown();

    if(_searchDebounceTimer)clearTimeout(_searchDebounceTimer);

    _searchDebounceTimer=setTimeout(()=>{

      if(v.trim().length>=2){searchServerPosts(v.trim());}

      if(typeof renderPosts==='function')renderPosts();

    },300);

  });

  searchInputEl.addEventListener('focus',function(){if(typeof showSearchDropdown==='function')showSearchDropdown();});

}

if(clearSearchBtnEl){clearSearchBtnEl.addEventListener('click',function(e){e.preventDefault();if(searchInputEl)searchInputEl.value="";try{localStorage.removeItem('lastSearch');}catch(e){}this.style.display='none';if(typeof hideSearchDropdown==='function')hideSearchDropdown();if(typeof renderPosts==='function')renderPosts();});}

function getSearchHistory(){

  try {

    const raw = JSON.parse(localStorage.getItem('searchHistory') || '[]');

    return Array.isArray(raw) ? raw : [];

  } catch(e) {

    return [];

  }

}

function addToSearchHistory(item){

  if(!item) return;

  let h = getSearchHistory();

  if(typeof item === 'object' && item.isUser){

    const uid = item.id || item.uid;

    h = h.filter(x => !(typeof x === 'object' && x && x.isUser && (x.id === uid || x.uid === uid)));

    h.unshift(item);

  } else if(typeof item === 'string'){

    const t = item.trim();

    if(t.length < 2) return;

    h = h.filter(x => typeof x !== 'string' || x.toLowerCase() !== t.toLowerCase());

    h.unshift(t);

  }

  if(h.length > 8) h = h.slice(0, 8);

  try { localStorage.setItem('searchHistory', JSON.stringify(h)); } catch(e){}

}

function removeFromHistory(target, event){

  if(event) event.stopPropagation();

  let h = getSearchHistory();

  h = h.filter(x => {

    if(typeof x === 'string') return x !== target;

    if(typeof x === 'object' && x){

      const uid = x.id || x.uid;

      return uid !== target && x.name !== target;

    }

    return true;

  });

  try { localStorage.setItem('searchHistory', JSON.stringify(h)); } catch(e){}

  showSearchDropdown();

}

function clearSearchHistory(event){

  if(event) event.stopPropagation();

  if(!confirm("مسح كل سجل البحث؟")) return;

  try { localStorage.removeItem('searchHistory'); } catch(e){}

  showSearchDropdown();

}

window.selectSearchedUser = function(user){

  if(!user) return;

  const uid = typeof user === 'string' ? user : (user.id || user.uid);

  const userName = (user.name || user.title || 'مستخدم').trim();

  const userUname = (user.username || '').replace(/^@/, '').trim();

  const userMember = user.member_no || user.memberNo || '';

  const userAvatar = (typeof window.getSafeSellerAvatar === "function") ? window.getSafeSellerAvatar(uid, user.avatar) : (user.avatar || "");

  // 1) حفظ الشخص في سجل آخر ما بحثت عنه

  addToSearchHistory({

    isUser: true,

    id: uid,

    name: userName,

    username: userUname,

    memberNo: userMember,

    avatar: userAvatar

  });

  // 2) إخفاء وتفريغ خانة البحث العلوية تماماً لمنع بقاء الاسم معلقاً

  const searchInput = document.getElementById("searchInput");

  if(searchInput){

    searchInput.value = "";

    searchInput.blur();

  }

  const clearBtn = document.getElementById("clearSearchBtn");

  if(clearBtn) clearBtn.style.display = "none";

  try { localStorage.removeItem('lastSearch'); } catch(e){}

  // 3) تصفير نتائج بحث المستخدمين وإعادة عرض الإعلانات الطبيعية في الخلفية

  window._matchedSearchUsers = [];

  hideSearchDropdown();

  if(typeof renderPosts === 'function') renderPosts();

  // 4) فتح الملف الشخصي فوراً

  if(typeof openSeller === 'function') openSeller(uid);

};

function getSuggestions(term){const t=(term||"").trim().toLowerCase();const seen=new Set();const results=[];allPosts.forEach(p=>{if(getStatus(p)!=="approved")return;if(isExpired(p))return;if(p.sold)return;const title=(p.title||"").trim();if(!title)return;const lower=title.toLowerCase();if(t && !lower.includes(t))return;const key=lower.slice(0,30);if(seen.has(key))return;seen.add(key);results.push({title,price:p.price,priceType:p.priceType,thumb:(p.images&&p.images[0])||p.imageUrl||""});});if(t){

    const cleanT = t.startsWith('@') ? t.slice(1) : t;

    // 👤 دمج الحسابات والأشخاص من نتائج البحث في profiles

    if(window._matchedSearchUsers && window._matchedSearchUsers.length > 0){

      window._matchedSearchUsers.forEach(u => {

        results.unshift({

          title: u.name || resolveDisplayName(u.id),

          username: u.username ? "@" + u.username : "",

          memberNo: u.member_no ? "#" + u.member_no : "",

          uid: u.id,

          isUser: true

        });

      });

    }

    // 👤 البحث عن المستخدمين بالمعرف والاسم

    const matchedUsers = new Map();

    allPosts.forEach(p => {

      if(p.uid && (p.sellerUsername || p.sellerName)){

        const u = (p.sellerUsername || "").toLowerCase();

        const n = (p.sellerName || "").toLowerCase();

        if((u.includes(cleanT) || n.includes(cleanT)) && !matchedUsers.has(p.uid)){

          matchedUsers.set(p.uid, {

            title: p.sellerName || resolveDisplayName(p.uid, p),

            username: p.sellerUsername ? "@" + p.sellerUsername : "",

            uid: p.uid,

            isUser: true

          });

        }

      }

    });

    matchedUsers.forEach(u => results.unshift(u));

    // 🏪 البحث عن المتاجر

    allStores.forEach(s => {

      if(s.status === "approved" && (s.name || "").toLowerCase().includes(cleanT)){

        results.unshift({

          title: s.name,

          thumb: s.logo || "",

          storeId: s.id,

          isStore: true

        });

      }

    });

    const allBrands=[...CAR_BRANDS,...MOTORCYCLE_BRANDS,...PHONE_BRANDS,...COMPUTER_BRANDS,...ANIMAL_TYPES,...PERFUME_TYPES];

    allBrands.forEach(b=>{if(b.toLowerCase().includes(t) && !seen.has(b.toLowerCase())){seen.add(b.toLowerCase());results.push({title:b,price:null,thumb:"",isBrand:true});}});

  }

  return results.slice(0,8);}

window.showSearchDropdown=function(){

  const box=document.getElementById("searchDropdown"),input=document.getElementById("searchInput");

  if(!box||!input)return;

  const term=(input.value||"").trim();

  const history=getSearchHistory();

  const suggestions=getSuggestions(term);

  let html="";

  // 1. سجل آخر ما بحثت عنه (عندما تكون الخانة فارغة)

  if(!term && history.length>0){

    html+=`<div class="sdSection">🕐 آخر ما بحثت عنه</div>`;

    html+=history.map(h=>{

      if(typeof h === 'object' && h && h.isUser){

        const safeName = escapeHtml(h.name || 'مستخدم');

        const safeUname = escapeHtml(h.username || '').replace(/^@/, '');

        const safeUid = escapeHtml(h.id || h.uid || '');

        const av = (typeof window.getSafeSellerAvatar === "function") ? window.getSafeSellerAvatar(h.id || h.uid, h.avatar) : (h.avatar || "");

        const initial = (h.name || '👤').trim()[0].toUpperCase();

        const avHtml = av ? `<img src="${escapeHtml(av)}" alt="${safeName}">` : initial;

        const uJson = JSON.stringify({

          isUser: true,

          id: h.id || h.uid,

          name: h.name || 'مستخدم',

          username: safeUname,

          memberNo: h.memberNo || '',

          avatar: av

        }).replace(/"/g, '&quot;');

        return `

          <div class="sdItem sdUserItem" onclick="selectSearchedUser(${uJson})">

            <span class="sdUserAvatar">${avHtml}</span>

            <span class="sdText">

              <b>${safeName}</b>

              ${safeUname ? `<span class="sdUserTag">@${safeUname}</span>` : ''}

            </span>

            <span class="sdUserBadge">حساب شخصي</span>

            <button type="button" class="sdRemove" onclick="removeFromHistory('${safeUid}', event)" title="إزالة من السجل">✕</button>

          </div>

        `;

      }

      const safeH=escapeHtml(typeof h === 'string' ? h : (h.title || h.name || '')).replace(/'/g,"&#39;");

      return `<div class="sdItem" onclick="pickSearch('${safeH}')"><span class="sdIcon">🕐</span><span class="sdText">${safeH}</span><button type="button" class="sdRemove" onclick="removeFromHistory('${safeH}',event)" title="إزالة">✕</button></div>`;

    }).join("");

    html+=`<div class="sdClearAll" onclick="clearSearchHistory(event)">🗑️ مسح كل السجل</div>`;

  }

  // 2. المقترحات أثناء الكتابة

  if(suggestions.length>0){

    const userSuggestions = suggestions.filter(s => s.isUser);

    const otherSuggestions = suggestions.filter(s => !s.isUser);

    // قسم الحسابات والأشخاص (خانة نظيفة ومبسطة فقط دون بطاقات ضخمة)

    if(userSuggestions.length > 0){

      html += `<div class="sdSection">👤 حسابات وأشخاص</div>`;

      html += userSuggestions.map(s => {

        const safeName = escapeHtml(s.title || 'مستخدم');

        const safeUname = escapeHtml(s.username || '').replace(/^@/, '');

        const safeMember = escapeHtml(s.memberNo || '').replace(/^#/, '');

        const av = (typeof window.getSafeSellerAvatar === "function") ? window.getSafeSellerAvatar(s.uid, s.avatar) : (s.avatar || "");

        const initial = (s.title || '👤').trim()[0].toUpperCase();

        const avHtml = av ? `<img src="${escapeHtml(av)}" alt="${safeName}">` : initial;

        const uJson = JSON.stringify({

          isUser: true,

          id: s.uid,

          name: s.title || 'مستخدم',

          username: safeUname,

          memberNo: safeMember,

          avatar: av

        }).replace(/"/g, '&quot;');

        return `

          <div class="sdItem sdUserItem" onclick="selectSearchedUser(${uJson})">

            <span class="sdUserAvatar">${avHtml}</span>

            <span class="sdText">

              <b>${safeName}</b>

              ${safeUname ? `<span class="sdUserTag">@${safeUname}</span>` : ''}

              ${safeMember ? `<span class="sdMemberTag">#${safeMember}</span>` : ''}

            </span>

            <span class="sdUserAction">عرض الحساب ›</span>

          </div>

        `;

      }).join("");

    }

    // قسم الإعلانات والمتاجر

    if(otherSuggestions.length > 0){

      const label = term ? "💡 مقترحات إعلانات" : "🔥 إعلانات مقترحة";

      html += `<div class="sdSection">${label}</div>`;

      html += otherSuggestions.map(s => {

        if(s.isStore){

          return `<div class="sdItem" onclick="hideSearchDropdown();openStore('${escapeHtml(s.storeId)}')"><span class="sdIcon">🏪</span><span class="sdText"><b>${escapeHtml(s.title)}</b></span><span style="font-size:11px;color:#92400e;font-weight:700">متجر معتمد ›</span></div>`;

        }

        const safeTitle = escapeHtml(s.title).replace(/'/g,"&#39;");

        const priceTxt = s.priceType==="contact"?"📞 تواصل":(s.price!=null?formatPrice(s.price)+" د.ل":"");

        return `<div class="sdItem" onclick="pickSearch('${safeTitle}')"><span class="sdIcon">${s.isBrand?"🏷️":(s.thumb?"📦":"🔎")}</span><span class="sdText">${escapeHtml(s.title)}</span>${priceTxt?`<span style="font-size:11.5px;color:var(--teal-dark);font-weight:700">${priceTxt}</span>`:""}</div>`;

      }).join("");

    }

  }

  if(!html) html=`<div class="sdSection" style="text-align:center;padding:20px;color:var(--muted)">اكتب للبحث...</div>`;

  box.innerHTML=html;

  box.classList.remove("hidden");

};

window.hideSearchDropdown=function(){const box=document.getElementById("searchDropdown");if(box)box.classList.add("hidden");};

window.pickSearch=function(term){const input=document.getElementById("searchInput");if(!input)return;input.value=term;addToSearchHistory(term);try{localStorage.setItem('lastSearch',term);}catch(e){}updateClearBtn();hideSearchDropdown();input.blur();if(term&&term.trim().length>=2){searchServerPosts(term.trim());}renderPosts();};

window.updateClearBtn=function(){const i=document.getElementById("searchInput");const b=document.getElementById("clearSearchBtn");if(!i||!b)return;b.style.display=(i.value&&i.value.length>0)?"flex":"none";};

window.clearSearch=function(){window._matchedSearchUsers=[];const i=document.getElementById("searchInput");if(i){i.value="";i.focus();}try{localStorage.removeItem('lastSearch');}catch(e){}updateClearBtn();hideSearchDropdown();renderPosts();};

document.addEventListener('click',(e)=>{const box=document.querySelector('.searchBox');if(box && !box.contains(e.target)){hideSearchDropdown();}});

/* ============================================

   أدوات الإعلانات

   ============================================ */

function isPostFeatured(p){return !!(p&&p.featured&&p.featuredUntil&&p.featuredUntil>Date.now());}

function featuredDaysLeft(p){if(!isPostFeatured(p))return 0;return Math.ceil((p.featuredUntil-Date.now())/(24*60*60*1000));}

function getStatus(p){return p.status||"approved";}

function getExpiresAt(p){if(p && p.expiresAt) return p.expiresAt;if(p && p.createdAt) return p.createdAt + POST_DURATION_MS;return null;}

function isExpired(p){const e=getExpiresAt(p);if(!e)return false;return e < Date.now();}

function daysLeft(p){const e=getExpiresAt(p);if(!e)return null;return Math.ceil((e-Date.now())/(24*60*60*1000));}

function expiredGracePassed(p){const e=getExpiresAt(p);if(!e)return false;const graceEnd=e+EXPIRED_GRACE_DAYS*24*60*60*1000;return Date.now()>graceEnd;}

function isWanted(p){return p && p.adType==="wanted";}

function sortPosts(arr){

  const featuredFirst=(a,b)=>{const af=isPostFeatured(a)?1:0;const bf=isPostFeatured(b)?1:0;return bf-af;};

  return arr.slice().sort((a,b)=>{

    const ff=featuredFirst(a,b);

    if(ff!==0)return ff;

    switch(currentSort){

      case "cheapest":return (Number(a.price)||0)-(Number(b.price)||0);

      case "expensive":return (Number(b.price)||0)-(Number(a.price)||0);

      case "views":return (b.views||0)-(a.views||0);

      default:return (b.createdAt||0)-(a.createdAt||0);

    }

  });

}

