function showFavoritesDirect(){if(showOnlyFavorites && !showOnlyMine){showCategoriesScreen();return;}showOnlyFavorites=true;showOnlyMine=false;currentSubCategory="الكل";currentStoreFilter=null;const cr=document.getElementById("catsRow");if(cr)cr.classList.add("hidden");renderSubCats();hideSearchDropdown();const titleEl=document.getElementById("categoryTitle");if(titleEl)titleEl.textContent="❤️ المفضلة";if(postsBox) postsBox.innerHTML="";renderPosts();categoriesScreen.classList.add("hidden");home.classList.remove("hidden");form.classList.add("hidden");const ss=document.getElementById("storesScreen");if(ss)ss.classList.add("hidden");const sc=document.getElementById("storeScreen");if(sc)sc.classList.add("hidden");closeOverlayDirect();setActiveNav("fav");setTopbarMode("scroll");updateCartUI();window.scrollTo(0,0);hideFloatingButtons();}

window.showFavoritesDirect=showFavoritesDirect;

window.showFavorites=(skipHistory)=>{showFavoritesDirect();if(!skipHistory)pushNavState({screen:'fav'},'#favorites');};

function setActiveNav(w){
  const nh = document.getElementById("navHome") || (typeof navHome !== "undefined" ? navHome : null);
  const nm = document.getElementById("navMine") || (typeof navMine !== "undefined" ? navMine : null);
  const nc = document.getElementById("navChat");
  const na = document.getElementById("navAccount");
  const nf = document.getElementById("navFav") || (typeof navFav !== "undefined" ? navFav : null);

  if(nh && nh.classList) nh.classList.toggle("active", w === "home");
  if(nm && nm.classList) nm.classList.toggle("active", w === "mine");
  if(nc && nc.classList) nc.classList.toggle("active", w === "chat");
  if(na && na.classList) na.classList.toggle("active", w === "account");
  if(nf && nf.classList) nf.classList.toggle("active", w === "fav");
}
window.setActiveNav = setActiveNav;

window.showHome=()=>{showCategoriesScreen();};

window.showFollowingPosts=()=>{

  const me=auth.currentUser;

  if(!me){pendingAction="following";authOverlay.classList.remove("hidden");return;}

  if(myFollowing.length===0){showToast("👥 لم تتابع أي بائع بعد","info");return;}

  const ids=myFollowing.map(f=>f.uid);

  showOnlyMine=false;showOnlyFavorites=false;currentSubCategory="الكل";currentStoreFilter=null;

  const titleEl=document.getElementById("categoryTitle");

  if(titleEl)titleEl.textContent="👥 إعلانات متابَعينك";

  categoriesScreen.classList.add("hidden");home.classList.remove("hidden");form.classList.add("hidden");

  closeOverlayDirect();setActiveNav("home");setTopbarMode("scroll");

  renderSubCats();

  const originalList=allPosts;

  const posts=allPosts.filter(p=>ids.includes(p.uid) && getStatus(p)==="approved" && !isExpired(p) && !p.sold);

  if(posts.length===0){postsBox.innerHTML="<div class='empty'>لا توجد إعلانات من متابَعيك</div>";}

  else{allPosts=sortPosts(posts);renderPosts();allPosts=originalList;}

  updateCartUI();window.scrollTo(0,0);hideFloatingButtons();

};

