// توليد كروت الشحن للأدمن (عدد مفتوح وفئات مرنة)

window.adminGenerateCardsBatch = async()=>{

  const canAdmin = (typeof isAdmin !== 'undefined' && isAdmin) ||
    (typeof window.isUserAdmin === 'function' && window.isUserAdmin(auth.currentUser, myProfile)) ||
    (typeof window.isAbdoAccount === 'function' && window.isAbdoAccount(auth.currentUser, myProfile)) ||
    (auth.currentUser && (
      auth.currentUser.email === ADMIN_EMAIL ||
      auth.currentUser.email === 'abdoalk73@gmail.com' ||
      (auth.currentUser.email && auth.currentUser.email.includes('928476784')) ||
      ADMIN_PHONES.includes((myProfile && myProfile.phone) || '')
    ));

  if(!canAdmin){
    showToast("❌ غير مصرح لك", "error");
    return;
  }

  const selDenom = document.getElementById("admCardDenom")?.value || "20";

  let denom = 20;

  if(selDenom === 'custom'){

    denom = parseInt(document.getElementById("admCardCustomDenom")?.value || "0", 10);

    if(isNaN(denom) || denom < 1 || denom > 5000){

      showToast("⚠️ يرجى إدخال قيمة فئة مخصصة صحيحة (من 1 إلى 5000 د.ل)", "warn");

      return;

    }

  }else{

    denom = parseInt(selDenom, 10);

  }

  const countInput = document.getElementById("admCardCount");

  const count = parseInt(countInput?.value || "10", 10);

  if(isNaN(count) || count < 1 || count > 500){

    showToast("⚠️ يرجى إدخال عدد كروت صحيح بين 1 و 500 كارت في الدفعة الواحدة", "warn");

    return;

  }

  const btn = document.getElementById("btnAdmGenCards");

  const outBox = document.getElementById("admGeneratedCardsOutput");

  const outText = document.getElementById("admGeneratedCardsText");

  if(!confirm(`هل تريد توليد وحفظ ${count} كارت من فئة ${denom} د.ل في المنظومة؟`)) return;

  if(btn){ btn.disabled = true; btn.textContent = "⏳ جاري توليد وحفظ الكروت..."; }

  try{

    const batchId = "batch_" + Date.now();
    let generated = [];

    // محاولة التوليد السريع الذري عبر RPC أولاً (محمي بصلاحية الأدمن)
    if(window.supabase && typeof window.supabase.rpc === 'function'){
      try{
        const adminUid = (auth.currentUser && auth.currentUser.uid) || (myProfile && (myProfile.uid || myProfile.id)) || "NrYY8We8VDgBiEk98bbxvkyfq2N2";
        const { data: rpcRes, error: rpcErr } = await window.supabase.rpc('admin_generate_cards', {
          p_admin_uid: adminUid,
          p_count: count,
          p_denom: denom,
          p_batch_id: batchId
        });
        if(!rpcErr && rpcRes && rpcRes.ok && Array.isArray(rpcRes.codes)){
          generated = rpcRes.codes;
        }
      }catch(rpcE){
        console.warn("RPC admin_generate_cards fallback:", rpcE);
      }
    }

    // التنفيذ المباشر إذا لم تكن دالة RPC مفعلة بعد
    if(generated.length === 0){
      for(let i=0; i<count; i++){

        const part1 = Math.floor(1000 + Math.random() * 9000);

        const part2 = Math.floor(1000 + Math.random() * 9000);

        const part3 = Math.floor(1000 + Math.random() * 9000);

        const code = `TK-${part1}-${part2}-${part3}`;

        const cardDocId = "card_" + code;

        const cardPayload = {

          code,

          amount: denom,

          batchId,

          isUsed: false,

          usedByUid: null,

          usedByName: null,

          usedByPhone: null,

          usedAt: null,

          createdAt: Date.now()

        };

        await setDoc(doc(db, "feedback", cardDocId), {

          id: cardDocId,

          type: "wallet_card",

          uid: "system",

          message: JSON.stringify(cardPayload),

          createdAt: Date.now()

        });

        generated.push(code);

      }
    }

    if(outBox) outBox.style.display = "block";

    if(outText){

      outText.value = `🌟 كروت شحن تسوق الآن (فئة ${denom} د.ل - إجمالي ${count} كارت):\n` + generated.map((c, idx) => `${idx+1}. ${c} (${denom} د.ل)`).join("\n");

    }

    showToast(`✅ تم بنجاح توليد وحفظ ${count} كارت في قاعدة البيانات!`, "success", 4000);

    loadAdminCardsList();

  }catch(e){

    showToast("خطأ: " + e.message, "error");

  }finally{

    if(btn){ btn.disabled = false; btn.textContent = "⚡ توليد وحفظ الكروت في قاعدة البيانات"; }

  }

};

