let _admDepTargetUser = null;

window.onAdmDepPhoneInputChanged = ()=>{

  const rawQuery = (document.getElementById("admDepPhone")?.value || "").trim();

  if(!rawQuery){

    _admDepTargetUser = null;

    const box = document.getElementById("admDepUserInfoBox");

    if(box){

      box.style.display = "none";

      box.innerHTML = "";

    }

  }

};

window.admLookupUserByPhone = async()=>{

  _admDepTargetUser = null;

  const rawQuery = (document.getElementById("admDepPhone")?.value || "").trim();

  const box = document.getElementById("admDepUserInfoBox");

  const btn = document.getElementById("btnAdmLookupPhone");

  if(!box) return;

  if(!rawQuery || rawQuery.length < 2){

    box.style.display = "block";

    box.style.background = "#fef2f2";

    box.style.color = "#991b1b";

    box.style.border = "1.5px solid #fecaca";

    box.style.borderRadius = "10px";

    box.style.padding = "10px 14px";

    box.style.fontSize = "13px";

    box.style.fontWeight = "700";

    box.textContent = "⚠️ يرجى كتابة رقم هاتف أو اسم مستخدم صحيح للبحث";

    return;

  }

  if(btn){

    btn.disabled = true;

    btn.textContent = "⏳...";

  }

  box.style.display = "block";

  box.style.background = "#f8fafc";

  box.style.color = "var(--text)";

  box.style.border = "1.5px solid var(--border)";

  box.style.borderRadius = "10px";

  box.style.padding = "12px 14px";

  box.style.fontSize = "13px";

  box.textContent = "⏳ جاري البحث عن صاحب الحساب في قاعدة البيانات...";

  try{

    let target = null;

    const cleanDigits = rawQuery.replace(/[^0-9]/g, "");

    const cleanUsername = rawQuery.replace(/^@/, "").toLowerCase();

    // 1. البحث برقم الهاتف

    if(cleanDigits.length >= 8 && window.supabase){

      const last8 = cleanDigits.slice(-8);

      const { data: pData } = await window.supabase

        .from("profiles")

        .select("*")

        .ilike("phone", `%${last8}%`)

        .limit(1)

        .maybeSingle();

      if(pData) target = pData;

      if(!target){

        const { data: phData } = await window.supabase

          .from("phones")

          .select("*")

          .ilike("phone", `%${last8}%`)

          .limit(1)

          .maybeSingle();

        if(phData && phData.uid){

          const { data: profData } = await window.supabase

            .from("profiles")

            .select("*")

            .eq("id", phData.uid)

            .limit(1)

            .maybeSingle();

          if(profData) target = profData;

        }

      }

    }

    // 2. البحث برقم العضوية (1 إلى 6 أرقام)

    if(!target && cleanDigits.length >= 1 && cleanDigits.length <= 6 && !isNaN(parseInt(rawQuery, 10)) && window.supabase){

      const memNo = parseInt(rawQuery, 10);

      const { data: mData } = await window.supabase

        .from("profiles")

        .select("*")

        .eq("member_no", memNo)

        .limit(1)

        .maybeSingle();

      if(mData) target = mData;

    }

    // 3. البحث باسم المستخدم

    if(!target && cleanUsername.length >= 2 && window.supabase){

      const { data: uData } = await window.supabase

        .from("profiles")

        .select("*")

        .ilike("username", cleanUsername)

        .limit(1)

        .maybeSingle();

      if(uData) target = uData;

      if(!target){

        const { data: unData } = await window.supabase

          .from("usernames")

          .select("*")

          .ilike("username", cleanUsername)

          .limit(1)

          .maybeSingle();

        if(unData && unData.uid){

          const { data: profData } = await window.supabase

            .from("profiles")

            .select("*")

            .eq("id", unData.uid)

            .limit(1)

            .maybeSingle();

          if(profData) target = profData;

        }

      }

    }

    // 4. البحث بـ UID أو الاسم

    if(!target && rawQuery.length >= 4 && window.supabase){

      const { data: anyData } = await window.supabase

        .from("profiles")

        .select("*")

        .or(`id.eq.${rawQuery},name.ilike.%${rawQuery}%`)

        .limit(1)

        .maybeSingle();

      if(anyData) target = anyData;

    }

    if(!target){

      box.style.background = "#fffbeb";

      box.style.color = "#92400e";

      box.style.border = "1.5px solid #fde68a";

      box.innerHTML = `⚠️ لم يتم العثور على أي حساب مسجل بـ "<b>${escapeHtml(rawQuery)}</b>". تأكد من رقم الهاتف أو اسم المستخدم.`;

      _admDepTargetUser = null;

      return;

    }

    _admDepTargetUser = target;

    const wal = await getUserWallet(target.id);

    box.style.background = "#f0fdf4";

    box.style.color = "#166534";

    box.style.border = "1.5px solid #86efac";

    box.style.padding = "12px";

    box.innerHTML = `

      <div style="font-weight:900;font-size:13px;color:#15803d;margin-bottom:8px;display:flex;align-items:center;gap:6px">

        ✅ تم العثور على حساب العضو بنجاح:

      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">

        <div style="background:#fff;border:1px solid #bbf7d0;border-radius:10px;padding:8px 12px">

          <div style="font-size:11px;color:var(--muted);font-weight:700">👤 الاسم الكامل:</div>

          <div style="font-size:13.5px;font-weight:900;color:var(--text);margin-top:2px">${escapeHtml(target.name || "مستخدم")}</div>

        </div>

        <div style="background:#fff;border:1px solid #bbf7d0;border-radius:10px;padding:8px 12px">

          <div style="font-size:11px;color:var(--muted);font-weight:700">🏷️ اسم المستخدم:</div>

          <div style="font-size:13.5px;font-weight:900;color:var(--text);margin-top:2px">@${escapeHtml(target.username || "—")}</div>

        </div>

        <div style="background:#fff;border:1px solid #bbf7d0;border-radius:10px;padding:8px 12px">

          <div style="font-size:11px;color:var(--muted);font-weight:700">📞 رقم الهاتف:</div>

          <div style="font-size:13.5px;font-weight:900;color:#0284c7;margin-top:2px;direction:ltr;text-align:right">${escapeHtml(target.phone || "—")}</div>

        </div>

        <div style="background:linear-gradient(135deg,#dcfce7,#bbf7d0);border:1.5px solid #22c55e;border-radius:10px;padding:8px 12px">

          <div style="font-size:11px;color:#15803d;font-weight:800">💳 الرصيد الحالي:</div>

          <div style="font-size:15px;font-weight:900;color:#166534;margin-top:2px">${wal.balance.toFixed(2)} د.ل</div>

        </div>

      </div>

    `;

  }catch(e){

    box.style.background = "#fef2f2";

    box.style.color = "#991b1b";

    box.style.border = "1.5px solid #fecaca";

    box.textContent = "خطأ في البحث: " + e.message;

    _admDepTargetUser = null;

  }finally{

    if(btn){

      btn.disabled = false;

      btn.textContent = "🔍 فحص";

    }

  }

};

window.adminExecuteDeposit = async()=>{

  const canAdmin = (typeof isAdmin !== 'undefined' && isAdmin) ||
    (typeof window.isUserAdmin === 'function' && window.isUserAdmin(auth.currentUser, myProfile)) ||
    (typeof window.isAbdoAccount === 'function' && window.isAbdoAccount(auth.currentUser, myProfile)) ||
    (auth.currentUser && (
      auth.currentUser.email === ADMIN_EMAIL ||
      auth.currentUser.email === 'abdoalk73@gmail.com' ||
      (auth.currentUser.email && auth.currentUser.email.includes('928476784')) ||
      ADMIN_PHONES.includes((myProfile && myProfile.phone) || '')
    ));

  if(!canAdmin){

    showToast("❌ ليس لديك صلاحية أدمن", "error");

    return;

  }

  const amt = parseFloat(document.getElementById("admDepAmount")?.value || "0");

  const type = document.getElementById("admDepType")?.value || "credit";

  const note = (document.getElementById("admDepNote")?.value || "").trim();

  const btn = document.getElementById("btnAdmExecuteDeposit");

  if(isNaN(amt) || amt <= 0){

    showToast("⚠️ يرجى إدخال مبلغ صحيح أكبر من 0", "warn");

    return;

  }

  if(!_admDepTargetUser){

    showToast("⚠️ يرجى الضغط على 'فحص' للتأكد من حساب الزبون أولاً", "warn");

    return;

  }

  const targetUid = _admDepTargetUser.id || _admDepTargetUser.uid;

  if(!targetUid){

    showToast("⚠️ تعذر تحديد معرف المستخدم، أعد فحصه بالرقم أو اليوزر", "warn");

    return;

  }

  const opLabel = type === 'credit' ? `إيداع مبلغ +${amt} د.ل` : `خصم مبلغ -${amt} د.ل`;

  if(!confirm(`هل أنت متأكد من ${opLabel} لحساب الزبون (${_admDepTargetUser.name || _admDepTargetUser.phone})؟`)) return;

  if(btn){ btn.disabled = true; btn.textContent = "⏳ جاري تنفيذ العملية وتحديث الرصيد..."; }

  try{

    const finalNote = note || (type === 'credit' ? "إيداع يدوي من الإدارة" : "خصم يدوي من الإدارة");

    let res = null;

    if(type === 'credit'){

      res = await creditUserWallet(targetUid, amt, finalNote, {

        txType: "admin_credit",

        userName: _admDepTargetUser.name,

        userPhone: _admDepTargetUser.phone,

        adminNote: finalNote

      });

    }else{

      res = await debitUserWallet(targetUid, amt, finalNote, {

        txType: "admin_debit",

        userName: _admDepTargetUser.name,

        userPhone: _admDepTargetUser.phone,

        adminNote: finalNote

      });

    }

    if(!res || !res.ok){

      showToast("❌ فشلت العملية: " + ((res && res.error) || "خطأ غير متوقع"), "error");

      return;

    }

    showToast(`✅ تمت العملية بنجاح! الرصيد الجديد: ${res.balance.toFixed(2)} د.ل`, "success", 4000);

    const amtInp = document.getElementById("admDepAmount");
    if(amtInp) amtInp.value = "";

    const noteInp = document.getElementById("admDepNote");
    if(noteInp) noteInp.value = "";

    const myCandUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(auth.currentUser?.uid) : [auth.currentUser?.uid];
    if(auth.currentUser && (auth.currentUser.uid === targetUid || myCandUids.includes(targetUid))){
      updateWalletUI(res.balance);
    }

    await admLookupUserByPhone();

  }catch(e){

    showToast("خطأ: " + e.message, "error");

  }finally{

    if(btn){ btn.disabled = false; btn.textContent = "💾 تنفيذ العملية وتحديث الرصيد فوراً"; }

  }

};

// مستحقات المطاعم (Restaurant Payouts & Ledger Breakdown)

window.filterLedgerByStore = (storeId, storeName)=>{

  switchAdmWalTab('ledger');

  const sel = document.getElementById("admLedgerStoreFilter");

  if(sel){

    let opt = Array.from(sel.options).find(o => o.value === storeId);

    if(!opt){

      opt = document.createElement("option");

      opt.value = storeId;

      opt.textContent = `🍽️ ${storeName}`;

      sel.appendChild(opt);

    }

    sel.value = storeId;

  }

  renderAdminLedgerTable();

};

async function loadAdminStoresPayouts(){

  const box = document.getElementById("admStoresPayoutsList");

  if(!box) return;

  box.innerHTML = `<div class="reportsEmpty">⏳ جاري حساب مبيعات ومستحقات المطاعم (أسبوعياً وشهرياً)...</div>`;

  try{

    let orders = [];

    if(window.supabase){

      const { data, error } = await window.supabase

        .from("feedback")

        .select("*")

        .eq("type", "restaurant_order")

        .order("created_at", { ascending: false })

        .limit(500);

      if(!error && data) orders = data;

    }

    const now = Date.now();

    const oneWeekAgo = now - (7 * 24 * 60 * 60 * 1000);

    const oneMonthAgo = now - (30 * 24 * 60 * 60 * 1000);

    const storesMap = {};

    orders.forEach(r=>{

      let ord = {};

      try{ ord = JSON.parse(r.message || "{}"); }catch(e){}

      if(ord.paymentMethod === 'wallet' && ord.isPaid && ord.status !== 'rejected'){

        const sId = ord.storeId || "unknown";

        if(!storesMap[sId]){

          storesMap[sId] = {

            storeId: sId,

            storeName: ord.storeName || "مطعم",

            storePhone: ord.storePhone || "",

            countAll: 0,

            revenueAll: 0,

            countWeek: 0,

            revenueWeek: 0,

            countMonth: 0,

            revenueMonth: 0

          };

        }

        const amt = Number(ord.totalPrice || 0);

        const orderTime = Number(ord.createdAt || (r.created_at ? new Date(r.created_at).getTime() : now));

        storesMap[sId].countAll += 1;

        storesMap[sId].revenueAll += amt;

        if(orderTime >= oneWeekAgo){

          storesMap[sId].countWeek += 1;

          storesMap[sId].revenueWeek += amt;

        }

        if(orderTime >= oneMonthAgo){

          storesMap[sId].countMonth += 1;

          storesMap[sId].revenueMonth += amt;

        }

      }

    });

    const list = Object.values(storesMap);

    populateLedgerStoreFilter(list);

    if(list.length === 0){

      box.innerHTML = `<div class="reportsEmpty">لا توجد طلبيات مطاعم مدفوعة بالمحفظة حتى الآن</div>`;

      return;

    }

    box.innerHTML = list.map(st=>`

      <div style="background:var(--card);border:1.5px solid var(--border);border-radius:12px;padding:12px">

        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px">

          <div>

            <div style="font-weight:900;font-size:15px;color:var(--text)">🍽️ ${escapeHtml(st.storeName)}</div>

            <div style="font-size:11.5px;color:var(--muted);margin-top:2px">

              ${st.storePhone ? `📞 <a href="tel:${formatCallPhone(st.storePhone)}" style="color:#0284c7;text-decoration:none;font-weight:700">${escapeHtml(st.storePhone)}</a> — ` : ''}

              إجمالي الطلبات المدفوعة بالمحفظة: <b>${st.countAll}</b> طلب

            </div>

          </div>

          <button type="button" class="btnGhost" onclick="filterLedgerByStore('${escapeHtml(st.storeId)}', '${escapeHtml(st.storeName)}')" style="padding:6px 12px;font-size:11.5px;font-weight:800;border:1.5px solid var(--teal);color:var(--teal-dark);background:var(--teal-light);border-radius:8px;cursor:pointer">

            📜 كشف الحساب

          </button>

        </div>

        <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:6px">

          <div style="background:#f0fdf4;border:1px solid #bbf7d0;border-radius:8px;padding:8px;text-align:center">

            <div style="font-size:10.5px;color:#166534;font-weight:700">مبيعات هذا الأسبوع</div>

            <div style="font-size:14px;font-weight:900;color:#15803d;margin-top:2px">${st.revenueWeek.toFixed(2)} د.ل</div>

            <div style="font-size:10px;color:#15803d">(${st.countWeek} طلب)</div>

          </div>

          <div style="background:#eff6ff;border:1px solid #bfdbfe;border-radius:8px;padding:8px;text-align:center">

            <div style="font-size:10.5px;color:#1e40af;font-weight:700">مبيعات هذا الشهر</div>

            <div style="font-size:14px;font-weight:900;color:#1d4ed8;margin-top:2px">${st.revenueMonth.toFixed(2)} د.ل</div>

            <div style="font-size:10px;color:#1d4ed8">(${st.countMonth} طلب)</div>

          </div>

          <div style="background:#faf5ff;border:1px solid #e9d5ff;border-radius:8px;padding:8px;text-align:center">

            <div style="font-size:10.5px;color:#6b21a8;font-weight:700">الإجمالي الكلي</div>

            <div style="font-size:14px;font-weight:900;color:#7e22ce;margin-top:2px">${st.revenueAll.toFixed(2)} د.ل</div>

            <div style="font-size:10px;color:#7e22ce">(${st.countAll} طلب)</div>

          </div>

        </div>

      </div>

    `).join("");

  }catch(e){

    box.innerHTML = `<div class="reportsEmpty">خطأ: ${e.message}</div>`;

  }

}
window.loadAdminStoresPayouts = loadAdminStoresPayouts;

// 14. دوال التحكم بالدفع من السلة

window.toggleRestPaymentMethod = ()=>{

  const pMethod = document.querySelector('input[name="restPaymentMethod"]:checked')?.value || "cash";

  const lblCash = document.getElementById("lblPayCash");

  const lblWallet = document.getElementById("lblPayWallet");

  if(lblCash){

    lblCash.style.borderColor = (pMethod === 'cash') ? 'var(--teal)' : 'var(--border)';

    lblCash.style.borderWidth = (pMethod === 'cash') ? '2px' : '1px';

  }

  if(lblWallet){

    lblWallet.style.borderColor = (pMethod === 'wallet') ? 'var(--teal)' : 'var(--border)';

    lblWallet.style.borderWidth = (pMethod === 'wallet') ? '2px' : '1px';

  }

  updateCartWalletBalance();

};

export async function updateCartWalletBalance(){

  const noticeBox = document.getElementById("cartWalletNotice");

  const pMethod = document.querySelector('input[name="restPaymentMethod"]:checked')?.value || "cash";

  const total = cartTotalPrice();

  if(!auth.currentUser){

    const cartBal = document.getElementById("cartWalletCurrentBalanceBadge");

    if(cartBal) cartBal.textContent = "سجّل دخولك للدفع بالمحفظة";

    if(pMethod === 'wallet' && noticeBox){

      noticeBox.style.display = "block";

      noticeBox.style.background = "#fffbeb";

      noticeBox.style.color = "#92400e";

      noticeBox.style.border = "1px solid #fde68a";

      noticeBox.innerHTML = `⚠️ يرجى تسجيل الدخول أولاً لتتمكن من الدفع الفوري من محفظتك الإلكترونية.`;

    }else if(noticeBox){

      noticeBox.style.display = "none";

    }

    return;

  }

  const wal = await getUserWallet(auth.currentUser.uid);

  updateWalletUI(wal.balance);

  if(!noticeBox) return;

  if(pMethod === 'wallet'){

    noticeBox.style.display = "block";

    if(wal.balance < total){

      noticeBox.style.background = "#fef2f2";

      noticeBox.style.color = "#991b1b";

      noticeBox.style.border = "1px solid #fecaca";

      noticeBox.innerHTML = `

        <div style="font-weight:800;margin-bottom:4px">⚠️ رصيدك (${wal.balance.toFixed(2)} د.ل) لا يكفي لدفع قيمة الطلب (${total} د.ل).</div>

        <button type="button" class="btnMain" onclick="openRechargeModal()" style="padding:6px 12px;font-size:12px;background:#0284c7;color:#fff;margin-top:4px;margin-bottom:0">⚡ اشحن محفظتك الآن بكارت أو تحويل</button>

      `;

    }else{

      noticeBox.style.background = "#f0fdf4";

      noticeBox.style.color = "#166534";

      noticeBox.style.border = "1px solid #bbf7d0";

      noticeBox.innerHTML = `🟢 <b>رصيدك كافٍ!</b> سيتم خصم <b>${total} د.ل</b> من محفظتك فوراً، وستصل طلبيتك للكاشير كطلبية مدفوعة مسبقاً وخالصة.`;

    }

  }else{

    noticeBox.style.display = "none";

  }

}

window.updateCartWalletBalance = updateCartWalletBalance;

/* ============================================================

   💬 15. نظام الدردشة المباشرة وصندوق المحادثات (Realtime فوري عبر الجداول المخصصة)

   ============================================================ */

window._activeChat = null;

let _chatChannel = null;

function getCanonicalChatUid(uid) {
  if (!uid) return uid;
  if (uid === 'zoSxkP0PGPWx37J6GMQiOjVgiMC3' || uid === 'NrYY8We8VDgBiEk98bbxvkyfq2N2') {
    return 'NrYY8We8VDgBiEk98bbxvkyfq2N2';
  }
  if (typeof window.getCandidateUids === 'function') {
    const cands = window.getCandidateUids(uid);
    if (cands.includes('NrYY8We8VDgBiEk98bbxvkyfq2N2') || cands.includes('zoSxkP0PGPWx37J6GMQiOjVgiMC3')) {
      return 'NrYY8We8VDgBiEk98bbxvkyfq2N2';
    }
  }
  return uid;
}

function chatConvId(a, b){
  const ca = getCanonicalChatUid(a);
  const cb = getCanonicalChatUid(b);
  return [ca, cb].sort().join("_");
}

window._chatSelectMode = false;

window._selectedChatMsgIds = new Set();

let _chatLongPressTimer = null;

let _chatTouchStartX = 0;

let _chatTouchStartY = 0;

function _attachBubbleEvents(bubble){

  if(!bubble || bubble._eventsAttached) return;

  bubble._eventsAttached = true;

  // 1) لمس مطول للشاشات التي تعمل باللمس (موبايل وتابلت)

  bubble.addEventListener('touchstart', (e) => {

    if(!e.touches || e.touches.length > 1) return;

    _chatTouchStartX = e.touches[0].clientX;

    _chatTouchStartY = e.touches[0].clientY;

    _chatLongPressTimer = setTimeout(() => {

      if(navigator.vibrate) try{ navigator.vibrate(40); }catch(v){}

      if(!window._chatSelectMode){

        enterChatSelectMode(bubble);

      } else {

        toggleSelectBubble(bubble);

      }

    }, 450);

  }, { passive: true });

  bubble.addEventListener('touchmove', (e) => {

    if(!_chatLongPressTimer) return;

    const dx = Math.abs(e.touches[0].clientX - _chatTouchStartX);

    const dy = Math.abs(e.touches[0].clientY - _chatTouchStartY);

    if(dx > 10 || dy > 10){

      clearTimeout(_chatLongPressTimer);

      _chatLongPressTimer = null;

    }

  }, { passive: true });

  bubble.addEventListener('touchend', () => {

    if(_chatLongPressTimer){

      clearTimeout(_chatLongPressTimer);

      _chatLongPressTimer = null;

    }

  });

  bubble.addEventListener('touchcancel', () => {

    if(_chatLongPressTimer){

      clearTimeout(_chatLongPressTimer);

      _chatLongPressTimer = null;

    }

  });

  // 2) النقر عند تفعيل وضع التحديد

  bubble.addEventListener('click', (e) => {

    if(window._chatSelectMode){

      e.preventDefault();

      e.stopPropagation();

      toggleSelectBubble(bubble);

    }

  });

  // 3) كليك يمين للكمبيوتر (Desktop)

  bubble.addEventListener('contextmenu', (e) => {

    e.preventDefault();

    if(!window._chatSelectMode){

      enterChatSelectMode(bubble);

    } else {

      toggleSelectBubble(bubble);

    }

  });

}

export function toggleChatSelectionMode(){

  if(window._chatSelectMode){

    cancelChatSelection();

  } else {

    enterChatSelectMode();

  }

}

window.toggleChatSelectionMode = toggleChatSelectionMode;

export function enterChatSelectMode(initialBubble){

  window._chatSelectMode = true;

  window._selectedChatMsgIds.clear();

  const box = document.getElementById("chatMessagesBox");

  if(box) box.classList.add("chatSelectMode");

  const bar = document.getElementById("chatSelectionBar");

  if(bar) bar.style.display = "flex";

  const delBtn = document.getElementById("chatHeaderDeleteBtn");

  if(delBtn) delBtn.classList.add("active");

  if(initialBubble){

    const msgId = initialBubble.getAttribute("data-msg-id");

    if(msgId){

      window._selectedChatMsgIds.add(String(msgId));

      initialBubble.classList.add("msgSelected");

    }

  }

  _updateSelectionBarUI();

}

window.enterChatSelectMode = enterChatSelectMode;

export function cancelChatSelection(){

  window._chatSelectMode = false;

  window._selectedChatMsgIds.clear();

  const box = document.getElementById("chatMessagesBox");

  if(box){

    box.classList.remove("chatSelectMode");

    box.querySelectorAll(".msgSelected").forEach(b => b.classList.remove("msgSelected"));

  }

  const bar = document.getElementById("chatSelectionBar");

  if(bar) bar.style.display = "none";

  const delBtn = document.getElementById("chatHeaderDeleteBtn");

  if(delBtn) delBtn.classList.remove("active");

}

window.cancelChatSelection = cancelChatSelection;

export function toggleSelectBubble(bubble){

  const msgId = bubble.getAttribute("data-msg-id");

  if(!msgId) {

    showToast("هذه الرسالة قيد الإرسال، انتظر لحظة", "info");

    return;

  }

  if(window._selectedChatMsgIds.has(String(msgId))){

    window._selectedChatMsgIds.delete(String(msgId));

    bubble.classList.remove("msgSelected");

  } else {

    window._selectedChatMsgIds.add(String(msgId));

    bubble.classList.add("msgSelected");

  }

  _updateSelectionBarUI();

}

window.toggleSelectBubble = toggleSelectBubble;

export function selectAllChatMessages(){

  const box = document.getElementById("chatMessagesBox");

  if(!box) return;

  const bubbles = box.querySelectorAll(".chatBubble[data-msg-id]");

  const allSelected = bubbles.length > 0 && Array.from(bubbles).every(b => window._selectedChatMsgIds.has(String(b.getAttribute("data-msg-id"))));

  if(allSelected){

    window._selectedChatMsgIds.clear();

    bubbles.forEach(b => b.classList.remove("msgSelected"));

  } else {

    bubbles.forEach(b => {

      const id = b.getAttribute("data-msg-id");

      if(id){

        window._selectedChatMsgIds.add(String(id));

        b.classList.add("msgSelected");

      }

    });

  }

  _updateSelectionBarUI();

}

window.selectAllChatMessages = selectAllChatMessages;

function _updateSelectionBarUI(){

  const count = window._selectedChatMsgIds.size;

  const countEl = document.getElementById("chatSelectionCount");

  const btnDelete = document.getElementById("btnConfirmDeleteMsgs");

  if(countEl){

    if(count === 0){

      countEl.textContent = "اضغط على أي رسالة لتحديدها";

    } else if(count === 1){

      countEl.textContent = "تم تحديد رسالة واحدة";

    } else if(count === 2){

      countEl.textContent = "تم تحديد رسالتين";

    } else if(count <= 10){

      countEl.textContent = `تم تحديد ${count} رسائل`;

    } else {

      countEl.textContent = `تم تحديد ${count} رسالة`;

    }

  }

  if(btnDelete){

    if(count > 0){

      btnDelete.style.opacity = "1";

      btnDelete.style.pointerEvents = "auto";

      btnDelete.innerHTML = `<span>🗑️</span><span>حذف من الطرفين (${count})</span>`;

    } else {

      btnDelete.style.opacity = "0.5";

      btnDelete.style.pointerEvents = "none";

      btnDelete.innerHTML = `<span>🗑️</span><span>حذف من الطرفين</span>`;

    }

  }

}

export function confirmDeleteSelectedChatMessages(){

  const count = window._selectedChatMsgIds.size;

  if(count === 0) return;

  const box = document.getElementById("chatMessagesBox");

  let myMessagesCount = 0;

  let otherMessagesCount = 0;

  window._selectedChatMsgIds.forEach(id => {

    const el = box ? box.querySelector(`[data-msg-id="${id}"]`) : null;

    if(el){

      if(el.classList.contains("outgoing")){

        myMessagesCount++;

      } else {

        otherMessagesCount++;

      }

    }

  });

  const textEl = document.getElementById("deleteChatConfirmText");

  const btnEveryone = document.getElementById("btnDeleteForEveryone");

  const btnForMe = document.getElementById("btnDeleteForMe");

  // 🔒 قاعدة أساسية: كل شخص يحذف رسائله هو فقط من الطرفين!

  // رسائل الطرف الآخر تُحذف من عندك فقط ولا يمكن حذفها من الطرفين

  if(btnEveryone){

    if(otherMessagesCount > 0 && myMessagesCount === 0){

      // كل الرسائل المحددة من الطرف الآخر -> لا يمكن حذفها من الطرفين

      btnEveryone.style.display = "none";

    } else if(otherMessagesCount > 0 && myMessagesCount > 0){

      // مختلط -> حذف رسائلي فقط من الطرفين

      btnEveryone.style.display = "flex";

      btnEveryone.innerHTML = `<span>🗑️</span><span>حذف رسائلي فقط من الطرفين (${myMessagesCount})</span>`;

    } else {

      // كلها رسائلي -> متاح بالكامل للطرفين

      btnEveryone.style.display = "flex";

      btnEveryone.innerHTML = `<span>🗑️</span><span>الحذف لدى الجميع (من الطرفين) (${count})</span>`;

    }

  }

  if(btnForMe){

    btnForMe.innerHTML = `<span>👁️‍🗨️</span><span>الحذف لدي فقط (${count})</span>`;

  }

  if(textEl){

    if(otherMessagesCount > 0 && myMessagesCount === 0){

      textEl.textContent = count === 1 ? "هذه الرسالة مرسلة من الطرف الآخر، يمكنك حذفها من عندك فقط." : "الرسائل المحددة مرسلة من الطرف الآخر، يمكنك حذفها من عندك فقط.";

    } else {

      textEl.textContent = "اختر هل تريد حذف الرسائل من عندك فقط أم من الطرفين:";

    }

  }

  const modal = document.getElementById("deleteChatConfirmModal");

  if(modal) modal.classList.remove("hidden");

}

window.confirmDeleteSelectedChatMessages = confirmDeleteSelectedChatMessages;

export function closeDeleteChatConfirmModal(){

  const modal = document.getElementById("deleteChatConfirmModal");

  if(modal) modal.classList.add("hidden");

}

window.closeDeleteChatConfirmModal = closeDeleteChatConfirmModal;

export async function executeDeleteSelectedChatMessages(mode = 'everyone'){

  const modal = document.getElementById("deleteChatConfirmModal");

  if(modal) modal.classList.add("hidden");

  const ids = Array.from(window._selectedChatMsgIds).map(x => Number(x)).filter(Boolean);

  if(ids.length === 0) return;

  const box = document.getElementById("chatMessagesBox");

  const activeChat = window._activeChat;

  const convId = activeChat ? activeChat.convId : null;

  const myUid = auth.currentUser ? auth.currentUser.uid : "";

  const sb = window.supabase || supabase;

  try {

    if(mode === 'for_me'){

      // ============================================

      // 1) الحذف لدي فقط (من عندي مثل ماسنجر)

      // ============================================

      showToast("⏳ جاري حذف الرسائل من عندك...", "info");

      // حفظ محلياً في localStorage

      const localKey = "tasawuq_hidden_msgs_" + myUid;

      let localHidden = [];

      try { localHidden = JSON.parse(localStorage.getItem(localKey) || "[]"); } catch(e){}

      const updatedHidden = Array.from(new Set([...localHidden, ...ids]));

      localStorage.setItem(localKey, JSON.stringify(updatedHidden));

      // حفظ في سوبابيز داخل store_context.hidden_for

      if(convId && myUid){

        try{

          const { data: conv } = await sb.from("chat_conversations").select("store_context").eq("conv_id", convId).maybeSingle();

          let sc = conv?.store_context;

          if(!sc || typeof sc !== 'object') sc = {};

          if(!sc.hidden_for || typeof sc.hidden_for !== 'object') sc.hidden_for = {};

          const prev = Array.isArray(sc.hidden_for[myUid]) ? sc.hidden_for[myUid] : [];

          sc.hidden_for[myUid] = Array.from(new Set([...prev, ...ids]));

          await sb.from("chat_conversations").update({ store_context: sc }).eq("conv_id", convId);

        }catch(e){}

      }

      // إزالة من الشاشة فوراً

      ids.forEach(id => {

        const el = box ? box.querySelector(`[data-msg-id="${id}"]`) : null;

        if(el){

          el.style.transition = "all .25s ease";

          el.style.opacity = "0";

          el.style.transform = "scale(0.8)";

          setTimeout(() => el.remove(), 250);

        }

      });

      try {

        const cKey = "tasawuq_chat_cache_" + convId;

        const cur = JSON.parse(localStorage.getItem(cKey) || "[]");

        const idSet = new Set(ids.map(Number));

        localStorage.setItem(cKey, JSON.stringify(cur.filter(m => !idSet.has(Number(m.id)))));

      } catch(e){}

      cancelChatSelection();

      showToast("تم حذف الرسائل من عندك بنجاح 🗑️", "success");

    } else {

      // ============================================

      // 2) الحذف لدى الجميع (من الطرفين مثل ماسنجر)

      // ============================================

      showToast("⏳ جاري حذف الرسائل من الطرفين...", "info");

      // 🔒 فحص أمني: كل شخص يحذف رسائله هو فقط من جدول chat_messages للطرفين

      const myMsgIds = [];

      const otherMsgIds = [];

      ids.forEach(id => {

        const el = box ? box.querySelector(`[data-msg-id="${id}"]`) : null;

        if(el && el.classList.contains("outgoing")){

          myMsgIds.push(id);

        } else {

          otherMsgIds.push(id);

        }

      });

      if(myMsgIds.length > 0){

        const { error } = await sb

          .from("chat_messages")

          .delete()

          .in("id", myMsgIds)

          .eq("sender_uid", myUid);

        if(error) throw error;

      }

      // إذا كانت هناك رسائل أخرى محددة للطرف الآخر، تُحذف من عندي فقط

      if(otherMsgIds.length > 0 && convId && myUid){

        try{

          const localKey = "tasawuq_hidden_msgs_" + myUid;

          let localHidden = [];

          try { localHidden = JSON.parse(localStorage.getItem(localKey) || "[]"); } catch(e){}

          localStorage.setItem(localKey, JSON.stringify(Array.from(new Set([...localHidden, ...otherMsgIds]))));

          const { data: conv } = await sb.from("chat_conversations").select("store_context").eq("conv_id", convId).maybeSingle();

          let sc = conv?.store_context;

          if(!sc || typeof sc !== 'object') sc = {};

          if(!sc.hidden_for || typeof sc.hidden_for !== 'object') sc.hidden_for = {};

          const prev = Array.isArray(sc.hidden_for[myUid]) ? sc.hidden_for[myUid] : [];

          sc.hidden_for[myUid] = Array.from(new Set([...prev, ...otherMsgIds]));

          await sb.from("chat_conversations").update({ store_context: sc }).eq("conv_id", convId);

        }catch(e){}

      }

      // إزالة الرسائل فورياً من الشاشة

      ids.forEach(id => {

        const el = box ? box.querySelector(`[data-msg-id="${id}"]`) : null;

        if(el){

          el.style.transition = "all .25s ease";

          el.style.opacity = "0";

          el.style.transform = "scale(0.8)";

          setTimeout(() => el.remove(), 250);

        }

      });

      cancelChatSelection();

      // تحديث آخر رسالة في المحادثة

      if(convId){

        const { data: latest } = await sb

          .from("chat_messages")

          .select("*")

          .eq("conv_id", convId)

          .order("created_at", { ascending: false })

          .limit(1);

        if(latest && latest.length > 0){

          let preview = latest[0].text;

          if(preview.startsWith("[صورة] ")) preview = "📷 صورة";

          else if(preview.startsWith("[صوت:")) preview = "🎙️ رسالة صوتية";

          await sb.from("chat_conversations").update({

            last_message: preview,

            last_sender_uid: latest[0].sender_uid,

            last_sender_name: latest[0].sender_name,

            updated_at: latest[0].created_at

          }).eq("conv_id", convId);

        } else {

          await sb.from("chat_conversations").update({

            last_message: "تم حذف الرسائل",

            updated_at: Date.now()

          }).eq("conv_id", convId);

        }

      }

      try {

        const cKey = "tasawuq_chat_cache_" + convId;

        const cur = JSON.parse(localStorage.getItem(cKey) || "[]");

        const idSet = new Set(ids.map(Number));

        localStorage.setItem(cKey, JSON.stringify(cur.filter(m => !idSet.has(Number(m.id)))));

      } catch(e){}

      showToast("تم حذف الرسائل من الطرفين بنجاح 🗑️", "success");

    }

    // فحص إذا فرغت المحادثة

    setTimeout(() => {

      if(box && !box.querySelector(".chatBubble")){

        box.innerHTML = `

          <div style="text-align:center;padding:40px 20px;color:var(--muted)">

            <div style="font-size:36px;margin-bottom:8px">💬</div>

            <div style="font-weight:800;font-size:14px;color:var(--text);margin-bottom:4px">لا توجد رسائل سابقة</div>

            <div style="font-size:12px">ابدأ المحادثة الآن واكتب رسالتك بالأسفل!</div>

          </div>`;

      }

    }, 300);

  } catch(err) {

    console.error("خطأ في حذف الرسائل:", err);

    showToast("⚠️ تعذر حذف الرسائل، يرجى المحاولة ثانية", "warn");

  }

}

window.executeDeleteSelectedChatMessages = executeDeleteSelectedChatMessages;

// ============================================================

// 👁️ نظام علامات القراءة الفورية (Read Receipts مثل واتساب وماسنجر)

// ============================================================

window._chatOtherReadTime = 0;

export async function markChatAsRead(convId, myUid){

  if(!convId || !myUid) return;

  try{

    const sb = window.supabase || supabase;

    const { data: conv } = await sb.from("chat_conversations").select("store_context").eq("conv_id", convId).maybeSingle();

    let sc = conv?.store_context;

    if(!sc || typeof sc !== 'object') sc = {};

    if(!sc.read_by || typeof sc.read_by !== 'object') sc.read_by = {};

    const now = Date.now();

    sc.read_by[myUid] = now;

    // 🌟 حاسم: لا نحدث updated_at هنا إطلاقاً! ففتح المحادثة أو قراءتها لا يغير ترتيبها أبداً، الترتيب يتغير فقط عند إرسال أو استقبال رسالة
    await sb.from("chat_conversations").update({ store_context: sc }).eq("conv_id", convId);

  }catch(e){

    console.warn("markChatAsRead error:", e);

  }

}

window.markChatAsRead = markChatAsRead;

function _updateMessagesReadStatus(readTime){

  if(!readTime) return;

  const box = document.getElementById("chatMessagesBox");

  if(!box) return;

  box.querySelectorAll(".chatBubble.outgoing").forEach(b => {

    const msgTime = Number(b.getAttribute("data-created-at")) || 0;

    if(msgTime && msgTime <= (readTime + 5000)){

      const checkEl = b.querySelector(".chatCheck");

      if(checkEl && !checkEl.classList.contains("read")){

        checkEl.className = "chatCheck read";

        checkEl.innerHTML = "✓✓";

        checkEl.setAttribute("title", "تمت القراءة");

      }

    }

  });

}

window._updateMessagesReadStatus = _updateMessagesReadStatus;

function _appendBubble(box, m, myUid, animate, otherReadTimestamp = 0){
  if (!box || !m) return false;

  const msgKey = (m.id ? 'id_' + m.id : '') || ('t_' + (m.created_at || '') + '_' + (m.sender_uid || ''));

  if(box.querySelector('[data-msg-key="' + msgKey + '"]') || (m.id && box.querySelector('[data-msg-id="' + m.id + '"]'))) return false;

  const normText = (m.text || '').trim();
  const msgTime = Number(m.created_at) || Date.now();
  const mSender = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(m.sender_uid) : m.sender_uid;

  // فحص ذكي صارم لمنع تكرار أي فقاعة في الواجهة
  const existingBubbles = box.querySelectorAll('.chatBubble');
  for (let i = existingBubbles.length - 1; i >= 0 && i >= existingBubbles.length - 8; i--) {
    const eb = existingBubbles[i];
    const ebTime = Number(eb.getAttribute('data-created-at')) || 0;
    const ebSender = eb.getAttribute('data-sender-uid');
    const ebCanonSender = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(ebSender) : ebSender;
    const ebText = eb.getAttribute('data-msg-text') || '';
    if (ebCanonSender === mSender && Math.abs(ebTime - msgTime) <= 4000) {
      if (ebText === normText || (m.id && eb.getAttribute('data-msg-id') == m.id)) {
        if (m.id && !eb.getAttribute('data-msg-id')) {
          eb.setAttribute('data-msg-id', m.id);
          eb.setAttribute('data-msg-key', 'id_' + m.id);
        }
        return false;
      }
    }
  }

  const myCandBubble = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(myUid) : [myUid];
  const isMe = myCandBubble.includes(m.sender_uid);

  const d = new Date(msgTime);

  const timeStr = d.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

  const div = document.createElement("div");

  div.className = "chatBubble " + (isMe ? "outgoing" : "incoming");

  if(!isMe){

    div.style.setProperty("background", "#ffffff", "important");

    div.style.setProperty("color", "#0f172a", "important");

    div.style.setProperty("border", "1.5px solid #cbd5e1", "important");

  }

  div.setAttribute("data-msg-key", msgKey);

  if(m.id) div.setAttribute("data-msg-id", m.id);

  div.setAttribute("data-created-at", msgTime);

  div.setAttribute("data-sender-uid", m.sender_uid || (isMe ? myUid : ""));

  div.setAttribute("data-msg-text", normText);

  let bodyHtml = escapeHtml(m.text || '');

  if(m.text && m.text.startsWith("[صورة] ")){

    const imgUrl = m.text.replace("[صورة] ", "").trim();

    bodyHtml = `<a href="${escapeHtml(imgUrl)}" target="_blank" onclick="if(window._chatSelectMode){event.preventDefault();}"><img src="${escapeHtml(imgUrl)}" style="max-width:220px;max-height:220px;border-radius:10px;display:block;margin-bottom:4px;pointer-events:none"></a>`;

  } else if(m.text && m.text.startsWith("[صوت:")){

    const parts = m.text.split("] ");

    const audioSrc = parts.slice(1).join("] ").trim();

    bodyHtml = `

      <div style="display:flex;align-items:center;gap:8px">

        <span style="font-size:20px">🎙️</span>

        <audio controls style="max-width:210px;height:36px;outline:none">

          <source src="${audioSrc}" type="audio/webm">

        </audio>

      </div>`;

  }

  // 👁️ تحديد شكل السهمين: رمادي عند الإرسال (غير مقروء)، وأزرق مضيء ✓✓ عند قراءة المستلم

  let checkHtml = "";

  if(isMe){

    const readLimit = otherReadTimestamp || (window._chatOtherReadTime || 0);

    const isRead = readLimit > 0 && msgTime <= (readLimit + 5000);

    if(isRead){

      checkHtml = '<span class="chatCheck read" title="تمت القراءة">✓✓</span>';

    } else {

      checkHtml = '<span class="chatCheck sent" title="تم الإرسال (غير مقروءة بعد)">✓✓</span>';

    }

  }

  div.innerHTML = `${bodyHtml}<div class="chatTime">${checkHtml}${timeStr}</div>`;

  _attachBubbleEvents(div);

  if(animate){

    div.style.opacity = "0";

    div.style.transform = "translateY(10px)";

  }

  box.appendChild(div);

  if(animate){

    requestAnimationFrame(() => {

      div.style.transition = "all .25s ease";

      div.style.opacity = "1";

      div.style.transform = "none";

    });

  }

  return true;

}

async function _loadChatIntoBox(convId){

  cancelChatSelection();

  const box = document.getElementById("chatMessagesBox");

  if(!box) return;

  const myUid = auth.currentUser ? auth.currentUser.uid : "";

  const sb = window.supabase || supabase;

  try{

    // 1) جلب وقت قراءة الطرف الآخر وقائمة الرسائل المحذوفة من عندي (Delete for me)

    let otherReadTime = 0;

    const hiddenIdsSet = new Set();

    const localKey = "tasawuq_hidden_msgs_" + myUid;

    try {

      const localHidden = JSON.parse(localStorage.getItem(localKey) || "[]");

      localHidden.forEach(id => hiddenIdsSet.add(Number(id)));

    } catch(e){}

    const targetUid = window._activeChat ? window._activeChat.targetUid : null;

    const { data: convData } = await sb.from("chat_conversations").select("store_context").eq("conv_id", convId).maybeSingle();

    if(convData && convData.store_context){

      if(convData.store_context.read_by && targetUid){

        otherReadTime = Number(convData.store_context.read_by[targetUid]) || 0;

      }

      if(convData.store_context.hidden_for && myUid && Array.isArray(convData.store_context.hidden_for[myUid])){

        convData.store_context.hidden_for[myUid].forEach(id => hiddenIdsSet.add(Number(id)));

      }

    }

    window._chatOtherReadTime = otherReadTime;

    // 2) تسجيل أنني قرأت المحادثة الآن

    if(myUid) markChatAsRead(convId, myUid);

    // 3) جلب أحدث 250 رسالة تنازلياً مع شمول كافة معرفات المحادثة المشتركة
    const myCandBox = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(myUid) : [myUid];
    const targetUidBox = window._activeChat ? window._activeChat.targetUid : null;
    const targetCandBox = targetUidBox ? ((typeof window.getCandidateUids === 'function') ? window.getCandidateUids(targetUidBox) : [targetUidBox]) : [];

    const targetConvIds = [convId];
    if(targetCandBox.length > 0){
      myCandBox.forEach(u1 => {
        targetCandBox.forEach(u2 => {
          const cid = [u1, u2].sort().join('_');
          if(!targetConvIds.includes(cid)) targetConvIds.push(cid);
        });
      });
    }

    const { data, error } = await sb

      .from("chat_messages")

      .select("*")

      .in("conv_id", targetConvIds)

      .order("created_at", { ascending: false })

      .limit(250);

    if(error) throw error;

    if(!data || data.length === 0){

      box.innerHTML = `

        <div style="text-align:center;padding:40px 20px;color:var(--muted)">

          <div style="font-size:36px;margin-bottom:8px">💬</div>

          <div style="font-weight:800;font-size:14px;color:var(--text);margin-bottom:4px">لا توجد رسائل سابقة</div>

          <div style="font-size:12px">ابدأ المحادثة الآن واكتب رسالتك بالأسفل!</div>

        </div>`;

      return;

    }

    // عكس الترتيب لعرض الأقدم للأحدث نحو الأسفل
    const sorted = [...data].reverse();
    const seen = new Set();
    const unique = [];

    for(const m of sorted){
      // استثناء الرسائل المحذوفة من عندي (Delete for me)
      if(m.id && hiddenIdsSet.has(Number(m.id))) continue;

      const k = (m.id ? 'id_' + m.id : '') || (m.created_at + '_' + m.text);
      if(seen.has(k)) continue;
      seen.add(k);

      // فحص التكرار الزمني والنصي لمنع إظهار أي رسالة مكررة حتى لو اختلفت معرفاتها
      const normText = (m.text || '').trim();
      const mTime = Number(m.created_at) || 0;
      const mSender = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(m.sender_uid) : m.sender_uid;

      const isDuplicate = unique.some(existing => {
        const existSender = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(existing.sender_uid) : existing.sender_uid;
        const existTime = Number(existing.created_at) || 0;
        const existText = (existing.text || '').trim();
        return existSender === mSender && existText === normText && Math.abs(existTime - mTime) <= 4000;
      });

      if(!isDuplicate){
        unique.push(m);
      }
    }

    box.innerHTML = "";

    unique.forEach(m => _appendBubble(box, m, myUid, false, otherReadTime));

    box.scrollTop = box.scrollHeight;

    try {

      localStorage.setItem("tasawuq_chat_cache_" + convId, JSON.stringify(unique.slice(-80)));

    } catch(e){}

  }catch(err){

    console.error("خطأ في تحميل الرسائل:", err);

    box.innerHTML = `<div class="reportsEmpty">⚠️ تعذر تحميل الرسائل</div>`;

  }

}

let _chatPollInterval = null;

function _unsubscribeChat(){

  if(_chatChannel){

    try{ (window.supabase || supabase).removeChannel(_chatChannel); }catch(e){}

    _chatChannel = null;

  }

  if(_chatPollInterval){

    clearInterval(_chatPollInterval);

    _chatPollInterval = null;

  }

}

export async function openChatWithSeller(sellerUid, postId, storeId, targetCustomName, skipHistory, existingConvId){

  if(!auth.currentUser){

    showToast("يرجى تسجيل الدخول أولاً للدردشة مع البائع 💬", "warn");

    const ao = document.getElementById("authOverlay");

    if(ao) { ao.classList.remove("hidden"); ao.style.zIndex = "2500"; }

    return;

  }

  const myUid = auth.currentUser.uid;
  const canonicalMyUid = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(myUid) : myUid;
  const canonicalSellerUid = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(sellerUid) : sellerUid;

  if(!sellerUid){

    showToast("تعذر تحديد البائع للدردشة معه", "warn");

    return;

  }

  if(canonicalMyUid === canonicalSellerUid){

    showToast("هذا إعلانك أو متجرك، لا يمكنك مراسلة نفسك!", "info");

    return;

  }

  let targetName = targetCustomName || "";

  if (!targetName || targetName === "مستخدم" || targetName === "البائع") {
    targetName = resolveDisplayName(sellerUid, (postId ? allPosts.find(x => x.id === postId) : null), (storeId ? allStores.find(x => x.id === storeId) : null));
  }

  let targetPhone = "";

  if(postId){

    const p = allPosts.find(x => x.id === postId);

    if(p && p.phone) targetPhone = p.phone;

  }

  if(storeId){

    const s = allStores.find(x => x.id === storeId);

    if(s && s.phone) targetPhone = s.phone;

  }

  if(!targetPhone){

    const pOwner = allPosts.find(x => x.uid === sellerUid && x.phone);

    if(pOwner) targetPhone = pOwner.phone;

    else {

      const sOwner = allStores.find(x => (x.ownerUid === sellerUid || x.owner_uid === sellerUid) && x.phone);

      if(sOwner) targetPhone = sOwner.phone;

    }

  }

  let isCurrentUserSeller = false;

  if(postId){

    const p = allPosts.find(x => x.id === postId);

    if(p && (p.uid === myUid || p.uid === canonicalMyUid)) isCurrentUserSeller = true;

  }

  if(storeId){

    const s = allStores.find(x => x.id === storeId);

    if(s && (s.ownerUid === myUid || s.owner_uid === myUid || s.ownerUid === canonicalMyUid)) isCurrentUserSeller = true;

  }

  let convId = chatConvId(canonicalMyUid, canonicalSellerUid);

  window._chatTargetUid = sellerUid;
  window._activeChat = { convId, targetUid: sellerUid, targetName, targetPhone, postId: postId || null, storeId: storeId || null, isSeller: isCurrentUserSeller };

  const callBtn = document.getElementById("chatHeaderCallBtn");

  const waBtn = document.getElementById("chatHeaderWaBtn");

  if(callBtn) callBtn.style.display = "inline-flex";

  if(waBtn) waBtn.style.display = targetPhone ? "inline-flex" : "none";

  renderChatQuickReplies(isCurrentUserSeller);

  const elName = document.getElementById("chatTargetName");

  const elAvatar = document.getElementById("chatTargetAvatar");

  if(elName) elName.textContent = targetName;

  // جلب وتعيين صورة الطرف الآخر إن وجدت

  let targetAvatarUrl = (typeof window.getSafeSellerAvatar === 'function') ? window.getSafeSellerAvatar(sellerUid) : (localStorage.getItem("tasawuq_avatar_" + sellerUid) || "");
  if (!isAbdoUser(sellerUid) && typeof isAbdoMedia === 'function' && isAbdoMedia(targetAvatarUrl)) targetAvatarUrl = "";

  if(elAvatar){

    if(targetAvatarUrl){

      elAvatar.innerHTML = `<img src="${escapeHtml(targetAvatarUrl)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;

    } else {

      elAvatar.textContent = targetName ? targetName.trim()[0].toUpperCase() : "👤";

      // فحص سريع من قاعدة البيانات لصورة الطرف الآخر

      getDoc(doc(db, "profiles", sellerUid)).then(snap => {

        let av = (snap.exists() && snap.data().avatar) ? snap.data().avatar : null;
        if (!isAbdoUser(sellerUid) && typeof isAbdoMedia === 'function' && isAbdoMedia(av)) av = null;

        if(av){

          localStorage.setItem("tasawuq_avatar_" + sellerUid, av);

          if(window._activeChat && window._activeChat.targetUid === sellerUid && elAvatar){

            elAvatar.innerHTML = `<img src="${escapeHtml(av)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;

          }

        } else {

          const sb = window.supabase || supabase;

          if(sb){

            sb.from("feedback").select("message").eq("id", "avatar_" + sellerUid).maybeSingle().then(res => {

              if(res && res.data && res.data.message){

                const avFb = res.data.message;
                if (!isAbdoUser(sellerUid) && typeof isAbdoMedia === 'function' && isAbdoMedia(avFb)) return;

                localStorage.setItem("tasawuq_avatar_" + sellerUid, avFb);

                if(window._activeChat && window._activeChat.targetUid === sellerUid && elAvatar){

                  elAvatar.innerHTML = `<img src="${escapeHtml(avFb)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%">`;

                }

              }

            }).catch(()=>{});

          }

        }

      }).catch(()=>{});

    }

  }

  const ctxBar = document.getElementById("chatPostContextBar");

  const ctxImg = document.getElementById("chatContextImg");

  const ctxTitle = document.getElementById("chatContextTitle");

  const ctxPrice = document.getElementById("chatContextPrice");

  const ctxBtn = document.getElementById("chatContextViewBtn");

  if(ctxBar){

    if(postId){

      const p = allPosts.find(x => x.id === postId);

      if(p){

        ctxBar.style.display = "flex";

        const imgs = getImages(p);

        if(ctxImg) ctxImg.src = imgs[0] || "icon-192.png";

        if(ctxTitle) ctxTitle.textContent = p.title || "إعلان";

        if(ctxPrice) ctxPrice.textContent = p.priceType === "contact" ? "تواصل للسعر" : (p.price != null ? formatPrice(p.price) + " د.ل" : "");

        if(ctxBtn) ctxBtn.onclick = () => { closeUserChat(); openPost(p.id); };

      }else ctxBar.style.display = "none";

    }else if(storeId){

      const s = allStores.find(x => x.id === storeId);

      if(s){

        ctxBar.style.display = "flex";

        if(ctxImg) ctxImg.src = s.logo || "icon-192.png";

        if(ctxTitle) ctxTitle.textContent = s.name || "متجر";

        if(ctxPrice) ctxPrice.textContent = s.category || "";

        if(ctxBtn) ctxBtn.onclick = () => { closeUserChat(); openStore(s.id); };

      }else ctxBar.style.display = "none";

    }else ctxBar.style.display = "none";

  }

  const inboxEl = document.getElementById("userInboxOverlay");
  const wasInboxOpen = inboxEl && !inboxEl.classList.contains("hidden");
  window._chatOpenedFromInbox = !!wasInboxOpen;

  const chatOverlay = document.getElementById("userChatOverlay");

  if(chatOverlay) {

    chatOverlay.classList.remove("hidden");

    chatOverlay.style.zIndex = "6000";

  }

  if (typeof resetVoiceRecordingUI === 'function') resetVoiceRecordingUI();

  if(typeof closeInboxDirect === "function") closeInboxDirect();
  else if(typeof closeInbox === "function") closeInbox(true);

  if(!skipHistory && typeof pushNavState === 'function') {

    pushNavState({ screen: 'chat', convId: convId }, '#chat-' + convId);

  }

  const box = document.getElementById("chatMessagesBox");

  let hasCachedMsgs = false;

  if(box){

    try {

      const cachedRaw = localStorage.getItem("tasawuq_chat_cache_" + convId);

      if(cachedRaw){

        const cachedList = JSON.parse(cachedRaw);

        if(Array.isArray(cachedList) && cachedList.length > 0){

          box.innerHTML = "";

          cachedList.forEach(m => _appendBubble(box, m, myUid, false, window._chatOtherReadTime || 0));

          box.scrollTop = box.scrollHeight;

          hasCachedMsgs = true;

        }

      }

    } catch(e){}

    if(!hasCachedMsgs){

      box.innerHTML = `

        <div style="text-align:center;padding:50px 20px;color:var(--muted)">

          <div style="font-size:32px;margin-bottom:8px">⏳</div>

          <div style="font-weight:800;font-size:14px;color:var(--text)">جاري فتح المحادثة...</div>

        </div>`;

    }

  }

  setTimeout(() => {

    const input = document.getElementById("chatMessageInput");

    if(input) input.focus();

  }, 100);

  await _loadChatIntoBox(convId);

  // ✅ التحديث الفوري: Realtime عبر WebSocket
  _unsubscribeChat();

  const myCandUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(myUid) : [myUid];
  const targetCandUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(canonicalSellerUid) : [canonicalSellerUid];
  const activeRoomIds = [convId];
  myCandUids.forEach(u1 => {
    targetCandUids.forEach(u2 => {
      const cid = [u1, u2].sort().join('_');
      if(!activeRoomIds.includes(cid)) activeRoomIds.push(cid);
    });
  });

  const sb = window.supabase || supabase;

  _chatChannel = sb
    .channel("chat:" + convId)
    .on("postgres_changes",
      { event: "INSERT", schema: "public", table: "chat_messages" },
      payload => {
        const box = document.getElementById("chatMessagesBox");
        if(!box || !window._activeChat) return;
        if(!activeRoomIds.includes(payload.new.conv_id)) return;

        // 🔒 منع تكرار الرسائل نهائياً (Deduplication Guard)
        if(payload.new.id && (box.querySelector(`[data-msg-id="${payload.new.id}"]`) || box.querySelector(`[data-msg-key="id_${payload.new.id}"]`))) return;

        const myUid2 = auth.currentUser ? auth.currentUser.uid : "";
        const myCandBubble = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(myUid2) : [myUid2];
        const isMe = myCandBubble.includes(payload.new.sender_uid);

        if(isMe){
          const normText = (payload.new.text || '').trim();
          const pTime = Number(payload.new.created_at) || 0;

          // نبحث أولاً عن أي فقاعة مؤقتة، أو أي فقاعة مرسلة سابقة بنفس النص لمنع التكرار نهائياً
          let matchedBubble = box.querySelector('[data-temp="1"]');
          if(!matchedBubble){
            const outgoingBubbles = box.querySelectorAll('.chatBubble.outgoing');
            for(let i = outgoingBubbles.length - 1; i >= 0; i--){
              const b = outgoingBubbles[i];
              if(b.getAttribute('data-msg-id') == payload.new.id) return; // موجودة بالفعل
              const bText = (b.getAttribute('data-msg-text') || b.textContent || '').trim();
              const bTime = Number(b.getAttribute('data-created-at')) || 0;
              if(bText && (bText === normText || bText.includes(normText) || normText.includes(bText))){
                if(!b.getAttribute('data-msg-id') || (pTime && bTime && Math.abs(pTime - bTime) < 20000)){
                  matchedBubble = b;
                  break;
                }
              }
            }
          }

          if(matchedBubble){
            matchedBubble.removeAttribute("data-temp");
            matchedBubble.style.opacity = "1";
            matchedBubble.style.transition = "";
            matchedBubble.style.transform = "none";
            if(payload.new.id){
              matchedBubble.setAttribute("data-msg-key", 'id_' + payload.new.id);
              matchedBubble.setAttribute("data-msg-id", String(payload.new.id));
              _attachBubbleEvents(matchedBubble);
            }
            const tEl = matchedBubble.querySelector(".chatTime");
            if(tEl){
              const msgTime = Number(payload.new.created_at) || Date.now();
              const timeStr = new Date(msgTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
              tEl.innerHTML = '<span class="chatCheck sent" title="تم الإرسال">✓✓</span>' + timeStr;
            }
            return; // ⛔ نخرج فوراً لمنع إضافة فقاعة ثانية
          }
        }

        const emptyNotice = box.querySelector(".reportsEmpty, div[style*='text-align:center']");
        if(emptyNotice) box.innerHTML = "";

        _appendBubble(box, payload.new, myUid2, !isMe);
        box.scrollTop = box.scrollHeight;

        try {

          const cKey = "tasawuq_chat_cache_" + convId;

          const cur = JSON.parse(localStorage.getItem(cKey) || "[]");

          cur.push(payload.new);

          localStorage.setItem(cKey, JSON.stringify(cur.slice(-80)));

        } catch(e){}

      })

    .on("postgres_changes",

      { event: "DELETE", schema: "public", table: "chat_messages" },

      payload => {

        const box = document.getElementById("chatMessagesBox");

        if(!box || !window._activeChat || window._activeChat.convId !== convId) return;

        const delId = payload.old ? payload.old.id : null;

        if(delId){

          const target = box.querySelector(`[data-msg-id="${delId}"]`);

          if(target){

            target.style.transition = "all .25s ease";

            target.style.opacity = "0";

            target.style.transform = "scale(0.8)";

            setTimeout(() => {

              target.remove();

              if(!box.querySelector(".chatBubble")){

                box.innerHTML = `

                  <div style="text-align:center;padding:40px 20px;color:var(--muted)">

                    <div style="font-size:36px;margin-bottom:8px">💬</div>

                    <div style="font-weight:800;font-size:14px;color:var(--text);margin-bottom:4px">لا توجد رسائل سابقة</div>

                    <div style="font-size:12px">ابدأ المحادثة الآن واكتب رسالتك بالأسفل!</div>

                  </div>`;

              }

            }, 250);

          }

        }

      })

    .on("postgres_changes",

      { event: "UPDATE", schema: "public", table: "chat_conversations" },

      payload => {

        if(!payload.new || payload.new.conv_id !== convId) return;

        const sc = payload.new.store_context;

        const targetUid = window._activeChat ? window._activeChat.targetUid : null;

        if(sc && sc.read_by && targetUid && sc.read_by[targetUid]){

          const newReadTime = Number(sc.read_by[targetUid]);

          window._chatOtherReadTime = newReadTime;

          _updateMessagesReadStatus(newReadTime);

        }

      })

    .subscribe();

  // فحص احتياطي سريع كل 1.5 ثانية لتحديث علامات القراءة الفورية

  _chatPollInterval = setInterval(async () => {

    if(!window._activeChat || window._activeChat.convId !== convId) {

      clearInterval(_chatPollInterval);

      return;

    }

    const box = document.getElementById("chatMessagesBox");

    if(!box) return;

    try {

      const { data: latestMsgs } = await sb

        .from("chat_messages")

        .select("*")

        .in("conv_id", activeRoomIds)

        .order("created_at", { ascending: false })

        .limit(10);

      if(latestMsgs && latestMsgs.length > 0){

        const myUid2 = auth.currentUser ? auth.currentUser.uid : "";

        let hasNew = false;

        const rev = [...latestMsgs].reverse();

        rev.forEach(m => {
          const k = (m.id ? 'id_' + m.id : '') || ('t_' + (m.created_at || '') + '_' + (m.sender_uid || ''));
          const normText = (m.text || '').trim();
          const tempEl = box.querySelector(`[data-temp="1"][data-msg-text="${escapeHtml(normText)}"]`) || box.querySelector('[data-temp="1"]');
          if (tempEl) {
            tempEl.removeAttribute("data-temp");
            tempEl.style.opacity = "1";
            tempEl.setAttribute("data-msg-key", k);
            if (m.id) tempEl.setAttribute("data-msg-id", m.id);
            _attachBubbleEvents(tempEl);
            const tEl = tempEl.querySelector(".chatTime");
            if (tEl) {
              const msgTime = Number(m.created_at) || Date.now();
              const timeStr = new Date(msgTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
              tEl.innerHTML = '<span class="chatCheck sent" title="تم الإرسال">✓✓</span>' + timeStr;
            }
            return;
          }
          if(!box.querySelector('[data-msg-key="' + k + '"]') && (!m.id || !box.querySelector(`[data-msg-id="${m.id}"]`))){
            if(_appendBubble(box, m, myUid2, false)){
              hasNew = true;
            }
          }
        });

        if(hasNew) box.scrollTop = box.scrollHeight;

      }

      // فحص إذا قرأ الطرف الآخر الرسائل وتحديث الأسهم إلى زرقاء ✓✓

      if(window._activeChat && window._activeChat.targetUid){

        const { data: convCheck } = await sb.from("chat_conversations").select("store_context").eq("conv_id", convId).maybeSingle();

        if(convCheck && convCheck.store_context && convCheck.store_context.read_by){

          const rt = Number(convCheck.store_context.read_by[window._activeChat.targetUid]) || 0;

          if(rt > (window._chatOtherReadTime || 0)){

            window._chatOtherReadTime = rt;

            _updateMessagesReadStatus(rt);

          }

        }

      }

      // فحص الرسائل المحذوفة من الطرف الآخر وإزالتها

      const visibleBubbles = box.querySelectorAll('.chatBubble[data-msg-id]');

      if(visibleBubbles.length > 0){

        const { data: allActive } = await sb

          .from("chat_messages")

          .select("id")

          .in("conv_id", activeRoomIds);

        if(allActive){

          const activeSet = new Set(allActive.map(x => String(x.id)));

          let removedAny = false;

          visibleBubbles.forEach(b => {

            const bId = b.getAttribute("data-msg-id");

            if(bId && !activeSet.has(bId)){

              removedAny = true;

              b.remove();

            }

          });

          if(removedAny && !box.querySelector(".chatBubble")){

            box.innerHTML = `

              <div style="text-align:center;padding:40px 20px;color:var(--muted)">

                <div style="font-size:36px;margin-bottom:8px">💬</div>

                <div style="font-weight:800;font-size:14px;color:var(--text);margin-bottom:4px">لا توجد رسائل سابقة</div>

                <div style="font-size:12px">ابدأ المحادثة الآن واكتب رسالتك بالأسفل!</div>

              </div>`;

          }

        }

      }

    }catch(e){}

  }, 2500);

}

export async function sendUserChatMessage(){

  if(!window._activeChat) return;

  if(!auth.currentUser){

    showToast("يرجى تسجيل الدخول أولاً لإرسال الرسالة", "warn");

    return;

  }

  const input = document.getElementById("chatMessageInput");

  if(!input) return;

  const text = (input.value || "").trim();

  if(!text) return;

  // 🛡️ حماية ضد الإغراق والرسائل المزعجة (Anti-Spam Rate Limit)

  const now = Date.now();

  if(window._lastChatSendTime && (now - window._lastChatSendTime < 1000)){

    showToast("⏳ يرجى التمهل قليلاً قبل إرسال رسالة أخرى", "warn");

    return;

  }

  window._lastChatSendTime = now;

  const me = auth.currentUser;
  const canonicalMyUid = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(me.uid) : me.uid;
  const activeChat = window._activeChat;
  const canonicalTargetUid = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(activeChat.targetUid) : activeChat.targetUid;

  const senderName = (myProfile && myProfile.name) || me.displayName || localStorage.getItem("tasawuq_my_name") || "أنا";

  const convId = activeChat.convId || chatConvId(canonicalMyUid, canonicalTargetUid);

  // 🚀 تصعيد المحادثة فورياً لأول القائمة مثل واتساب وإنستغرام
  _onConversationUpdated({
    conv_id: convId,
    p1: [canonicalMyUid, canonicalTargetUid].sort()[0],
    p2: [canonicalMyUid, canonicalTargetUid].sort()[1],
    participant_uids: [canonicalMyUid, canonicalTargetUid],
    last_message: text,
    last_sender_uid: canonicalMyUid,
    last_sender_name: senderName,
    updated_at: now
  });

  input.value = "";

  resetVoiceRecordingUI();

  input.focus();

  // عرض فوري مؤقت (يتم تأكيده بسلاسة دون حذف أو اختفاء أو قفزات)

  const box = document.getElementById("chatMessagesBox");

  let tempBubble = null;

  if(box){

    const emptyNotice = box.querySelector(".reportsEmpty, div[style*='text-align:center']");

    if(emptyNotice) box.innerHTML = "";

    tempBubble = document.createElement("div");

    tempBubble.className = "chatBubble outgoing";

    tempBubble.setAttribute("data-temp", "1");
    tempBubble.setAttribute("data-msg-text", text.trim());
    tempBubble.setAttribute("data-created-at", now);
    tempBubble.setAttribute("data-sender-uid", canonicalMyUid);

    tempBubble.style.opacity = ".85";

    tempBubble.innerHTML = `${escapeHtml(text)}<div class="chatTime"><span class="chatCheck sent" style="opacity:0.6">✓</span>جارٍ الإرسال...</div>`;

    box.appendChild(tempBubble);

    box.scrollTop = box.scrollHeight;

  }

  const sb = window.supabase || supabase;

  try{

    // 1) حفظ الرسالة في جدول الرسائل المخصص

    const { data: insertedMsg, error: msgErr } = await sb.from("chat_messages").insert({

      conv_id: convId,

      sender_uid: canonicalMyUid,

      sender_name: senderName,

      receiver_uid: canonicalTargetUid,

      text: text,

      post_id: activeChat.postId,

      store_id: activeChat.storeId,

      created_at: now

    }).select().single();

    if(msgErr) throw msgErr;

    // 🔔 إرسال إشعار فوري (Push Notification) لهاتف المستلم حتى لو كان هاتفه مقفلاً

    dispatchChatPushNotification(activeChat.targetUid, senderName, text, convId);

    // حفظ الرسالة في الكاش المحلي فوراً للسرعة اللحظية

    if(insertedMsg){

      try {

        const cKey = "tasawuq_chat_cache_" + convId;

        const cur = JSON.parse(localStorage.getItem(cKey) || "[]");

        cur.push(insertedMsg);

        localStorage.setItem(cKey, JSON.stringify(cur.slice(-80)));

      } catch(e){}

    }

    // تأكيد الحفظ فوراً على الفقاعة حتى لا تظل معلقة

    if(tempBubble){

      tempBubble.removeAttribute("data-temp");

      tempBubble.style.opacity = "1";

      if(insertedMsg && insertedMsg.id){

        tempBubble.setAttribute("data-msg-key", 'id_' + insertedMsg.id);

        tempBubble.setAttribute("data-msg-id", insertedMsg.id);

        _attachBubbleEvents(tempBubble);

      }

      const tEl = tempBubble.querySelector(".chatTime");

      if(tEl){

        tEl.innerHTML = '<span class="chatCheck sent" title="تم الإرسال (غير مقروءة بعد)">✓✓</span>' + new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

      }

    }

    // 2) تحديث ملخص المحادثة (مع الحفاظ على read_by وجميع البيانات السابقة)

    const postTitle = document.getElementById("chatContextTitle")?.textContent || "";

    const postPrice = document.getElementById("chatContextPrice")?.textContent || "";

    const postImage = document.getElementById("chatContextImg")?.src || "";

    const p1 = [canonicalMyUid, canonicalTargetUid].sort()[0];

    const p2 = [canonicalMyUid, canonicalTargetUid].sort()[1];

    let sc = {};

    try {

      const { data: curConv } = await sb.from("chat_conversations").select("store_context").eq("conv_id", convId).maybeSingle();

      if(curConv && curConv.store_context && typeof curConv.store_context === 'object'){

        sc = { ...curConv.store_context };

      }

    } catch(e){}

    if(activeChat.storeId){

      sc.id = activeChat.storeId;

      sc.name = postTitle;

    }

    if(!sc.read_by || typeof sc.read_by !== 'object') sc.read_by = {};

    sc.read_by[me.uid] = now; // المرسل قرأ حتى هذه اللحظة

    const { error: convErr } = await sb.from("chat_conversations").upsert({

      conv_id: convId,

      p1: p1,

      p2: p2,

      participant_uids: [me.uid, activeChat.targetUid],

      last_message: text,

      last_sender_uid: me.uid,

      last_sender_name: senderName,

      updated_at: now,

      post_context: activeChat.postId ? { id: activeChat.postId, title: postTitle, price: postPrice, image: postImage } : null,

      store_context: sc

    });

    if(convErr) console.warn("تعذر تحديث ملخص المحادثة:", convErr);

    // ✅ لا ننتظر إعادة تحميل — الـ Realtime سيرسل الرسالة للطرفين فوراً

  }catch(err){

    console.error("فشل إرسال الرسالة:", err);

    if(tempBubble) tempBubble.remove();

    showToast("تعذر إرسال الرسالة: " + (err.message || err) + " — تحقق من الاتصال", "error");

  }

}

export function closeUserChat(skipHistory){

  if(!skipHistory && !_isHistoryNavigating && window.history.state && window.history.state.screen === 'chat'){

    window.history.back();

    return;

  }

  closeUserChatDirect();

}

export function closeUserChatDirect(){

  cancelChatSelection();

  const chatOverlay = document.getElementById("userChatOverlay");

  if(chatOverlay) {

    chatOverlay.classList.add("hidden");

    chatOverlay.style.zIndex = "";

  }

  _unsubscribeChat();

  window._activeChat = null;

  // 🌟 التنقل الذكي المطابق للواتساب وإنستغرام:
  // إذا كان المستخدم قد دخل المحادثة من قائمة الرسائل، يرجع إليها
  // أما إذا دخل من إعلان أو متجر أو حساب شخص أو من الواجهة، فيخرج مباشرة للشاشة السابقة/الرئيسي ولا يفتح الرسائل!
  if (window._chatOpenedFromInbox) {
    window._chatOpenedFromInbox = false;
    if (typeof openInbox === 'function') {
      openInbox(true);
    }
  } else {
    // التأكد الحاسم من إغلاق شاشة الرسائل لكي لا تظهر في الخلفية نهائياً
    if (typeof closeInboxDirect === 'function') closeInboxDirect();
    else {
      const uio = document.getElementById("userInboxOverlay");
      if (uio) { uio.classList.add("hidden"); uio.style.zIndex = ""; }
    }
  }

}

// 🌟 تحديث ترتيب المحادثات في الوقت الفعلي: الذي ترسل له رسالة أو تصلك منه رسالة يصعد لأول القائمة فوراً
export function _onConversationUpdated(convData) {
  if (!convData || !convData.conv_id) return;
  const myUid = (typeof auth !== 'undefined' && auth && auth.currentUser) ? auth.currentUser.uid : null;
  if (!myUid) return;

  const now = Number(convData.updated_at) || Date.now();

  // 1) تحديث الكاش المخزن محلياً لضمان عدم ظهور ترتيب قديم عند فتح المحادثات
  try {
    const listKey = "tasawuq_inbox_list_" + myUid;
    let list = JSON.parse(localStorage.getItem(listKey) || "[]");
    const idx = list.findIndex(c => c.conv_id === convData.conv_id);
    let item = { conv_id: convData.conv_id, ...convData, updated_at: now };
    if (idx !== -1) {
      item = { ...list[idx], ...convData, updated_at: now };
      list.splice(idx, 1);
    }
    // وضع المحادثة في رأس القائمة فوراً
    list.unshift(item);
    list.sort((a, b) => (Number(b.updated_at) || 0) - (Number(a.updated_at) || 0));
    localStorage.setItem(listKey, JSON.stringify(list));
    localStorage.removeItem("tasawuq_inbox_cache_" + myUid);
  } catch(e){}

  // 2) التحديث الفوري في الواجهة (DOM) إذا كانت شاشة الرسائل مفتوحة
  const container = document.getElementById("userInboxList");
  if (container) {
    const row = container.querySelector(`[data-conv-id="${convData.conv_id}"]`);
    if (row) {
      const msgEl = row.querySelector(".inboxLastMsg");
      if (msgEl) {
        const isMe = convData.last_sender_uid === myUid;
        msgEl.innerHTML = (isMe ? '<span style="color:#0284c7;font-weight:700">أنت: </span>' : '') + escapeHtml(convData.last_message || '');
      }
      const timeEl = row.querySelector(".inboxTime");
      if (timeEl) timeEl.textContent = "الآن";

      // نقل العنصر إلى أول القائمة فوراً مثل واتساب وانستغرام
      container.prepend(row);

      row.style.transition = "background-color 0.4s ease";
      const origBg = row.style.backgroundColor;
      row.style.backgroundColor = "rgba(2, 132, 199, 0.12)";
      setTimeout(() => { row.style.backgroundColor = origBg; }, 700);
    } else {
      if (typeof openInbox === 'function' && !document.getElementById("userInboxOverlay")?.classList.contains("hidden")) {
        openInbox(true);
      }
    }
  }
}
window._onConversationUpdated = _onConversationUpdated;

export async function openInbox(skipHistory){

  const overlay = document.getElementById("userInboxOverlay");

  const list = document.getElementById("userInboxList");

  if(!overlay || !list) return;

  overlay.classList.remove("hidden");
  overlay.style.zIndex = "4500";

  if (!skipHistory && typeof pushNavState === 'function') {
    pushNavState({ screen: 'inbox' }, '#inbox');
  }

  // 🧹 تنظيف كاش صندوق الرسائل القديم لضمان تطبيق الترتيب الصحيح الحقيقي 100%
  try {
    if (localStorage.getItem("tasawuq_inbox_v") !== "212") {
      const myId = (typeof auth !== 'undefined' && auth && auth.currentUser) ? auth.currentUser.uid : "";
      if (myId) {
        localStorage.removeItem("tasawuq_inbox_cache_" + myId);
        localStorage.removeItem("tasawuq_inbox_list_" + myId);
      }
      localStorage.setItem("tasawuq_inbox_v", "212");
    }
  } catch(e){}

  if(!auth.currentUser){

    list.innerHTML = `

      <div style="text-align:center;padding:40px 20px;background:var(--card);border-radius:16px;border:1px solid var(--border);margin-top:20px">

        <div style="font-size:48px;margin-bottom:12px">💬</div>

        <h4 style="margin:0 0 8px;font-size:17px;color:var(--text);font-weight:900">صندوق الرسائل والمحادثات</h4>

        <p style="font-size:13px;color:var(--muted);margin:0 0 16px">سجّل دخولك الآن للتواصل المباشر مع البائعين والمشترين ومتابعة محادثاتك الفورية</p>

        <button onclick="document.getElementById('userInboxOverlay').classList.add('hidden');openAccount();" class="btnMain" style="max-width:220px;margin:0 auto">🔑 تسجيل الدخول</button>

      </div>

    `;

    return;

  }

  const myUid = auth.currentUser.uid;

  let hasCachedInbox = false;

  try {

    const cachedHtml = localStorage.getItem("tasawuq_inbox_cache_" + myUid);

    if(cachedHtml && cachedHtml.trim()){

      list.innerHTML = cachedHtml;

      hasCachedInbox = true;

    }

  } catch(e){}

  if(!hasCachedInbox){

    list.innerHTML = `<div class="reportsEmpty">⏳ جاري تحميل المحادثات...</div>`;

  }

  try{

    localStorage.setItem("tasawuq_chat_last_seen", String(Date.now()));

    updateGlobalUnreadChatCount();

    const sb = window.supabase || supabase;

    const myCandUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(myUid) : [myUid];
    const orParts = myCandUids.flatMap(u => [`p1.eq.${u}`, `p2.eq.${u}`]).join(',');

    const { data: convs, error } = await sb

      .from("chat_conversations")

      .select("*")

      .or(orParts)

      .order("updated_at", { ascending: false })

      .limit(50);

    if(error) throw error;

    const localKey = "tasawuq_deleted_convs_" + myUid;

    let localDeleted = [];

    try { localDeleted = JSON.parse(localStorage.getItem(localKey) || "[]"); } catch(e){}

    const deletedSet = new Set(localDeleted);

    const activeConvs = [];
    const seenOtherUids = new Set();
    (convs || []).forEach(c => {
      if(deletedSet.has(c.conv_id)) return;
      if(c.store_context && c.store_context.deleted_by && c.store_context.deleted_by[myUid]) return;

      const rawOther = myCandUids.includes(c.p1) ? c.p2 : c.p1;
      const canonicalOther = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(rawOther) : rawOther;
      if(seenOtherUids.has(canonicalOther)) return;
      seenOtherUids.add(canonicalOther);
      activeConvs.push(c);
    });

    // 🌟 الترتيب الفوري الحاسم: الأحدث رسالة يكون أول محادثة في القمة تماماً مثل واتساب وإنستغرام
    activeConvs.sort((a, b) => {
      const timeA = Number(a.updated_at) || 0;
      const timeB = Number(b.updated_at) || 0;
      return timeB - timeA;
    });

    if(!activeConvs || activeConvs.length === 0){

      list.innerHTML = `

        <div style="text-align:center;padding:40px 20px;color:var(--muted)">

          <div style="font-size:42px;margin-bottom:8px">📭</div>

          <div style="font-weight:800;font-size:15px;color:var(--text);margin-bottom:6px">صندوق الرسائل فارغ</div>

          <div style="font-size:12px;margin-bottom:14px">لم تبدأ أي محادثة مع أي بائع أو مشترٍ بعد.</div>

          <button class="btnMain" style="margin:auto;max-width:200px;font-size:13px;padding:10px" onclick="closeInbox()">تصفح الإعلانات الآن</button>

        </div>`;

      return;

    }

    // 1) جمع معرّفات جميع الأطراف الأخرى في المحادثات

    const uniqueOtherUids = Array.from(new Set(activeConvs.map(c => c.p1 === myUid ? c.p2 : c.p1).filter(Boolean)));

    const profilesMap = {};

    // فحص الكاش المحلي أولاً للسرعة اللحظية

    uniqueOtherUids.forEach(uid => {

      const cachedAv = (typeof window.getSafeSellerAvatar === 'function') ? window.getSafeSellerAvatar(uid) : (localStorage.getItem("tasawuq_avatar_" + uid) || "");

      const cachedName = localStorage.getItem("tasawuq_name_" + uid);

      if (cachedAv || cachedName) {

        profilesMap[uid] = { avatar: cachedAv || "", name: cachedName || "" };

      }

    });

    // 2) جلب الملفات الشخصية الحقيقية (الاسم، اليوزر، الصورة) دفعة واحدة

    try {

      const { data: profs } = await sb

        .from("profiles")

        .select("*")

        .in("id", uniqueOtherUids);

      if (profs && profs.length) {

        profs.forEach(p => {

          profilesMap[p.id] = { ...(profilesMap[p.id] || {}), ...p };

          if (p.avatar) try { localStorage.setItem("tasawuq_avatar_" + p.id, p.avatar); } catch(e){}

          if (p.name) try { localStorage.setItem("tasawuq_name_" + p.id, p.name); } catch(e){}

        });

      }

    } catch(e) {}

    // للملفات المتبقية (إن وجدت)، جلبها بالتوازي من فايرستور

    const missingUids = uniqueOtherUids.filter(uid => !profilesMap[uid] || !profilesMap[uid].name);

    if (missingUids.length > 0) {

      await Promise.all(missingUids.map(async (uid) => {

        try {

          const snap = await getDoc(doc(db, "profiles", uid));

          if (snap && snap.exists()) {

            const d = snap.data();

            profilesMap[uid] = { ...(profilesMap[uid] || {}), id: uid, name: d.name, username: d.username, avatar: d.avatar };

            if (d.avatar) try { localStorage.setItem("tasawuq_avatar_" + uid, d.avatar); } catch(e){}

            if (d.name) try { localStorage.setItem("tasawuq_name_" + uid, d.name); } catch(e){}

          }

        } catch(e) {}

      }));

    }

    const freshInboxHtml = activeConvs.map(c => {

      const otherUid = myCandUids.includes(c.p1) ? c.p2 : c.p1;

      const prof = profilesMap[otherUid] || {};

      // الاسم الحقيقي للطرف الآخر (بدون عنوان الإعلان ولا كلمة بائع)

      let otherName = "";

      if (prof.name && prof.name.trim()) {

        otherName = prof.name.trim();

      } else if (prof.username && prof.username.trim()) {

        otherName = "@" + prof.username.trim();

      } else if (c.last_sender_uid !== myUid && c.last_sender_name && c.last_sender_name !== "البائع") {

        otherName = c.last_sender_name;

      } else {

        const s = allStores.find(x => x.ownerUid === otherUid || x.owner_uid === otherUid);

        if (s && s.name) otherName = s.name;

        else {

          const p = allPosts.find(x => x.uid === otherUid && x.sellerName && x.sellerName !== "البائع");

          if (p) otherName = p.sellerName;

        }

      }

      if (!otherName || otherName === "مستخدم") otherName = resolveDisplayName(otherUid);

      // الصورة الشخصية الحقيقية (أو الحرف كحل أخير)

      const avUrl = (typeof window.getSafeSellerAvatar === 'function') ? window.getSafeSellerAvatar(otherUid, prof.avatar) : (prof.avatar || "");

      const initial = otherName ? otherName.trim()[0].toUpperCase() : '👤';

      const avatarHtml = avUrl

        ? `<img src="${escapeHtml(avUrl)}" alt="${escapeHtml(otherName)}" style="width:100%;height:100%;object-fit:cover;border-radius:50%" loading="lazy" onerror="this.parentElement.innerHTML='${initial}'">`

        : initial;

      // سياق الإعلان أو المتجر يظهر كوسم منفصل أنيق تحت الاسم

      const postTag = (c.post_context && c.post_context.title) ? `<span style="font-size:11px;color:#0284c7;background:#f0f9ff;padding:2px 7px;border-radius:6px;border:1px solid #bae6fd;display:inline-flex;align-items:center;gap:3px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">📦 ${escapeHtml(c.post_context.title)}</span>` : '';

      const storeTag = (c.store_context && c.store_context.name) ? `<span style="font-size:11px;color:#16a34a;background:#f0fdf4;padding:2px 7px;border-radius:6px;border:1px solid #bbf7d0;display:inline-flex;align-items:center;gap:3px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">🏪 ${escapeHtml(c.store_context.name)}</span>` : '';

      const tagHtml = postTag || storeTag;

      const lastSeenTxt = c.last_message || '';

      const unameSub = (prof.username && prof.name && prof.username !== prof.name) ? `<span style="font-size:11.5px;color:#0284c7;font-weight:600;margin-right:6px">@${escapeHtml(prof.username)}</span>` : '';

      return `

        <div class="inboxRow" data-conv-id="${escapeHtml(c.conv_id || '')}" data-uid="${escapeHtml(otherUid || '')}" data-post-id="${escapeHtml((c.post_context && c.post_context.id) || '')}" data-store-id="${escapeHtml((c.store_context && c.store_context.id) || '')}" data-name="${escapeHtml(otherName)}" onclick="openChatWithSeller(this.dataset.uid, this.dataset.postId, this.dataset.storeId, this.dataset.name, false, this.dataset.convId)">

          <div class="inboxAvatar">${avatarHtml}</div>

          <div style="flex:1;min-width:0">

            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:3px">

              <div style="font-weight:800;font-size:14px;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:flex;align-items:center;gap:4px">

                <span>${escapeHtml(otherName)}</span>

                ${unameSub}

              </div>

              <div class="inboxTime" style="font-size:11px;color:var(--muted);white-space:nowrap">${timeAgo(c.updated_at)}</div>

            </div>

            ${tagHtml ? `<div style="margin-bottom:4px">${tagHtml}</div>` : ''}

            <div class="inboxLastMsg" style="font-size:12.5px;color:var(--muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">

              ${myCandUids.includes(c.last_sender_uid) ? '<span style="color:#0284c7;font-weight:700">أنت: </span>' : ''}${escapeHtml(lastSeenTxt)}

            </div>

          </div>

          <button type="button" onclick="event.stopPropagation();deleteConversationForMe('${escapeHtml(c.conv_id)}')" title="حذف المحادثة من عندي" style="background:none;border:none;font-size:16px;color:var(--muted);cursor:pointer;padding:6px;border-radius:8px;flex:0 0 auto;opacity:0.6;transition:all .2s" onmouseover="this.style.opacity='1';this.style.color='#ef4444'" onmouseout="this.style.opacity='0.6';this.style.color='var(--muted)'">🗑️</button>

        </div>`;

    }).join("");

    list.innerHTML = freshInboxHtml;

    try {

      localStorage.setItem("tasawuq_inbox_cache_" + myUid, freshInboxHtml);

    } catch(e){}

  }catch(err){

    console.error("خطأ في تحميل المحادثات:", err);

    list.innerHTML = `<div class="reportsEmpty">⚠️ تعذر تحميل المحادثات</div>`;

  }

}

