export async function updateGlobalUnreadChatCount(){

  if(!auth.currentUser) return;

  const hBadge = document.getElementById("chatHeaderBadge");

  const aBadge = document.getElementById("accountChatBadge");

  try{

    const myUid = auth.currentUser.uid;

    const lastSeen = parseInt(localStorage.getItem("tasawuq_chat_last_seen") || "0", 10);

    const sb = window.supabase || supabase;

    const myCandUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(myUid) : [myUid];
    const orParts = myCandUids.flatMap(u => [`p1.eq.${u}`, `p2.eq.${u}`]).join(',');

    const { data, error } = await sb

      .from("chat_conversations")

      .select("conv_id, updated_at, last_sender_uid")

      .or(orParts)

      .not("last_sender_uid", "in", `(${myCandUids.join(',')})`)

      .gt("updated_at", lastSeen)

      .limit(50);

    if(error) return;

    const unreadCount = (data || []).length;

    if(hBadge){
      if(unreadCount > 0){
        hBadge.style.display = "flex";
        hBadge.textContent = unreadCount > 9 ? "9+" : unreadCount;
      } else hBadge.style.display = "none";
    }
    const bottomChatBadge = document.getElementById("bottomChatBadge");
    if(bottomChatBadge){
      if(unreadCount > 0){
        bottomChatBadge.style.display = "flex";
        bottomChatBadge.textContent = unreadCount > 9 ? "9+" : unreadCount;
      } else bottomChatBadge.style.display = "none";
    }

    if(aBadge){

      if(unreadCount > 0){

        aBadge.style.display = "inline-flex";

        aBadge.textContent = unreadCount > 9 ? "9+" : unreadCount;

      } else aBadge.style.display = "none";

    }

  }catch(e){}

}

// 🔄 فحص دوري ذكي كل 10 ثوانٍ لضمان عدم فوات أي إشعار حتى مع ضعف النت

