window.getCanonicalFollowUid = function(uid) {
  if (!uid) return uid;
  if (uid === 'zoSxkP0PGPWx37J6GMQiOjVgiMC3' || uid === 'NrYY8We8VDgBiEk98bbxvkyfq2N2') {
    return 'NrYY8We8VDgBiEk98bbxvkyfq2N2';
  }
  if (typeof window.getCandidateUids === 'function') {
    const cands = window.getCandidateUids(uid);
    if (cands.includes('NrYY8We8VDgBiEk98bbxvkyfq2N2') || cands.includes('zoSxkP0PGPWx37J6GMQiOjVgiMC3')) {
      return 'NrYY8We8VDgBiEk98bbxvkyfq2N2';
    }
  }
  return uid;
};

window.fetchAndFormatFollowers = async function(targetUid, tab) {
  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (!sb || !targetUid) return [];

  const candUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(targetUid) : [targetUid];
  const filterCol = tab === "following" ? "follower_uid" : "seller_uid";

  const { data, error } = await sb
    .from("user_follows")
    .select("*")
    .in(filterCol, candUids);

  if (error || !data || data.length === 0) return [];

  const uids = [];
  data.forEach(row => {
    const rawId = tab === "following" ? (row.seller_uid || row.sellerUid) : (row.follower_uid || row.followerUid);
    const id = (typeof window.getCanonicalFollowUid === 'function') ? window.getCanonicalFollowUid(rawId) : rawId;
    if (id && !candUids.includes(id) && !uids.includes(id)) {
      uids.push(id);
    }
  });

  if (uids.length === 0) return [];

  const allQueryUids = [];
  uids.forEach(u => {
    if (u === 'NrYY8We8VDgBiEk98bbxvkyfq2N2' || u === 'zoSxkP0PGPWx37J6GMQiOjVgiMC3') {
      if (!allQueryUids.includes('NrYY8We8VDgBiEk98bbxvkyfq2N2')) allQueryUids.push('NrYY8We8VDgBiEk98bbxvkyfq2N2');
      if (!allQueryUids.includes('zoSxkP0PGPWx37J6GMQiOjVgiMC3')) allQueryUids.push('zoSxkP0PGPWx37J6GMQiOjVgiMC3');
    } else {
      if (!allQueryUids.includes(u)) allQueryUids.push(u);
    }
  });

  let profileMap = {};
  try {
    const { data: profData } = await sb
      .from("profiles")
      .select("*")
      .in("id", allQueryUids);
    if (profData && Array.isArray(profData)) {
      profData.forEach(pr => {
        const cId = (typeof window.getCanonicalFollowUid === 'function') ? window.getCanonicalFollowUid(pr.id) : pr.id;
        if (!profileMap[cId] || (!profileMap[cId].name && pr.name)) {
          profileMap[cId] = {
            name: (pr.name || pr.full_name || "").trim(),
            username: (pr.username || "").trim(),
            avatar: pr.avatar || ""
          };
        }
      });
    }
  } catch(e){}

  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  return uids.map(uid => {
    const isAbdo = (uid === 'NrYY8We8VDgBiEk98bbxvkyfq2N2' || uid === 'zoSxkP0PGPWx37J6GMQiOjVgiMC3');
    const existingP = (typeof allPosts !== 'undefined' && Array.isArray(allPosts)) ? allPosts.find(p => p.uid === uid || p.addedBy === uid || (isAbdo && (p.uid === 'NrYY8We8VDgBiEk98bbxvkyfq2N2' || p.uid === 'zoSxkP0PGPWx37J6GMQiOjVgiMC3'))) : null;
    const storeMatch = (typeof allStores !== 'undefined' && Array.isArray(allStores)) ? allStores.find(s => s.ownerUid === uid || s.id === uid) : null;
    const fromDb = profileMap[uid] || {};
    const cachedProf = (window.sellersProfileCache && window.sellersProfileCache[uid]) || (isAbdo ? (window.sellersProfileCache['NrYY8We8VDgBiEk98bbxvkyfq2N2'] || window.sellersProfileCache['zoSxkP0PGPWx37J6GMQiOjVgiMC3']) : null) || null;
    const localAv = (typeof window.getSafeSellerAvatar === 'function') ? window.getSafeSellerAvatar(uid) : "";
    const isMe = me && (me.uid === uid || (candUids.includes(uid)));
    const myName = (typeof myProfile !== 'undefined' && myProfile && myProfile.name) || (me && me.displayName) || localStorage.getItem("tasawuq_my_name");

    let resolvedName = fromDb.name || (cachedProf && cachedProf.name && cachedProf.name !== "مستخدم" ? cachedProf.name : "");
    if (!resolvedName && isMe && myName) resolvedName = myName;
    if (!resolvedName && isAbdo) resolvedName = "Abdo Alkera";
    if (!resolvedName && existingP) resolvedName = existingP.sellerName || existingP.storeName;
    if (!resolvedName && storeMatch) resolvedName = storeMatch.name;
    if (!resolvedName && (fromDb.username || (cachedProf && cachedProf.username))) resolvedName = "@" + (fromDb.username || cachedProf.username);
    if (!resolvedName && existingP && existingP.sellerUsername) resolvedName = "@" + existingP.sellerUsername;
    if (!resolvedName) resolvedName = (typeof resolveDisplayName === 'function') ? resolveDisplayName(uid, existingP, storeMatch) : ("عضو " + uid.substring(0, 5));

    let resolvedUsername = fromDb.username || (cachedProf && cachedProf.username) || (existingP && existingP.sellerUsername) || "";
    if (!resolvedUsername && isAbdo) resolvedUsername = "abd";

    let resolvedAvatar = (typeof window.getSafeSellerAvatar === 'function') ? window.getSafeSellerAvatar(uid, (cachedProf && cachedProf.avatar) || fromDb.avatar || (storeMatch && storeMatch.logo) || (existingP && existingP.sellerAvatar) || localAv) : (fromDb.avatar || "");
    if (!resolvedAvatar && isAbdo) resolvedAvatar = "https://i.ibb.co/JwP60ttQ/photo.jpg";

    return {
      uid: uid,
      name: resolvedName,
      username: resolvedUsername,
      avatar: resolvedAvatar
    };
  });
};

window.renderFollowerCardsHtml = function(profiles) {
  if (!profiles || profiles.length === 0) return "";
  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  return profiles.map(p => {
    const name = p.name;
    const uname = p.username ? "@" + p.username.replace(/^@/, '') : "";
    const avUrl = p.avatar;
    const initial = name ? name.trim()[0].toUpperCase() : '👤';
    const isMe = me && me.uid === p.uid;
    const followingHim = (typeof isFollowing === 'function') ? isFollowing(p.uid) : false;

    const actionBtn = (!isMe && me) ? `
      <button class="fbBtnAction ${followingHim ? 'edit' : 'primary'}" data-follow-uid="${p.uid}" onclick="event.stopPropagation();toggleFollow('${p.uid}',event)" style="padding:6px 14px;font-size:12px;margin:0">
        ${followingHim ? '✓ متابَع' : '+ متابعة'}
      </button>
    ` : `<div style="font-size:12px;color:var(--muted)">عرض البروفايل ›</div>`;

    return `
      <div class="followerUserRow" style="cursor:pointer;display:flex;align-items:center;gap:12px;padding:10px 14px;background:var(--card);border-radius:12px;margin-bottom:8px;border:1px solid var(--border);" onclick="openSellerFromFollowers('${escapeHtml(p.uid)}')">
        <div class="followerAvatar" style="width:44px;height:44px;min-width:44px;max-width:44px;min-height:44px;max-height:44px;border-radius:50%;overflow:hidden;flex-shrink:0;display:flex;align-items:center;justify-content:center;background:linear-gradient(135deg,#0284c7,#0369a1);color:#fff;font-weight:800;font-size:16px;">
          ${avUrl ? `<img src="${escapeHtml(avUrl)}" alt="${escapeHtml(name)}" style="width:100%;height:100%;min-width:100%;max-width:100%;min-height:100%;max-height:100%;object-fit:cover;border-radius:50%;display:block;" onerror="this.parentElement.innerHTML='${initial}'">` : initial}
        </div>
        <div class="followerInfo" style="flex:1;min-width:0;">
          <div class="followerName" style="font-size:14px;font-weight:800;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${escapeHtml(name)}</div>
          ${uname ? `<div class="followerUsername" style="font-size:12px;color:#166534;font-weight:700;direction:ltr;text-align:right;">${escapeHtml(uname)}</div>` : ''}
        </div>
        ${actionBtn}
      </div>
    `;
  }).join("");
};

async function loadFollowersModalContent(targetUid, tab) {
  const list = document.getElementById("followersModalList");
  if (!list) return;

  list.innerHTML = "<div class='reportsEmpty'>⏳ جاري التحميل...</div>";

  try {
    const profiles = await window.fetchAndFormatFollowers(targetUid, tab);

    const tabFCount = document.getElementById("tabFollowersCount");
    const tabFgCount = document.getElementById("tabFollowingCount");
    if (tab === "followers" && tabFCount) tabFCount.textContent = profiles.length;
    if (tab === "following" && tabFgCount) tabFgCount.textContent = profiles.length;

    if (profiles.length === 0) {
      list.innerHTML = `<div class='reportsEmpty'>${tab === "following" ? "🔍 لا يتابع أحداً بعد" : "👥 لا يوجد متابعون بعد"}</div>`;
      return;
    }

    list.innerHTML = window.renderFollowerCardsHtml(profiles);
  } catch(err) {
    console.error("loadFollowersModalContent error:", err);
    list.innerHTML = "<div class='reportsEmpty'>⚠️ تعذر تحميل القائمة</div>";
  }
}
window.openFollowersModal = async (targetUid, initialTab = "followers", skipHistory = false) => {
  if(!targetUid) return;
  const so = document.getElementById("sellerOverlay");
  const ao = document.getElementById("accountOverlay");
  if (so && !so.classList.contains("hidden")) {
    window._followersBackTarget = 'seller';
    so.classList.add("hidden");
  } else if (ao && !ao.classList.contains("hidden")) {
    window._followersBackTarget = 'account';
    ao.classList.add("hidden");
  }
  window._currentFollowersModalUid = targetUid;
  window._currentFollowersTab = initialTab;
  const fo = document.getElementById("followersOverlay");
  if(fo) {
    fo.classList.remove("hidden");
    fo.style.zIndex = "4500";
    if(!skipHistory && typeof pushNavState === 'function') pushNavState({ screen: 'followers' }, '#followers');
  }

  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  const candUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(targetUid) : [targetUid];
  const isMe = me && (candUids.includes(me.uid) || targetUid === me.uid);

  // تحديث عناوين التبويبات بحسب صاحب الملف (أتابعهم للمستخدم نفسه أو يتابعهم للبائعين)
  const tabFg = document.getElementById("tabFollowing");
  if (tabFg) {
    const curCount = document.getElementById("tabFollowingCount")?.textContent || "0";
    tabFg.innerHTML = (isMe ? "أتابعهم" : "يتابعهم") + ` (<span id="tabFollowingCount">${curCount}</span>)`;
  }

  const titleEl = document.getElementById("followersModalTitle");
  if (titleEl) {
    titleEl.textContent = isMe ? "المتابعون والأصدقاء" : "قائمة المتابعين";
  }

  // جلب كلا العدادين فورياً وبدقة تامة من Supabase
  const sbCounts = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (sbCounts) {
    sbCounts.from("user_follows").select("follower_uid").in("seller_uid", candUids).then(res => {
      const el = document.getElementById("tabFollowersCount");
      if (el && res && Array.isArray(res.data)) {
        const unique = new Set(res.data.map(r => (typeof window.getCanonicalFollowUid === 'function' ? window.getCanonicalFollowUid(r.follower_uid) : r.follower_uid)).filter(u => u && !candUids.includes(u)));
        el.textContent = unique.size;
      }
    }).catch(()=>{});

    sbCounts.from("user_follows").select("seller_uid").in("follower_uid", candUids).then(res => {
      const el = document.getElementById("tabFollowingCount");
      if (el && res && Array.isArray(res.data)) {
        const unique = new Set(res.data.map(r => (typeof window.getCanonicalFollowUid === 'function' ? window.getCanonicalFollowUid(r.seller_uid) : r.seller_uid)).filter(u => u && !candUids.includes(u)));
        el.textContent = unique.size;
      }
    }).catch(()=>{});
  }

  switchFollowersTab(initialTab);

};

/* ========================================================

   🔔 نظام إشعارات OneSignal الحقيقي (Web Push Notifications)

   ======================================================== */

export const DEFAULT_ONESIGNAL_APP_ID = "7030f4d7-c06e-41a9-a601-8d42965023b3";

export const DEFAULT_ONESIGNAL_REST_KEY = "os_v2_app_oaypjv6anza2tjqbrvbjmubdwpvxh6svcgkenzngim3kq4ddjazv3lso5f3aynddjakwakbul77jznflu4bu5u4xpvtc5hdusuetaaa";

let _onesignalRestKey = localStorage.getItem("tasawuq_onesignal_rest_key") || DEFAULT_ONESIGNAL_REST_KEY;

window._onesignalRestKey = _onesignalRestKey;

// ربط المستخدم بـ OneSignal لتلقي الإشعارات حتى عندما يكون الهاتف أو الشاشة مقفلة

export function bindOneSignalUser(user){

  if(!user) return;

  startChatPushRealtimeListener(user.uid);

  const setupOneSignal = async (OneSignal) => {

    try {

      if(OneSignal.login){

        await OneSignal.login(user.uid);

      } else if(OneSignal.setExternalUserId){

        await OneSignal.setExternalUserId(user.uid);

      }

      if(OneSignal.User && OneSignal.User.addTag){

        await OneSignal.User.addTag("user_uid", user.uid);

        if(user.displayName) await OneSignal.User.addTag("user_name", user.displayName);

      }

      // طلب الإذن بلطف

      if(window.Notification && Notification.permission === "default"){

        setTimeout(() => {

          try {

            if(OneSignal.Notifications && OneSignal.Notifications.requestPermission){

              OneSignal.Notifications.requestPermission();

            }

          } catch(e){}

        }, 4000);

      }

    } catch(err){

      console.warn("OneSignal binding:", err);

    }

  };

  if(window.OneSignal){

    setupOneSignal(window.OneSignal);

  } else {

    window.OneSignalDeferred = window.OneSignalDeferred || [];

    window.OneSignalDeferred.push(setupOneSignal);

  }

}

window.bindOneSignalUser = bindOneSignalUser;

export function unbindOneSignalUser(){

  try {

    if(window.OneSignal && typeof window.OneSignal.logout === 'function'){

      window.OneSignal.logout().catch(()=>{});

    }

  } catch(e){}

}

window.unbindOneSignalUser = unbindOneSignalUser;

// إرسال Push Notification فوري للمستلم عبر OneSignal REST API لإيقاظ هاتفه حتى لو كان مقفلاً

export async function dispatchChatPushNotification(receiverUid, senderName, textPreview, convId){

  if(!receiverUid || !auth.currentUser) return;

  const cleanSnippet = (textPreview || "أرسل لك رسالة جديدة").slice(0, 140);

  const myName = senderName || (myProfile && myProfile.name) || auth.currentUser.displayName || localStorage.getItem("tasawuq_my_name") || "عضو";

  try {

    const restKey = window._onesignalRestKey || localStorage.getItem("tasawuq_onesignal_rest_key") || DEFAULT_ONESIGNAL_REST_KEY;

    if (restKey) {

      const targetUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(receiverUid) : [receiverUid];

      const payload = {

        app_id: DEFAULT_ONESIGNAL_APP_ID,

        include_aliases: { external_id: targetUids },

        include_external_user_ids: targetUids,

        target_channel: "push",

        headings: {

          ar: `💬 رسالة من ${myName}`,

          en: `💬 Message from ${myName}`

        },

        contents: {

          ar: cleanSnippet,

          en: cleanSnippet

        },

        url: window.location.origin + "?openChat=" + encodeURIComponent(convId),

        data: {

          convId: convId,

          type: "chat_message",

          senderUid: auth.currentUser.uid

        }

      };

      fetch("https://onesignal.com/api/v1/notifications", {

        method: "POST",

        headers: {

          "Content-Type": "application/json; charset=utf-8",

          "Authorization": "Basic " + restKey

        },

        body: JSON.stringify(payload)

      }).catch(err => console.warn("OneSignal Push delivery:", err));

    }

  } catch(err){

    console.warn("dispatchChatPushNotification err:", err);

  }

}

window.dispatchChatPushNotification = dispatchChatPushNotification;

/* ========================================================

   🔔 نظام الاستماع الفوري لإشعارات الرسائل (Realtime & Push)

   ======================================================== */

let _chatPushUnsub = null;

export function startChatPushRealtimeListener(myUid){

  if(!myUid) return;

  if(_chatPushUnsub){

    try{ _chatPushUnsub(); }catch(e){}

    _chatPushUnsub = null;

  }

  const processedEventIds = new Set();

  const sb = window.supabase || supabase;

  try {

    const candUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(myUid) : [myUid];

    const channels = [];

    candUids.forEach(uid => {

      const channel = sb

        .channel('chat_notifications:' + uid)

        .on('postgres_changes', {

          event: 'INSERT',

          schema: 'public',

          table: 'chat_messages',

          filter: 'receiver_uid=eq.' + uid

        }, payload => {

          const msg = payload.new;

          if(!msg || processedEventIds.has(msg.id)) return;

          processedEventIds.add(msg.id);

          const isActiveHere = window._activeChat && window._activeChat.convId === msg.conv_id && !document.hidden;

          if(!isActiveHere){

            // 1. تشغيل التنبيه الصوتي

            if(typeof playChatNotificationSound === 'function') playChatNotificationSound();

            // 2. تحديث عداد الرسائل

            if(typeof updateGlobalUnreadChatCount === 'function') updateGlobalUnreadChatCount();

            if(typeof _onConversationUpdated === 'function'){
              _onConversationUpdated({
                conv_id: msg.conv_id,
                last_message: msg.text || (msg.audio_url ? "🎙️ رسالة صوتية" : (msg.image_url ? "📷 صورة" : "رسالة جديدة")),
                last_sender_uid: msg.sender_uid,
                last_sender_name: msg.sender_name,
                updated_at: Number(msg.created_at) || Date.now()
              });
            }

            // 3. عرض إشعار النظام المباشر خارج الشاشة
            const title = `💬 ${msg.sender_name || 'رسالة جديدة'}`;

            const body = (msg.text || "وصلتك رسالة جديدة").replace('[صورة] ', '📷 صورة: ');

            showDeviceNotification(title, {
              body: body,
              icon: "/icon-192.png",
              badge: "/icon-192.png",
              tag: "chat_" + msg.conv_id,
              data: { url: window.location.origin + "?openChat=" + encodeURIComponent(msg.conv_id) }
            });

          }

        })

        .subscribe();

      channels.push(channel);

    });

    _chatPushUnsub = () => {

      channels.forEach(ch => {
        try { sb.removeChannel(ch); } catch(e){}
      });

    };

  } catch(e){

    console.warn("startChatPushRealtimeListener error:", e);

  }

}

window.startChatPushRealtimeListener = startChatPushRealtimeListener;

/* ========================================================

   🎙️ نظام التسجيل الصوتي المباشر والتبديل مثل Messenger

   ======================================================== */

let _mediaRecorder = null;

let _audioChunks = [];

let _voiceRecordTimer = null;

let _voiceRecordSeconds = 0;

let _recordedAudioBlob = null;

// زر الأكشن الموحد: ميكروفون افتراضياً -> تسجيل عند النقر، ويتحول إلى إرسال عند الكتابة
window.handleChatActionButton = () => {
  const input = document.getElementById("chatMessageInput");
  const text = (input?.value || "").trim();

  // 1) لو كان جاري تسجيل الصوت -> إيقاف وإرسال التسجيل الصوتي
  if (_mediaRecorder && _mediaRecorder.state === "recording") {
    stopVoiceRecordingAndSend();
    return;
  }

  // 2) لو في كلام مكتوب في الحقل -> إرسال الرسالة النصية فوراً
  if (text.length > 0) {
    sendUserChatMessage();
    return;
  }

  // 3) لو الحقل فارغ -> فتح وبدء تسجيل الصوت
  toggleVoiceRecording();
};

window.handleChatInputTyping = (input) => {
  const text = (input?.value || "").trim();
  const btn = document.getElementById("btnChatAction");
  if (!btn) return;

  if (_mediaRecorder && _mediaRecorder.state === "recording") return;

  if (text.length > 0) {
    // يتحول الزر إلى إرسال 🚀
    btn.innerHTML = "🚀";
    btn.style.background = "linear-gradient(135deg, #0284c7, #38bdf8)";
    btn.style.color = "#ffffff";
    btn.style.border = "none";
    btn.style.boxShadow = "0 3px 12px rgba(2, 132, 199, 0.35)";
    btn.classList.remove("voiceRecordingActive");
    btn.title = "إرسال الرسالة 🚀";
  } else {
    // الحقل فارغ -> الزر هو ميكروفون 🎙️
    btn.innerHTML = "🎙️";
    btn.style.background = "rgba(2, 132, 199, 0.1)";
    btn.style.color = "#0284c7";
    btn.style.border = "1.5px solid rgba(2, 132, 199, 0.25)";
    btn.style.boxShadow = "none";
    btn.classList.remove("voiceRecordingActive");
    btn.title = "تسجيل صوتي 🎙️";
  }
};

// بدء أو إيقاف التسجيل الصوتي

window.toggleVoiceRecording = async () => {

  if(_mediaRecorder && _mediaRecorder.state === "recording"){

    // تم الانتهاء من التسجيل -> تجهيز الإرسال

    stopVoiceRecordingAndSend();

    return;

  }

  if(!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia){

    showToast("⚠️ جهازك لا يدعم تسجيل الصوت من المتصفح", "warn");

    return;

  }

  try {

    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });

    _mediaRecorder = new MediaRecorder(stream);

    _audioChunks = [];

    _recordedAudioBlob = null;

    _mediaRecorder.ondataavailable = (e) => {

      if(e.data.size > 0) _audioChunks.push(e.data);

    };

    _mediaRecorder.onstop = async () => {

      stream.getTracks().forEach(t => t.stop());

      clearInterval(_voiceRecordTimer);

      if(_audioChunks.length > 0){

        _recordedAudioBlob = new Blob(_audioChunks, { type: 'audio/webm' });

        // إرسال الصوت مباشرة

        uploadAndSendVoiceMessage(_recordedAudioBlob, _voiceRecordSeconds);

      }

      resetVoiceRecordingUI();

    };

    _mediaRecorder.start();

    _voiceRecordSeconds = 0;

    showVoiceRecordingUI();

    _voiceRecordTimer = setInterval(() => {

      _voiceRecordSeconds++;

      const m = Math.floor(_voiceRecordSeconds / 60);

      const s = (_voiceRecordSeconds % 60).toString().padStart(2, '0');

      const timerEl = document.getElementById("chatVoiceTimer");

      if(timerEl) timerEl.textContent = `${m}:${s}`;

      if(_voiceRecordSeconds >= 120){ // الحد الأقصى دقيقتين

        stopVoiceRecordingAndSend();

      }

    }, 1000);

  } catch(err){

    console.error("Mic error:", err);

    showToast("يرجى السماح بالوصول للميكروفون لتسجيل الصوت 🎙️", "warn");

  }

};

window.showVoiceRecordingUI = function showVoiceRecordingUI(){

  const input = document.getElementById("chatMessageInput");
  const attachBtns = document.getElementById("chatNormalAttachBtns");
  const voiceBar = document.getElementById("chatVoiceRecordingBar");
  const btn = document.getElementById("btnChatAction");

  if(input) input.style.display = "none";
  if(attachBtns) attachBtns.style.display = "none";
  if(voiceBar) voiceBar.style.display = "flex";

  if(btn){
    btn.innerHTML = "🚀";
    btn.style.background = "#ef4444";
    btn.style.color = "#ffffff";
    btn.style.border = "none";
    btn.style.boxShadow = "0 3px 14px rgba(239, 68, 68, 0.45)";
    btn.classList.add("voiceRecordingActive");
    btn.title = "إيقاف وإرسال التسجيل الصوتي 🚀";
  }

  const timerEl = document.getElementById("chatVoiceTimer");
  if(timerEl) timerEl.textContent = "0:00";

}

window.resetVoiceRecordingUI = function resetVoiceRecordingUI(){

  const input = document.getElementById("chatMessageInput");
  const attachBtns = document.getElementById("chatNormalAttachBtns");
  const voiceBar = document.getElementById("chatVoiceRecordingBar");
  const btn = document.getElementById("btnChatAction");

  if(input) input.style.display = "block";
  if(attachBtns) attachBtns.style.display = "flex";
  if(voiceBar) voiceBar.style.display = "none";

  if(input){
    handleChatInputTyping(input);
  } else if(btn){
    btn.classList.remove("voiceRecordingActive");
    btn.innerHTML = "🎙️";
    btn.style.background = "rgba(2, 132, 199, 0.1)";
    btn.style.color = "#0284c7";
    btn.style.border = "1.5px solid rgba(2, 132, 199, 0.25)";
    btn.style.boxShadow = "none";
    btn.title = "تسجيل صوتي 🎙️";
  }

}

// إلغاء التسجيل وحذفه في سلة المهملات

window.cancelVoiceRecording = () => {

  _audioChunks = [];

  _recordedAudioBlob = null;

  clearInterval(_voiceRecordTimer);

  if(_mediaRecorder && _mediaRecorder.state === "recording"){

    _mediaRecorder.onstop = (e) => {

      if(_mediaRecorder.stream){

        _mediaRecorder.stream.getTracks().forEach(t => t.stop());

      }

      resetVoiceRecordingUI();

    };

    _mediaRecorder.stop();

  } else {

    resetVoiceRecordingUI();

  }

  showToast("🗑️ تم إلغاء التسجيل الصوتي", "info", 1500);

};

function stopVoiceRecordingAndSend(){

  if(_mediaRecorder && _mediaRecorder.state === "recording"){

    _mediaRecorder.stop();

  }

}

// رفع الرسالة الصوتية وإرسالها في الشات

async function uploadAndSendVoiceMessage(blob, durationSec){

  if(!blob || !window._activeChat || !auth.currentUser) return;

  const me = auth.currentUser;
  const canonicalMyUid = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(me.uid) : me.uid;
  const activeChat = window._activeChat;
  const canonicalTargetUid = (typeof getCanonicalChatUid === 'function') ? getCanonicalChatUid(activeChat.targetUid) : activeChat.targetUid;

  const senderName = (myProfile && myProfile.name) || me.displayName || localStorage.getItem("tasawuq_my_name") || "أنا";

  const convId = activeChat.convId || chatConvId(canonicalMyUid, canonicalTargetUid);

  const box = document.getElementById("chatMessagesBox");

  let tempDiv = null;

  if(box){

    const emptyNotice = box.querySelector(".reportsEmpty, div[style*='text-align:center']");

    if(emptyNotice) box.innerHTML = "";

    tempDiv = document.createElement("div");

    tempDiv.className = "chatBubble outgoing";

    tempDiv.setAttribute("data-temp", "1");
    tempDiv.setAttribute("data-msg-text", "[صوت]");
    tempDiv.setAttribute("data-created-at", Date.now());
    tempDiv.setAttribute("data-sender-uid", canonicalMyUid);

    tempDiv.innerHTML = `🎙️ رسالة صوتية (${durationSec || 1}ث) ⏳ <div class="chatTime">الآن</div>`;

    box.appendChild(tempDiv);

    box.scrollTop = box.scrollHeight;

  }

  try {

    // تحويل الـ Blob إلى Base64 Data URL لنقله وتشغيله مباشرة

    const reader = new FileReader();

    reader.readAsDataURL(blob);

    reader.onloadend = async () => {

      const base64Audio = reader.result;

      const now = Date.now();

      const textPayload = `[صوت:${durationSec || 1}] ` + base64Audio;

      const sb = window.supabase || supabase;

      const { data: insertedMsg, error: msgErr } = await sb.from("chat_messages").insert({

        conv_id: convId,

        sender_uid: canonicalMyUid,

        sender_name: senderName,

        receiver_uid: canonicalTargetUid,

        text: textPayload,

        post_id: activeChat.postId,

        store_id: activeChat.storeId,

        created_at: now

      }).select().single();

      if(msgErr) throw msgErr;

      if(tempDiv){

        tempDiv.removeAttribute("data-temp");

        if(insertedMsg && insertedMsg.id){

          tempDiv.setAttribute("data-msg-key", 'id_' + insertedMsg.id);

          tempDiv.setAttribute("data-msg-id", insertedMsg.id);

          _attachBubbleEvents(tempDiv);

        }

        tempDiv.innerHTML = `

          <div style="display:flex;align-items:center;gap:8px">

            <span style="font-size:20px">🎙️</span>

            <audio controls style="max-width:210px;height:36px;outline:none">

              <source src="${base64Audio}" type="audio/webm">

            </audio>

          </div>

          <div class="chatTime"><span style="opacity:0.85;margin-inline-end:3px">✓✓</span>${new Date(now).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}</div>

        `;

      }

      // تحديث ملخص المحادثة لصندوق الرسائل

      const p1 = [canonicalMyUid, canonicalTargetUid].sort()[0];

      const p2 = [canonicalMyUid, canonicalTargetUid].sort()[1];

      _onConversationUpdated({
        conv_id: convId,
        p1: p1,
        p2: p2,
        participant_uids: [canonicalMyUid, canonicalTargetUid],
        last_message: "🎙️ رسالة صوتية",
        last_sender_uid: canonicalMyUid,
        last_sender_name: senderName,
        updated_at: now
      });

      await sb.from("chat_conversations").upsert({

        conv_id: convId,

        p1: p1,

        p2: p2,

        participant_uids: [canonicalMyUid, canonicalTargetUid],

        last_message: "🎙️ رسالة صوتية",

        last_sender_uid: me.uid,

        last_sender_name: senderName,

        updated_at: now

      });

      // إشعار فوري

      if(typeof dispatchChatPushNotification === 'function'){

        dispatchChatPushNotification(activeChat.targetUid, senderName, "🎙️ أرسل لك رسالة صوتية", convId);

      }

    };

  } catch(e){

    if(tempDiv) tempDiv.remove();

    showToast("تعذر إرسال الصوت: " + e.message, "error");

  }

}

/* ========================================================

   📲 إدارة تثبيت التطبيق PWA الذكي (Android & iOS)

   ======================================================== */

let _deferredPwaPrompt = null;

if (typeof window !== 'undefined') {

  window.addEventListener('beforeinstallprompt', (e) => {

    e.preventDefault();

    _deferredPwaPrompt = e;

    const dismissedTime = Number(localStorage.getItem('tasawuq_pwa_dismissed') || 0);

    if (Date.now() - dismissedTime > 24 * 60 * 60 * 1000) {

      const banner = document.getElementById('pwaInstallBanner');

      if (banner) banner.style.display = 'flex';

    }

  });

  window.addEventListener('appinstalled', () => {

    _deferredPwaPrompt = null;
    try { localStorage.setItem('tasawuq_pwa_installed', 'true'); } catch(e){}
    if (typeof updatePwaInstallButtonsVisibility === 'function') updatePwaInstallButtonsVisibility();

    const banner = document.getElementById('pwaInstallBanner');

    if (banner) banner.style.display = 'none';

    // إرسال إشعار حقيقي لشاشة الجهاز لو كانت الإشعارات مفعلة

  try {

    if ("Notification" in window && Notification.permission === "granted") {

      new Notification(item.title, { body: item.text, icon: "favicon.ico" });

    }

  } catch(e){}

  if (typeof showToast === 'function') {

      showToast("🎉 تم تثبيت تطبيق تسوق الآن بنجاح على هاتفك!", "success", 4000);

    }

  });

}

export function isAppInstalled() {
  try {
    if (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) return true;
    if (window.navigator && (window.navigator.standalone === true || window.navigator.standalone === 'true')) return true;
    if (document.referrer && document.referrer.includes('android-app://')) return true;
    if (localStorage.getItem('tasawuq_pwa_installed') === 'true') return true;
  } catch(e){}
  return false;
}

export function updatePwaInstallButtonsVisibility() {
  const btn = document.getElementById('accountInstallAppBtn');
  if (!btn) return;
  if (isAppInstalled()) {
    btn.style.display = 'none';
  } else {
    btn.style.display = 'flex';
  }
}
window.isAppInstalled = isAppInstalled;
window.updatePwaInstallButtonsVisibility = updatePwaInstallButtonsVisibility;
try {
  if (typeof document !== 'undefined') {
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', updatePwaInstallButtonsVisibility);
    } else {
      updatePwaInstallButtonsVisibility();
    }
  }
} catch(e){}

export function triggerPwaInstall() {

  const isIos = /iPhone|iPad|iPod/.test(navigator.userAgent) && !window.MSStream;

  if (isAppInstalled()) {

    showToast("✅ التطبيق مثبت بالفعل وتعمل عليه الآن!", "info");
    updatePwaInstallButtonsVisibility();
    return;

  }

  if (isIos) {

    const iosModal = document.getElementById('iosInstallOverlay');

    if (iosModal) iosModal.classList.remove('hidden');

    return;

  }

  if (_deferredPwaPrompt) {

    _deferredPwaPrompt.prompt();

    _deferredPwaPrompt.userChoice.then((choiceResult) => {

      if (choiceResult.outcome === 'accepted') {

        const banner = document.getElementById('pwaInstallBanner');

        if (banner) banner.style.display = 'none';

      }

      _deferredPwaPrompt = null;

    });

  } else {

    showToast("📲 يمكنك تثبيت التطبيق من قائمة خيارات المتصفح (⋮) -> تثبيت التطبيق", "info", 5000);

  }

}

export function dismissPwaBanner() {

  const banner = document.getElementById('pwaInstallBanner');

  if (banner) banner.style.display = 'none';

  localStorage.setItem('tasawuq_pwa_dismissed', String(Date.now()));

}

export function closeIosInstallModal() {

  const iosModal = document.getElementById('iosInstallOverlay');

  if (iosModal) iosModal.classList.add('hidden');

}

window.triggerPwaInstall = triggerPwaInstall;

window.dismissPwaBanner = dismissPwaBanner;

window.closeIosInstallModal = closeIosInstallModal;

/* ========================================================

   🗑️ حذف الحساب بالكامل (مطلب إلزامي لمتجري Google Play و App Store)

   ======================================================== */

let deleteCountdownTimer = null;
let deleteCountdownSeconds = 10;

export function openDeleteAccountSafetyModal() {
  if (!auth.currentUser) {
    showToast("يرجى تسجيل الدخول أولاً", "warn");
    return;
  }
  const modal = document.getElementById('deleteAccountSafetyModal');
  if (!modal) {
    if (!confirm("⚠️ هل أنت متأكد تماماً من رغبتك في حذف حسابك نهائياً؟")) return;
    executeAccountDeletion();
    return;
  }
  modal.classList.remove('hidden');

  const btn = document.getElementById('btnFinalConfirmDelete');
  const numEl = document.getElementById('deleteCountdownNum');
  const timerBox = document.getElementById('deleteSafetyTimerBox');
  const timerText = document.getElementById('deleteSafetyTimerText');

  deleteCountdownSeconds = 10;
  if (numEl) numEl.textContent = '10';
  if (timerBox) {
    timerBox.style.background = '#fef2f2';
    timerBox.style.borderColor = '#fca5a5';
  }
  if (timerText) {
    timerText.innerHTML = 'فترة الأمان والتأكيد: <strong id="deleteCountdownNum" style="font-size:16px;color:#dc2626">10</strong> ثوانٍ';
  }

  if (btn) {
    btn.disabled = true;
    btn.style.background = '#94a3b8';
    btn.style.cursor = 'not-allowed';
    btn.style.boxShadow = 'none';
    btn.innerHTML = '⏳ يرجى الانتظار (10 ثوانٍ)...';
  }

  if (deleteCountdownTimer) clearInterval(deleteCountdownTimer);

  deleteCountdownTimer = setInterval(() => {
    deleteCountdownSeconds--;
    const currentNum = document.getElementById('deleteCountdownNum');
    if (currentNum) currentNum.textContent = String(deleteCountdownSeconds);

    if (btn && deleteCountdownSeconds > 0) {
      btn.innerHTML = `⏳ يرجى الانتظار (${deleteCountdownSeconds} ثوانٍ)...`;
    }

    if (deleteCountdownSeconds <= 0) {
      clearInterval(deleteCountdownTimer);
      deleteCountdownTimer = null;
      if (timerBox) {
        timerBox.style.background = '#f0fdf4';
        timerBox.style.borderColor = '#86efac';
      }
      if (timerText) {
        timerText.innerHTML = '<span style="color:#16a34a;font-weight:900">انتهت فترة الأمان (10 ثوانٍ) - يمكنك الآن الحذف النهائي إذا أردت</span>';
      }
      if (btn) {
        btn.disabled = false;
        btn.style.background = '#dc2626';
        btn.style.cursor = 'pointer';
        btn.style.boxShadow = '0 4px 14px rgba(220,38,38,0.35)';
        btn.innerHTML = '🔥 نعم، أنا متأكد - احذف حسابي نهائياً';
      }
    }
  }, 1000);
}

export function closeDeleteAccountSafetyModal() {
  if (deleteCountdownTimer) {
    clearInterval(deleteCountdownTimer);
    deleteCountdownTimer = null;
  }
  const modal = document.getElementById('deleteAccountSafetyModal');
  if (modal) modal.classList.add('hidden');
}

export async function executeAccountDeletion() {
  if (!auth.currentUser) {
    closeDeleteAccountSafetyModal();
    showToast("يرجى تسجيل الدخول أولاً", "warn");
    return;
  }
  const btn = document.getElementById('btnFinalConfirmDelete');
  if (btn) {
    btn.disabled = true;
    btn.innerHTML = '⏳ جاري مسح جميع بيانات الحساب نهائياً...';
  }

  const myUid = auth.currentUser.uid;
  const sb = window.supabase || supabase;

  try {
    if (sb) {
      await sb.from("posts").delete().eq("uid", myUid).catch(() => {});
      await sb.from("profiles").delete().eq("id", myUid).catch(() => {});
      await sb.from("feedback").delete().eq("uid", myUid).catch(() => {});
      await sb.from("user_follows").delete().or(`follower_uid.eq.${myUid},seller_uid.eq.${myUid}`).catch(() => {});
    }

    const keysToRemove = [];
    for (let i = 0; i < localStorage.length; i++) {
      const k = localStorage.key(i);
      if (k && (k.startsWith("tasawuq_") || k.includes(myUid))) {
        keysToRemove.push(k);
      }
    }
    keysToRemove.forEach(k => localStorage.removeItem(k));

    closeDeleteAccountSafetyModal();
    if (typeof closeOverlayDirect === 'function') closeOverlayDirect();

    if (typeof logout === 'function') {
      await logout();
    } else {
      await auth.signOut();
    }

    showToast("✅ تم حذف حسابك وجميع بياناتك نهائياً بنجاح.", "success", 6000);

    setTimeout(() => {
      window.location.reload();
    }, 1500);
  } catch (err) {
    console.error("deleteMyAccount err:", err);
    if (btn) {
      btn.disabled = false;
      btn.innerHTML = '🔥 نعم، أنا متأكد - احذف حسابي نهائياً';
    }
    showToast("تعذر استكمال حذف الحساب: " + (err.message || err), "error");
  }
}

export async function confirmDeleteMyAccount() {
  openDeleteAccountSafetyModal();
}

window.openDeleteAccountSafetyModal = openDeleteAccountSafetyModal;
window.closeDeleteAccountSafetyModal = closeDeleteAccountSafetyModal;
window.executeAccountDeletion = executeAccountDeletion;
window.confirmDeleteMyAccount = confirmDeleteMyAccount;

