// بناء قائمة تشغيل الريلز بناءً على مصدر الدخول

function buildReelsPlaylist(startSellerUid = null, startPostId = null) {

  const list = [];

  const seenIds = new Set();

  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;

  // 1) الفيديوهات الحقيقية من إعلانات المنصة (تشمل فيديوهات المستخدم والريلز المعتمدة)

  allPosts.forEach(p => {

    const vUrl = p.videoUrl || p.video || (p.specs && p.specs.video_url);
    if (vUrl && !seenIds.has(p.id)) {
      if (typeof vUrl === 'string' && vUrl.startsWith('blob:')) return;

      const isMine = (typeof window.isPostMine === 'function' ? window.isPostMine(p, true) : (me && (p.uid === me.uid || p.addedBy === me.uid)));

      const isApproved = getStatus(p) === "approved" || p.status === "approved";

      if (!isApproved && !isMine && !isAdmin) return;

      const placement = p.videoPlacement || "both";

      // إذا تم طلب الإعلان بالاسم أو كان لمعلن معين نسمح بالستوري دائماً، وإلا نتحقق من 24 ساعة
      if (placement === "story" && (!startPostId || startPostId !== p.id) && (!startSellerUid || p.uid !== startSellerUid)) {
        const DAY_MS = 24 * 60 * 60 * 1000;
        const created = Number(p.createdAt) || 0;
        if (Date.now() - created > DAY_MS && !isMine) return;
      }

      seenIds.add(p.id);

      // مزامنة التعليقات المخزنة في p.specs
      if (p.specs && Array.isArray(p.specs.reel_comments)) {
        const local = _reelsCommentsMap[p.id] || [];
        const mergedMap = new Map();
        p.specs.reel_comments.forEach(c => mergedMap.set(c.id || (c.author + '_' + (c.timestamp || 0)), c));
        local.forEach(c => mergedMap.set(c.id || (c.author + '_' + (c.timestamp || 0)), c));
        _reelsCommentsMap[p.id] = Array.from(mergedMap.values()).sort((a,b) => (a.timestamp || 0) - (b.timestamp || 0));
      }

      list.push({

        id: p.id,

        uid: p.uid,

        title: p.title || "إعلان",

        price: p.price || 0,

        city: p.city || "ليبيا",

        phone: p.phone || (window.sellersProfileCache && (window.sellersProfileCache[p.uid]?.phone || window.sellersProfileCache[p.uid]?.local_phone || window.sellersProfileCache[p.uid]?.localPhone)) || "",

        sellerName: resolveDisplayName(p.uid, p),

        sellerUsername: p.sellerUsername || (window.sellersProfileCache && window.sellersProfileCache[p.uid]?.username) || "",

        videoUrl: vUrl,

        videoPlacement: placement,

        createdAt: Number(p.createdAt) || Date.now(),

        views: p.views || 0,

        likes: _reelsLikesMap[p.id] || 0

      });

    }

  });

  // 2) دمج الفيديوهات التوضيحية فقط إذا لم تكن هناك أي فيديوهات حقيقية من إعلانات المنصة

  if (list.length === 0) {

    const demoItems = getDemoReelsItems();

    demoItems.forEach(d => {

      if (!seenIds.has(d.id)) {

        seenIds.add(d.id);

        list.push(d);

      }

    });

  }

  // ترتيب القائمة: لو داخلين من بروفايل شخص معين، نبدأ بفيديوهاته أولاً ثم يكمل للباقين

  if (startSellerUid) {

    const sellerVideos = list.filter(v => v.uid === startSellerUid);

    const otherVideos = list.filter(v => v.uid !== startSellerUid);

    _reelsPlaylist = [...sellerVideos, ...otherVideos];

  } else {

    _reelsPlaylist = list;

  }

  // ضبط المؤشر على الإعلان المطلوب تحديداً إن وجد

  _reelsCurrentIndex = 0;

  if (startPostId) {

    const idx = _reelsPlaylist.findIndex(v => v.id === startPostId);

    if (idx !== -1) _reelsCurrentIndex = idx;

  }

}

// مزامنة أحدث فيديوهات الستوري والريلز المعتمدة من Supabase في الخلفية
let _lastStoriesSyncTime = 0;
window.syncActiveStoriesFromSupabase = async function() {
  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (!sb) return;

  try {
    const { data, error } = await sb
      .from('posts')
      .select('*')
      .not('video_url', 'is', null)
      .order('created_at', { ascending: false })
      .limit(30);

    if (!error && Array.isArray(data) && data.length > 0) {
      let hasChanges = false;
      const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;

      data.forEach(row => {
        // تجاهل الروابط المؤقتة التالفة القديمة
        if (typeof row.video_url === 'string' && row.video_url.startsWith('blob:')) return;

        const p = (typeof objectFromDb === 'function') ? objectFromDb(row) : row;
        if (!p || !p.id) return;

        const exIdx = allPosts.findIndex(x => x.id === p.id);
        if (exIdx !== -1) {
          allPosts[exIdx].videoUrl = p.videoUrl;
          allPosts[exIdx].videoPlacement = p.videoPlacement || "both";
          if (p.specs) allPosts[exIdx].specs = Object.assign(allPosts[exIdx].specs || {}, p.specs);
          if (p.status === 'approved') allPosts[exIdx].status = 'approved';
          hasChanges = true;
        } else {
          allPosts.unshift(p);
          hasChanges = true;
        }
      });

      allPosts = sortPosts(allPosts);
      window.allPosts = allPosts;
      renderStoriesBarDirect();
      buildReelsPlaylist();
    }
  } catch(e) {
    console.warn("syncActiveStoriesFromSupabase error:", e);
  }
};

// عرض شريط الستوريات والريلز بالأعلى في الصفحة الرئيسية
window.renderStoriesBar = function() {
  renderStoriesBarDirect();

  // فحص الخلفية وتحديث السيرفر كل 30 ثانية
  const now = Date.now();
  if (now - _lastStoriesSyncTime > 30000) {
    _lastStoriesSyncTime = now;
    syncActiveStoriesFromSupabase();
  }
};

function renderStoriesBarDirect() {
  const bar1 = document.getElementById("storiesBar");
  const bar2 = document.getElementById("storiesBarCat");
  if (!bar1 && !bar2) return;

  const now = Date.now();
  const DAY_MS = 24 * 60 * 60 * 1000;
  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;

  // 1) تجميع كل مقاطع الفيديو الحقيقية من الإعلانات
  const activeVideoPosts = [];

  allPosts.forEach(p => {
    const vUrl = p.videoUrl || p.video || (p.specs && p.specs.video_url);
    if (vUrl) {
      // نتجاهل أي رابط blob قديم تالف
      if (typeof vUrl === 'string' && vUrl.startsWith('blob:')) return;

      const isMine = (typeof window.isPostMine === 'function' ? window.isPostMine(p, true) : (me && (p.uid === me.uid || p.addedBy === me.uid)));
      const isApproved = getStatus(p) === "approved" || p.status === "approved";
      if (!isApproved && !isMine && !isAdmin) return;

      const placement = p.videoPlacement || (p.specs && p.specs.video_placement) || "both";
      const created = Number(p.createdAt) || 0;

      // الستوري (24 ساعة)، الريلز وكلاهما مستمر
      if (placement === "story" && (now - created > DAY_MS) && !isMine) return;

      activeVideoPosts.push({ ...p, videoUrl: vUrl, videoPlacement: placement });
    }
  });

  // فحص هل المستخدم الحالي لديه ستوري أو ريلز نشط
  const myActiveStory = (typeof window.isPostMine === 'function')
    ? activeVideoPosts.find(p => window.isPostMine(p, true))
    : (me ? activeVideoPosts.find(p => p.uid === me.uid || p.addedBy === me.uid) : null);

  // 2) تجميع مقاطع الريلز والستوريات جنب بعضها (لكل معلن دائرة فيديو)
  const sellersMap = new Map();

  activeVideoPosts.forEach(p => {
    if (!sellersMap.has(p.uid)) {
      sellersMap.set(p.uid, {
        uid: p.uid,
        name: resolveDisplayName(p.uid, p),
        username: p.sellerUsername || (window.sellersProfileCache && window.sellersProfileCache[p.uid]?.username) || "",
        firstPostId: p.id,
        avatar: (typeof window.getSafeSellerAvatar === 'function') ? window.getSafeSellerAvatar(p.uid) : "",
        placement: p.videoPlacement || "both",
        isDemo: false
      });
    }
  });

  // 3) دمج مقاطع توضيحية فقط في حال لم تكن هناك أي إعلانات فيديو حقيقية نشطة
  if (sellersMap.size === 0) {
    const demoItems = (typeof getDemoReelsItems === 'function') ? getDemoReelsItems() : [];
    demoItems.forEach(d => {
      if (!sellersMap.has(d.uid)) {
        sellersMap.set(d.uid, {
          uid: d.uid,
          name: d.sellerName || "ريلز",
          username: d.sellerUsername || "",
          firstPostId: d.id,
          avatar: "",
          placement: "both",
          isDemo: true
        });
      }
    });
  }

  // 4) بناء الشريط المتجاور
  const myAvatar = me ? (localStorage.getItem("tasawuq_avatar_" + me.uid) || "") : "";
  const myInitial = (window.myProfile && window.myProfile.name) ? window.myProfile.name.trim()[0].toUpperCase() : '👤';
  const myAvHtml = myAvatar ? `<img src="${escapeHtml(myAvatar)}" alt="أنا">` : myInitial;
  const myStoryAction = myActiveStory ? `openReelsModal({ sellerUid: '${escapeHtml(me.uid)}', postId: '${escapeHtml(myActiveStory.id)}' })` : `openAddStoryPrompt()`;
  const myRingClass = myActiveStory ? `storyRing activeStoryRing` : `storyRing myStoryRing`;

  let html = `
    <!-- دائرة قصتك (عرض الستوري أو إضافة فيديو) -->
    <div class="storyBubble" onclick="${myStoryAction}" title="${myActiveStory ? 'مشاهدة فيديوهاتك ⭕' : 'أضف ستوري أو ريلز جديد ➕'}">
      <div class="${myRingClass}">
        <div class="storyAvatar">${myAvHtml}</div>
        <div class="storyAddBadge" onclick="event.stopPropagation();openAddStoryPrompt();" title="إضافة فيديو ريلز / ستوري جديد">+</div>
      </div>
      <div class="storyName" style="${myActiveStory ? 'color:var(--teal-dark);font-weight:800' : ''}">${myActiveStory ? 'فيديوهاتك ⭕' : 'قصتك'}</div>
    </div>

    <!-- زر كل الـ Reels للدخول والتفرج على جميع الفيديوهات -->
    <div class="storyBubble" onclick="openReelsModal()" title="اضغط هنا للدخول والتفرج على كل مقاطع الريلز">
      <div class="storyRing" style="background:linear-gradient(135deg, #ec4899, #8b5cf6, #3b82f6);box-shadow:0 3px 10px rgba(236,72,153,0.35)">
        <div class="storyAvatar" style="background:#0f172a;color:#fff;font-size:22px;display:flex;align-items:center;justify-content:center">
          🎬
        </div>
      </div>
      <div class="storyName" style="color:#ec4899;font-weight:800">كل الـ Reels</div>
    </div>
  `;

  // عرض كل مقاطع المعلنين جنب بعض
  sellersMap.forEach(s => {
    if (me && s.uid === me.uid) return; // تم عرضه في دائرة "قصتك"

    const sInitial = (s.name || '👤').trim()[0].toUpperCase();
    const sAvHtml = s.avatar ? `<img src="${escapeHtml(s.avatar)}" alt="${escapeHtml(s.name)}">` : (s.isDemo ? '🎥' : sInitial);
    const ringGradient = s.placement === 'story'
      ? 'linear-gradient(135deg, #f59e0b, #ec4899)'
      : 'linear-gradient(135deg, #ec4899, #8b5cf6, #0284c7)';

    html += `
      <div class="storyBubble" onclick="openReelsModal({ sellerUid: '${escapeHtml(s.uid)}', postId: '${escapeHtml(s.firstPostId)}' })" title="مشاهدة ريلز: ${escapeHtml(s.name)}">
        <div class="storyRing" style="background:${ringGradient}">
          <div class="storyAvatar">${sAvHtml}</div>
        </div>
        <div class="storyName">${escapeHtml(s.name)}</div>
      </div>
    `;
  });

  if (bar1) bar1.innerHTML = html;
  if (bar2) bar2.innerHTML = html;
}

window.openAddStoryPrompt = function() {

  if (typeof startAddPost === 'function') {

    startAddPost();

    setTimeout(() => {

      const tile = document.getElementById("postVideoAddTile");

      if (tile) tile.scrollIntoView({ behavior: 'smooth', block: 'center' });

    }, 400);

  }

};

// فتح مشغل الريلز

window.openReelsModal = function(options = {}) {

  const sellerUid = options.sellerUid || null;

  const postId = options.postId || null;

  buildReelsPlaylist(sellerUid, postId);

  if (_reelsPlaylist.length === 0) {

    if (typeof showToast === 'function') showToast("لا توجد فيديوهات ريلز متاحة حالياً", "info");

    return;

  }

  const overlay = document.getElementById("reelsOverlay");

  if (overlay) overlay.classList.remove("hidden");

  loadCurrentReel();

  initReelsSwipeGestures();

};

// إغلاق مشغل الريلز

window.closeReelsModal = function() {

  const overlay = document.getElementById("reelsOverlay");

  if (overlay) overlay.classList.add("hidden");

  const video = document.getElementById("reelsMainVideo");

  if (video) {

    video.pause();

    video.src = "";

  }

  closeReelsComments();

};

// تحميل وعرض الريل الحالي

function loadCurrentReel() {

  if (_reelsCurrentIndex < 0) _reelsCurrentIndex = 0;

  if (_reelsCurrentIndex >= _reelsPlaylist.length) _reelsCurrentIndex = _reelsPlaylist.length - 1;

  const reel = _reelsPlaylist[_reelsCurrentIndex];

  if (!reel) return;

  const video = document.getElementById("reelsMainVideo");

  if (video) {

    video.src = reel.videoUrl;

    video.muted = _reelsMuted;

    video.play().catch(() => {

      // تشغيل صامت لو كان المتصفح يمنع الصوت التلقائي

      video.muted = true;

      video.play().catch(e => console.log("Video auto play prevented:", e));

    });

  }

  // تحديث النصوص والبيانات

  const headerTitle = document.getElementById("reelsHeaderTitle");

  if (headerTitle) {

    if (reel.videoPlacement === "story") {

      headerTitle.textContent = "⭕ ستوري الإعلانات (24 ساعة)";

    } else if (reel.videoPlacement === "reels") {

      headerTitle.textContent = "🎬 ريلز الإعلانات";

    } else {

      headerTitle.textContent = "🌟 ستوري وريلز";

    }

  }

  const titleEl = document.getElementById("reelsPostTitle");

  if (titleEl) titleEl.textContent = reel.title || "إعلان";

  const priceEl = document.getElementById("reelsPriceTag");

  if (priceEl) priceEl.textContent = (reel.price ? (Number(reel.price).toLocaleString() + " د.ل") : "للتواصل");

  const cityEl = document.getElementById("reelsCityTag");

  if (cityEl) cityEl.textContent = "📍 " + (reel.city || "ليبيا");

  const sNameEl = document.getElementById("reelsSellerName");

  if (sNameEl) sNameEl.textContent = reel.sellerName || "معلن";

  // الأفاتار

  const sAvEl = document.getElementById("reelsSellerAvatar");

  if (sAvEl) {

    const av = (typeof window.getSafeSellerAvatar === 'function') ? window.getSafeSellerAvatar(reel.uid) : "";

    const initial = (reel.sellerName || '👤').trim()[0].toUpperCase();

    sAvEl.innerHTML = av ? `<img src="${escapeHtml(av)}" alt="${escapeHtml(reel.sellerName)}">` : initial;

  }

  // زر المتابعة الموجب (+) التيك توك

  updateReelsFollowButton(reel.uid);

  // زر الإعجاب والعداد

  const likeCountEl = document.getElementById("reelsLikeCount");

  const likeIconEl = document.getElementById("reelsLikeIcon");

  const isLiked = !!_reelsUserLiked[reel.id];

  const count = (_reelsLikesMap[reel.id] !== undefined) ? _reelsLikesMap[reel.id] : (reel.likes || 0);

  if (likeCountEl) likeCountEl.textContent = count;

  if (likeIconEl) likeIconEl.textContent = isLiked ? "❤️" : "🤍";

  // عداد التعليقات
  const comments = _reelsCommentsMap[reel.id] || (reel.specs && Array.isArray(reel.specs.reel_comments) ? reel.specs.reel_comments : []);
  _reelsCommentsMap[reel.id] = comments;
  const commCountEl = document.getElementById("reelsCommentsCount");
  if (commCountEl) commCountEl.textContent = comments.length;

  // إذا كان درج التعليقات مفتوحاً، نحدث القائمة فوراً للفيديو الجديد
  const commentsSheetEl = document.getElementById("reelsCommentsSheet");
  if (commentsSheetEl && !commentsSheetEl.classList.contains("hidden")) {
    renderReelCommentsList(reel.id);
  }

  // التحكم بأزرار حذف وتعديل الفيديو (للأدمن أو صاحب الإعلان)
  const canManageReel = (typeof window.canManageCurrentReel === 'function') ? window.canManageCurrentReel(reel) : (isAdmin || (auth?.currentUser?.uid === reel.uid));

  const delTopBtn = document.getElementById("reelsDeleteTopBtn");
  const delSideBtn = document.getElementById("reelsSideDeleteBtn");
  const editSideBtn = document.getElementById("reelsSideEditBtn");

  if (delTopBtn) delTopBtn.style.display = canManageReel ? "flex" : "none";
  if (delSideBtn) delSideBtn.style.display = canManageReel ? "flex" : "none";
  if (editSideBtn) editSideBtn.style.display = canManageReel ? "flex" : "none";

}

// فحص صلاحية إدارة وحذف الفيديو في الريلز (للأدمن أو صاحب الفيديو/المتجر/الهاتف)
window.canManageCurrentReel = function(reel) {
  if (!reel) return false;
  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  const prof = (typeof myProfile !== 'undefined') ? myProfile : null;

  // 1. الأدمن العام ومشرف الموقع
  const isAdm = (typeof isAdmin !== 'undefined' && isAdmin) ||
    (typeof window.isUserAdmin === 'function' && window.isUserAdmin(me, prof)) ||
    (typeof window.isAbdoAccount === 'function' && window.isAbdoAccount(me, prof));
  if (isAdm) return true;

  if (!me && !prof) return false;

  // 2. فحص الإعلان الأصلي عبر isPostMine
  const postId = reel.id;
  const post = (typeof allPosts !== 'undefined' && Array.isArray(allPosts)) ? allPosts.find(p => p.id === postId) : null;
  if (post && typeof window.isPostMine === 'function' && window.isPostMine(post, true)) {
    return true;
  }

  // 3. مطابقة معرف الناشر المباشر أو قائمة المعرفات المرتبطة بالحساب
  const candUids = (typeof window.getCandidateUids === 'function') ? window.getCandidateUids(me ? me.uid : null) : [me ? me.uid : ''];
  if (reel.uid && candUids.includes(reel.uid)) return true;
  if (me && reel.uid === me.uid) return true;
  if (prof && prof.id && reel.uid === prof.id) return true;
  const oUid = prof && (prof.original_uid || prof.originalUid);
  if (oUid && reel.uid === oUid) return true;
  const aliases = (prof && (prof.alias_uids || prof.aliasUids)) || [];
  if (Array.isArray(aliases) && aliases.includes(reel.uid)) return true;

  // 4. مطابقة المتجر إن كان الإعلان لمتجر
  if (post && post.storeId && typeof window.canUserManageStore === 'function') {
    const store = (typeof allStores !== 'undefined' && Array.isArray(allStores)) ? allStores.find(s => s.id === post.storeId) : null;
    if (store && window.canUserManageStore(store)) return true;
  }

  // 5. مطابقة رقم الهاتف (آخر 8 أرقام)
  const myPhone = String((prof && (prof.phone || prof.local_phone || prof.localPhone)) || (window._activeWaSession && window._activeWaSession.phone) || (me && me.phoneNumber) || '').replace(/[^0-9]/g, '');
  const reelPhone = String(reel.phone || (post && post.phone) || '').replace(/[^0-9]/g, '');
  if (myPhone && reelPhone && myPhone.length >= 8 && reelPhone.length >= 8 && myPhone.slice(-8) === reelPhone.slice(-8)) {
    return true;
  }

  return false;
};

// تحديث زر المتابعة التيك توك (+)

function updateReelsFollowButton(sellerUid) {

  const btn = document.getElementById("reelsFollowPlusBtn");

  if (!btn) return;

  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;

  if (me && me.uid === sellerUid) {

    btn.style.display = "none";

    return;

  }

  btn.style.display = "flex";

  const followed = (typeof isFollowing === 'function') ? isFollowing(sellerUid) : false;

  if (followed) {

    btn.textContent = "✓";

    btn.classList.add("following");

  } else {

    btn.textContent = "+";

    btn.classList.remove("following");

  }

}


/* ==========================================================================
   🎬 وظائف حذف وتعديل فيديوهات الريلز والإعلانات (للأدمن وصاحب الفيديو)
   ========================================================================== */

window.deleteCurrentReelVideo = async function() {
  const reel = _reelsPlaylist[_reelsCurrentIndex];
  if (!reel) return;

  const canDelete = (typeof window.canManageCurrentReel === 'function')
    ? window.canManageCurrentReel(reel)
    : (isAdmin || (auth?.currentUser?.uid === reel.uid));

  if (!canDelete) {
    if (typeof showToast === 'function') showToast("ليس لديك صلاحية لحذف هذا الفيديو", "warn");
    return;
  }

  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  const isDirectOwner = !!(me && reel.uid === me.uid);
  const roleText = (isAdmin && !isDirectOwner) ? " (بصفتك مدير/مشرف الموقع)" : "";
  const confirmMsg = `هل أنت متأكد من حذف هذا الفيديو نهائياً من الإعلان والريلز؟${roleText}\n\nالعنوان: «${reel.title || 'إعلان'}»`;
  if (!confirm(confirmMsg)) return;

  // إيقاف الفيديو الحالي فوراً
  const mainVideoEl = document.getElementById("reelsMainVideo");
  if (mainVideoEl) {
    try {
      mainVideoEl.pause();
      mainVideoEl.removeAttribute("src");
      mainVideoEl.load();
    } catch(e) {}
  }

  if (typeof showToast === 'function') showToast("⏳ جاري حذف الفيديو فوراً...", "info", 1500);

  const postId = reel.id;

  try {
    const post = (typeof allPosts !== 'undefined' && Array.isArray(allPosts)) ? allPosts.find(x => x.id === postId) : null;
    let cleanSpecs = {};
    if (post && post.specs && typeof post.specs === 'object') {
      cleanSpecs = { ...post.specs };
    }
    delete cleanSpecs.video_url;
    delete cleanSpecs.video_placement;
    delete cleanSpecs.videoUrl;
    delete cleanSpecs.video;

    // 1) تحديث في Supabase فورياً
    const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
    if (sb) {
      await sb.from("posts").update({
        video_url: null,
        video_placement: null,
        specs: cleanSpecs
      }).eq("id", postId).catch(()=>{});
    }

    // 2) تحديث في Firestore / Supabase Adapter
    if (typeof db !== 'undefined' && db && typeof updateDoc === 'function') {
      await updateDoc(doc(db, "posts", postId), {
        videoUrl: null,
        video: null,
        videoPlacement: null,
        specs: cleanSpecs
      }).catch(()=>{});
    }

    // 3) تحديث الإعلان في الذاكرة المحلية
    if (post) {
      post.videoUrl = null;
      post.video = null;
      post.videoPlacement = null;
      if (post.specs && typeof post.specs === 'object') {
        delete post.specs.video_url;
        delete post.specs.video_placement;
        delete post.specs.videoUrl;
        delete post.specs.video;
      }
    }

    // 4) إزالة الفيديو من قائمة التشغيل الحالية
    _reelsPlaylist.splice(_reelsCurrentIndex, 1);

    if (_reelsPlaylist.length === 0) {
      closeReelsModal();
      if (typeof showToast === 'function') showToast("✅ تم حذف الفيديو بنجاح على الفور 🗑️", "success", 3000);
    } else {
      if (_reelsCurrentIndex >= _reelsPlaylist.length) {
        _reelsCurrentIndex = _reelsPlaylist.length - 1;
      }
      loadCurrentReel();
      if (typeof showToast === 'function') showToast("✅ تم حذف الفيديو بنجاح والانتقال للتالي 🗑️", "success", 3000);
    }

    // 5) إعادة رسم بطاقات الإعلانات وشريط الستوريات
    if (typeof renderPosts === 'function') renderPosts();
    if (typeof renderStoriesBar === 'function') renderStoriesBar();

  } catch(err) {
    console.error("deleteCurrentReelVideo error:", err);
    if (typeof showToast === 'function') showToast("تعذر حذف الفيديو: " + (err.message || err), "error");
  }
};

window.editCurrentReelPost = function() {
  const reel = _reelsPlaylist[_reelsCurrentIndex];
  if (!reel) return;
  closeReelsModal();
  setTimeout(() => {
    if (typeof editPost === 'function') editPost(reel.id);
  }, 200);
};

window.deletePostVideoDirect = async function(postId) {
  if (!postId) return;
  const p = (typeof allPosts !== 'undefined' && Array.isArray(allPosts)) ? allPosts.find(x => x.id === postId) : null;
  if (!p) return;

  const canDelete = (typeof window.canManageCurrentReel === 'function')
    ? window.canManageCurrentReel(p)
    : (isAdmin || (typeof window.isPostMine === 'function' && window.isPostMine(p, true)));

  if (!canDelete) {
    if (typeof showToast === 'function') showToast("ليس لديك صلاحية لحذف هذا الفيديو", "warn");
    return;
  }

  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  const isDirectOwner = !!(me && p.uid === me.uid);
  const roleText = (isAdmin && !isDirectOwner) ? " (بصفتك مدير/مشرف الموقع)" : "";
  if (!confirm(`هل أنت متأكد من حذف الفيديو المرفق بهذا الإعلان؟${roleText}`)) return;

  if (typeof showToast === 'function') showToast("⏳ جاري حذف الفيديو من الإعلان...", "info", 1500);

  try {
    let cleanSpecs = {};
    if (p.specs && typeof p.specs === 'object') {
      cleanSpecs = { ...p.specs };
    }
    delete cleanSpecs.video_url;
    delete cleanSpecs.video_placement;
    delete cleanSpecs.videoUrl;
    delete cleanSpecs.video;

    const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
    if (sb) {
      await sb.from("posts").update({
        video_url: null,
        video_placement: null,
        specs: cleanSpecs
      }).eq("id", postId).catch(()=>{});
    }

    if (typeof db !== 'undefined' && db && typeof updateDoc === 'function') {
      await updateDoc(doc(db, "posts", postId), {
        videoUrl: null,
        video: null,
        videoPlacement: null,
        specs: cleanSpecs
      }).catch(()=>{});
    }

    p.videoUrl = null;
    p.video = null;
    p.videoPlacement = null;
    if (p.specs && typeof p.specs === 'object') {
      delete p.specs.video_url;
      delete p.specs.video_placement;
      delete p.specs.videoUrl;
      delete p.specs.video;
    }

    openPost(postId, true);
    if (typeof renderPosts === 'function') renderPosts();
    if (typeof renderStoriesBar === 'function') renderStoriesBar();
    if (typeof showToast === 'function') showToast("✅ تم حذف الفيديو بنجاح من الإعلان 🗑️", "success");
  } catch(err) {
    console.error("deletePostVideoDirect err:", err);
    if (typeof showToast === 'function') showToast("تعذر حذف الفيديو: " + (err.message || err), "error");
  }
};

// الضغط على زر المتابعة (+) في الريلز

window.toggleReelsFollow = function(event) {

  if (event) event.stopPropagation();

  const reel = _reelsPlaylist[_reelsCurrentIndex];

  if (!reel || !reel.uid) return;

  if (typeof toggleFollow === 'function') {

    toggleFollow(reel.uid, event);

    setTimeout(() => {

      updateReelsFollowButton(reel.uid);

    }, 250);

  }

};

// التنقل للفيديو التالي

window.reelsGoNext = function() {

  if (_reelsCurrentIndex < _reelsPlaylist.length - 1) {

    const prevUid = _reelsPlaylist[_reelsCurrentIndex].uid;

    _reelsCurrentIndex++;

    const nextReel = _reelsPlaylist[_reelsCurrentIndex];

    // تنبيه الانتقال بين الحسابات

    if (prevUid !== nextReel.uid) {

      showAccountSwitchNotice(nextReel.sellerName || "معلن آخر");

    }

    loadCurrentReel();

  } else {

    if (typeof showToast === 'function') showToast("وصلت لآخر فيديو ريلز!", "info");

  }

};

// التنقل للفيديو السابق

window.reelsGoPrev = function() {

  if (_reelsCurrentIndex > 0) {

    _reelsCurrentIndex--;

    loadCurrentReel();

  }

};

// إشعار الانتقال من حساب لحساب

function showAccountSwitchNotice(sellerName) {

  const notice = document.getElementById("reelsAccountSwitchNotice");

  const txt = document.getElementById("reelsAccountSwitchText");

  if (!notice || !txt) return;

  txt.textContent = "انتقال إلى إعلانات: " + sellerName;

  notice.classList.remove("hidden");

  setTimeout(() => {

    notice.classList.add("hidden");

  }, 2200);

}

// الإعجاب بالريل وتفاعل الدبل تاب

window.toggleReelsLike = function() {

  const reel = _reelsPlaylist[_reelsCurrentIndex];

  if (!reel) return;

  const isLiked = !_reelsUserLiked[reel.id];

  _reelsUserLiked[reel.id] = isLiked;

  let count = (_reelsLikesMap[reel.id] !== undefined) ? _reelsLikesMap[reel.id] : (reel.likes || 0);

  count = isLiked ? (count + 1) : Math.max(0, count - 1);

  _reelsLikesMap[reel.id] = count;

  try {

    localStorage.setItem('tasawuq_reels_likes', JSON.stringify(_reelsLikesMap));

    localStorage.setItem('tasawuq_reels_user_liked', JSON.stringify(_reelsUserLiked));

  } catch(e) {}

  const likeCountEl = document.getElementById("reelsLikeCount");

  const likeIconEl = document.getElementById("reelsLikeIcon");

  if (likeCountEl) likeCountEl.textContent = count;

  if (likeIconEl) likeIconEl.textContent = isLiked ? "❤️" : "🤍";

};

// الضغط والنقر المزدوج على الفيديو

let _lastVideoTapTime = 0;

window.handleReelsVideoTap = function(event) {

  const now = Date.now();

  if (now - _lastVideoTapTime < 300) {

    // دبل تاب -> إعجاب مع قلب كبير في منتصف الفيديو

    triggerDoubleTapHeart();

    if (!_reelsUserLiked[_reelsPlaylist[_reelsCurrentIndex]?.id]) {

      toggleReelsLike();

    }

  } else {

    // نقرة واحدة -> إيقاف / استئناف الفيديو

    toggleReelsPlayPause();

  }

  _lastVideoTapTime = now;

};

function triggerDoubleTapHeart() {

  const heart = document.getElementById("reelsDoubleTapHeart");

  if (!heart) return;

  heart.classList.remove("hidden");

  setTimeout(() => {

    heart.classList.add("hidden");

  }, 600);

}

function toggleReelsPlayPause() {

  const video = document.getElementById("reelsMainVideo");

  const notice = document.getElementById("reelsPlayPauseNotice");

  if (!video) return;

  if (video.paused) {

    video.play();

    if (notice) notice.classList.add("hidden");

  } else {

    video.pause();

    if (notice) notice.classList.remove("hidden");

  }

}

// كتم / تشغيل الصوت

window.toggleReelsMute = function() {

  _reelsMuted = !_reelsMuted;

  const video = document.getElementById("reelsMainVideo");

  const btn = document.getElementById("reelsMuteToggleBtn");

  if (video) video.muted = _reelsMuted;

  if (btn) btn.textContent = _reelsMuted ? "🔇" : "🔊";

};

// تواصل واتساب مع المعلن

window.contactReelsSeller = function() {
  const reel = _reelsPlaylist[_reelsCurrentIndex];
  if (!reel) return;

  const rawPhone = reel.phone || (window.sellersProfileCache && (window.sellersProfileCache[reel.uid]?.phone || window.sellersProfileCache[reel.uid]?.local_phone)) || "";
  if (!rawPhone) {
    if (typeof showToast === 'function') showToast("⚠️ رقم هاتف المعلن غير متوفر", "warn");
    return;
  }

  const cleanPhone = normalizePhone(rawPhone);
  if (!cleanPhone || cleanPhone === "218" || cleanPhone.length < 10) {
    if (typeof showToast === 'function') showToast("⚠️ رقم هاتف المعلن غير صحيح أو غير متوفر", "warn");
    return;
  }

  if (reel.id && typeof incrementWhatsappClick === 'function') {
    incrementWhatsappClick(reel.id, 'post');
  }

  const msg = "السلام عليكم، بخصوص إعلانك على تسوق الآن: " + (reel.title || "");
  const url = toWhatsappUrl(cleanPhone, msg);
  window.open(url, "_blank");
};

