// ==========================================================================
// 💬 نظام التعليقات التفاعلي المباشر للريلز والستوري (مربوط بقاعدة البيانات)
// ==========================================================================

window.openReelsComments = async function() {
  const reel = _reelsPlaylist[_reelsCurrentIndex];
  if (!reel) return;
  const sheet = document.getElementById("reelsCommentsSheet");
  const backdrop = document.getElementById("reelsCommentsBackdrop");
  if (sheet) sheet.classList.remove("hidden");
  if (backdrop) backdrop.classList.remove("hidden");

  // عرض فوري للتعليقات من الذاكرة المحلية
  renderReelCommentsList(reel.id);

  // تحديث فوري مباشر من Supabase إن وجد اتصال وكان إعلاناً حقيقياً
  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (sb && reel.id && !String(reel.id).startsWith("demo_")) {
    try {
      const { data: dbRow, error } = await sb.from('posts').select('specs').eq('id', reel.id).maybeSingle();
      if (!error && dbRow && dbRow.specs) {
        let specs = dbRow.specs;
        if (typeof specs === "string") {
          try { specs = JSON.parse(specs); } catch(e) { specs = {}; }
        }
        if (specs && Array.isArray(specs.reel_comments)) {
          const local = _reelsCommentsMap[reel.id] || [];
          const mergedMap = new Map();
          specs.reel_comments.forEach(c => {
            const cid = c.id || (c.author + '_' + (c.timestamp || 0));
            mergedMap.set(cid, c);
          });
          local.forEach(c => {
            const cid = c.id || (c.author + '_' + (c.timestamp || 0));
            mergedMap.set(cid, c);
          });
          const mergedList = Array.from(mergedMap.values()).sort((a,b) => (a.timestamp || 0) - (b.timestamp || 0));
          _reelsCommentsMap[reel.id] = mergedList;
          try {
            localStorage.setItem('tasawuq_reels_comments', JSON.stringify(_reelsCommentsMap));
          } catch(e) {}
          renderReelCommentsList(reel.id);
          const commCountEl = document.getElementById("reelsCommentsCount");
          if (commCountEl) commCountEl.textContent = mergedList.length;
        }
      }
    } catch(e) {
      console.warn("Could not refresh comments from Supabase:", e);
    }
  }

  // تركيز حقل الإدخال برفق بعد الفتح
  setTimeout(() => {
    const input = document.getElementById("reelsCommentInput");
    if (input) input.focus();
  }, 300);
};

window.closeReelsComments = function() {
  const sheet = document.getElementById("reelsCommentsSheet");
  const backdrop = document.getElementById("reelsCommentsBackdrop");
  if (sheet) sheet.classList.add("hidden");
  if (backdrop) backdrop.classList.add("hidden");
};

function formatReelCommentTime(ts) {
  if (!ts) return "";
  const diff = Math.floor((Date.now() - ts) / 1000);
  if (diff < 60) return "الآن";
  if (diff < 3600) return `منذ ${Math.floor(diff / 60)} د`;
  if (diff < 86400) return `منذ ${Math.floor(diff / 3600)} س`;
  if (diff < 86400 * 7) return `منذ ${Math.floor(diff / 86400)} ي`;
  return new Date(ts).toLocaleDateString('ar-LY', { month: 'numeric', day: 'numeric' });
}

function renderReelCommentsList(reelId) {
  const list = document.getElementById("reelsCommentsList");
  const countEl = document.getElementById("reelsCommentsHeaderCount");
  if (!list) return;

  const reel = _reelsPlaylist[_reelsCurrentIndex] || {};
  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  const isAdOwner = me && (reel.uid === me.uid || reel.addedBy === me.uid);
  const isAdminUser = typeof isAdmin !== 'undefined' ? isAdmin : false;

  const comments = _reelsCommentsMap[reelId] || [];
  if (countEl) countEl.textContent = comments.length;

  if (comments.length === 0) {
    list.innerHTML = `<div class="reportsEmpty" style="padding:24px 16px;text-align:center;color:var(--muted)">💬 لا توجد تعليقات بعد، كن أول من يعلق!</div>`;
    return;
  }

  list.innerHTML = comments.map(c => {
    const authorName = c.author || 'مستخدم تسوق الآن';
    const initial = (authorName.trim()[0] || '👤').toUpperCase();
    const isMyComment = me && c.uid && (c.uid === me.uid);
    const canDelete = isMyComment || isAdOwner || isAdminUser;
    const timeStr = formatReelCommentTime(c.timestamp);

    const avHtml = c.avatar
      ? `<img src="${escapeHtml(c.avatar)}" alt="${escapeHtml(authorName)}">`
      : initial;

    const delBtn = canDelete
      ? `<button type="button" class="reelsCommentDelBtn" onclick="deleteReelComment('${escapeHtml(c.id || '')}')" title="حذف التعليق">🗑️</button>`
      : '';

    return `
      <div class="reelsCommentItem">
        <div class="reelsCommentAvatar">${avHtml}</div>
        <div class="reelsCommentContent">
          <div class="reelsCommentHeaderLine">
            <div class="reelsCommentAuthor">
              <span>${escapeHtml(authorName)}</span>
              ${timeStr ? `<span class="reelsCommentTime">${timeStr}</span>` : ''}
            </div>
            ${delBtn}
          </div>
          <div class="reelsCommentText">${escapeHtml(c.text)}</div>
        </div>
      </div>
    `;
  }).join("");
}

window.submitReelComment = async function() {
  const input = document.getElementById("reelsCommentInput");
  if (!input) return;

  const text = (input.value || "").trim();
  if (!text) return;

  const reel = _reelsPlaylist[_reelsCurrentIndex];
  if (!reel) return;

  if (!_reelsCommentsMap[reel.id]) _reelsCommentsMap[reel.id] = [];

  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) || null;
  const myUid = me ? me.uid : ("user_" + Math.random().toString(36).substr(2, 7));
  const myName = (window.myProfile && window.myProfile.name) ||
                 (me && me.displayName) ||
                 (me && me.email ? me.email.split('@')[0] : "مستخدم تسوق الآن");
  const myAvatar = (window.myProfile && window.myProfile.avatar) ||
                   (me ? localStorage.getItem("tasawuq_avatar_" + me.uid) : "") || "";

  const newComment = {
    id: "rc_" + Date.now() + "_" + Math.random().toString(36).substr(2, 5),
    uid: myUid,
    author: myName,
    avatar: myAvatar,
    text: text,
    timestamp: Date.now()
  };

  _reelsCommentsMap[reel.id].push(newComment);

  try {
    localStorage.setItem('tasawuq_reels_comments', JSON.stringify(_reelsCommentsMap));
  } catch(e) {}

  input.value = "";
  renderReelCommentsList(reel.id);

  const commCountEl = document.getElementById("reelsCommentsCount");
  if (commCountEl) commCountEl.textContent = _reelsCommentsMap[reel.id].length;

  // تمرير القائمة لأسفل لرؤية التعليق الجديد
  setTimeout(() => {
    const list = document.getElementById("reelsCommentsList");
    if (list) list.scrollTop = list.scrollHeight;
  }, 50);

  if (typeof showToast === 'function') {
    showToast("✅ تم نشر تعليقك بنجاح!", "success", 2000);
  }

  // مزامنة فورية مع Supabase إذا كان إعلاناً حقيقياً
  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (sb && reel.id && !String(reel.id).startsWith("demo_")) {
    try {
      const post = allPosts.find(p => p.id === reel.id) || reel;
      let specs = post.specs;
      if (typeof specs === "string") {
        try { specs = JSON.parse(specs); } catch(e) { specs = {}; }
      }
      if (!specs || typeof specs !== "object") specs = {};

      const { data: dbRow } = await sb.from('posts').select('specs').eq('id', reel.id).maybeSingle();
      let remoteSpecs = (dbRow && dbRow.specs) ? dbRow.specs : specs;
      if (typeof remoteSpecs === "string") {
        try { remoteSpecs = JSON.parse(remoteSpecs); } catch(e) { remoteSpecs = {}; }
      }
      if (!remoteSpecs || typeof remoteSpecs !== "object") remoteSpecs = {};

      const currentList = Array.isArray(remoteSpecs.reel_comments) ? remoteSpecs.reel_comments : [];
      if (!currentList.some(c => c.id === newComment.id)) {
        currentList.push(newComment);
      }
      remoteSpecs.reel_comments = currentList;
      post.specs = remoteSpecs;
      _reelsCommentsMap[reel.id] = currentList;

      await sb.from('posts').update({ specs: remoteSpecs }).eq('id', reel.id);

      try {
        localStorage.setItem('tasawuq_reels_comments', JSON.stringify(_reelsCommentsMap));
      } catch(e) {}
      renderReelCommentsList(reel.id);
    } catch(err) {
      console.warn("Error syncing reel comment to Supabase:", err);
    }
  }
};

window.deleteReelComment = async function(commentId) {
  if (!commentId) return;
  const reel = _reelsPlaylist[_reelsCurrentIndex];
  if (!reel) return;

  if (!confirm("هل أنت متأكد من حذف هذا التعليق؟")) return;

  const list = _reelsCommentsMap[reel.id] || [];
  _reelsCommentsMap[reel.id] = list.filter(c => c.id !== commentId);

  try {
    localStorage.setItem('tasawuq_reels_comments', JSON.stringify(_reelsCommentsMap));
  } catch(e) {}

  renderReelCommentsList(reel.id);

  const commCountEl = document.getElementById("reelsCommentsCount");
  if (commCountEl) commCountEl.textContent = _reelsCommentsMap[reel.id].length;

  if (typeof showToast === 'function') {
    showToast("🗑️ تم حذف التعليق", "info", 2000);
  }

  // تحديث الحذف في Supabase
  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (sb && reel.id && !String(reel.id).startsWith("demo_")) {
    try {
      const post = allPosts.find(p => p.id === reel.id) || reel;
      let specs = post.specs;
      if (typeof specs === "string") {
        try { specs = JSON.parse(specs); } catch(e) { specs = {}; }
      }
      if (!specs || typeof specs !== "object") specs = {};

      const { data: dbRow } = await sb.from('posts').select('specs').eq('id', reel.id).maybeSingle();
      let remoteSpecs = (dbRow && dbRow.specs) ? dbRow.specs : specs;
      if (typeof remoteSpecs === "string") {
        try { remoteSpecs = JSON.parse(remoteSpecs); } catch(e) { remoteSpecs = {}; }
      }
      if (!remoteSpecs || typeof remoteSpecs !== "object") remoteSpecs = {};

      const currentList = Array.isArray(remoteSpecs.reel_comments) ? remoteSpecs.reel_comments : [];
      remoteSpecs.reel_comments = currentList.filter(c => c.id !== commentId);
      post.specs = remoteSpecs;

      await sb.from('posts').update({ specs: remoteSpecs }).eq('id', reel.id);
    } catch(err) {
      console.warn("Error deleting comment from Supabase:", err);
    }
  }
};

// دعم إيماءات التمرير بالأصبع (Swipe Up / Down) مع عزل التعليقات بالكامل
function initReelsSwipeGestures() {
  const container = document.getElementById("reelsContainer");
  if (!container || container._swipeInitialized) return;
  container._swipeInitialized = true;

  // عزل أحداث التمرير والنقر داخل درج التعليقات
  const sheet = document.getElementById("reelsCommentsSheet");
  if (sheet) {
    const stopBubble = e => e.stopPropagation();
    sheet.addEventListener("touchstart", stopBubble, { passive: true });
    sheet.addEventListener("touchend", stopBubble, { passive: true });
    sheet.addEventListener("touchmove", stopBubble, { passive: true });
    sheet.addEventListener("wheel", stopBubble, { passive: true });
  }

  container.addEventListener("touchstart", e => {
    if (e.target.closest("#reelsCommentsSheet") || e.target.closest("#reelsCommentsBackdrop")) return;
    const curSheet = document.getElementById("reelsCommentsSheet");
    if (curSheet && !curSheet.classList.contains("hidden")) return;
    _reelsTouchStartY = e.touches[0].clientY;
  }, { passive: true });

  container.addEventListener("touchend", e => {
    if (e.target.closest("#reelsCommentsSheet") || e.target.closest("#reelsCommentsBackdrop")) return;
    const curSheet = document.getElementById("reelsCommentsSheet");
    if (curSheet && !curSheet.classList.contains("hidden")) return;
    const endY = e.changedTouches[0].clientY;
    const diff = _reelsTouchStartY - endY;
    if (diff > 50) {
      // سحب للأعلى -> التالي
      reelsGoNext();
    } else if (diff < -50) {
      // سحب للأسفل -> السابق
      reelsGoPrev();
    }
  }, { passive: true });

  // دعم عجلة الفأرة على الكمبيوتر
  container.addEventListener("wheel", e => {
    if (e.target.closest("#reelsCommentsSheet") || e.target.closest("#reelsCommentsBackdrop")) return;
    const curSheet = document.getElementById("reelsCommentsSheet");
    if (curSheet && !curSheet.classList.contains("hidden")) return;
    if (e.deltaY > 30) {
      reelsGoNext();
    } else if (e.deltaY < -30) {
      reelsGoPrev();
    }
  }, { passive: true });
}

// رفع واختيار فيديو في إضافة الإعلان

window.handlePostVideoSelected = function() {
  const input = document.getElementById("postVideoFile");
  if (!input || !input.files || input.files.length === 0) return;
  const file = input.files[0];

  // حجم أقصى مرن حتى 40 ميجابايت بدلاً من 15 ميجابايت الصارمة
  const MAX_BYTES = 40 * 1024 * 1024;
  if (file.size > MAX_BYTES) {
    const sizeMb = (file.size / (1024 * 1024)).toFixed(1);
    if (typeof showToast === 'function') {
      showToast(`⚠️ حجم الفيديو (${sizeMb} ميجابايت) كبير جداً! لتسريع الرفع وتشغيل الريلز، اختر فيديو أقل من 40 ميجابايت`, "warn", 5000);
    }
    removePostVideo();
    return;
  }

  const sizeMbNum = (file.size / (1024 * 1024)).toFixed(1);
  if (file.size > 25 * 1024 * 1024) {
    if (typeof showToast === 'function') {
      showToast(`💡 حجم الفيديو (${sizeMbNum}MB) — جاري التجهيز، يُفضل دائماً الفيديوهات الخفيفة للمشاهدة الفورية`, "info", 4000);
    }
  }

  let applied = false;
  const applySelectedVideo = (durationSec = null) => {
    if (applied) return;
    applied = true;

    _postVideoRemoved = false;
    _postSelectedVideoFile = file;

    if (_postSelectedVideoUrl && _postSelectedVideoUrl.startsWith("blob:")) {
      try { URL.revokeObjectURL(_postSelectedVideoUrl); } catch(e){}
    }
    _postSelectedVideoUrl = URL.createObjectURL(file);

    const prevBox = document.getElementById("postVideoPreviewBox");
    const prevEl = document.getElementById("postVideoPreviewEl");
    const promptTxt = document.getElementById("postVideoPromptText");

    if (prevEl) {
      prevEl.src = _postSelectedVideoUrl;
      try { prevEl.load(); } catch(e){}
    }
    if (prevBox) prevBox.classList.remove("hidden");
    if (promptTxt) {
      promptTxt.textContent = (durationSec != null && durationSec > 0)
        ? `✅ تم اختيار الفيديو (${durationSec} ثانية - ${sizeMbNum}MB)`
        : `✅ تم اختيار الفيديو بنجاح (${sizeMbNum}MB)`;
    }
    const optionsBox = document.getElementById("videoPlacementOptions");
    if (optionsBox) optionsBox.classList.remove("hidden");
  };

  // فحص مدة الفيديو بمرونة تامة مع مؤقت أمان وonerror
  const tempV = document.createElement("video");
  tempV.preload = "metadata";

  const safetyTimer = setTimeout(() => {
    // إذا تأخر فحص الميتاداتا لأكثر من ثانيتين، نقبل الفيديو فوراً دون تعطيل المستخدم
    applySelectedVideo();
  }, 2200);

  tempV.onloadedmetadata = function() {
    clearTimeout(safetyTimer);
    try { window.URL.revokeObjectURL(tempV.src); } catch(e){}

    const duration = Math.round(tempV.duration || 0);

    // إذا تجاوزت المدة 65 ثانية، ننبه المستخدم بلطف دون كسر الإضافة
    if (duration > 65) {
      if (typeof showToast === 'function') {
        showToast(`⚠️ مدة الفيديو (${duration} ثانية) طويلة نسبياً. الحد الأقصى الموصى به لريلز وستوري المنصة هو 60 ثانية`, "warn", 5000);
      }
    } else if (duration > 35) {
      if (typeof showToast === 'function') {
        showToast(`💡 مدة الفيديو (${duration} ثانية) — الفيديوهات القصيرة (أقل من 30 ثانية) تحقق عادة تفاعلاً أعلى`, "info", 3500);
      }
    }

    applySelectedVideo(duration);
  };

  tempV.onerror = function() {
    clearTimeout(safetyTimer);
    try { window.URL.revokeObjectURL(tempV.src); } catch(e){}
    // قبول الفيديو حتى لو فشلت الميتاداتا في متصفح أو صيغة معينة
    applySelectedVideo();
  };

  try {
    tempV.src = URL.createObjectURL(file);
  } catch(e) {
    clearTimeout(safetyTimer);
    applySelectedVideo();
  }
};

window.removePostVideo = function() {

  _postVideoRemoved = true;

  _postSelectedVideoFile = null;

  _postSelectedVideoUrl = null;

  const input = document.getElementById("postVideoFile");

  if (input) input.value = "";

  const prevBox = document.getElementById("postVideoPreviewBox");

  const prevEl = document.getElementById("postVideoPreviewEl");

  const promptTxt = document.getElementById("postVideoPromptText");

  if (prevEl) { prevEl.pause(); prevEl.src = ""; }

  if (prevBox) prevBox.classList.add("hidden");

  if (promptTxt) promptTxt.textContent = "اضغط هنا لإضافة فيديو للإعلان (ريلز 30 يوم + ستوري 24 ساعة)";

  const optionsBox = document.getElementById("videoPlacementOptions");

  if (optionsBox) optionsBox.classList.add("hidden");

  if (typeof setVideoPlacement === 'function') setVideoPlacement('both');

};

/* ==========================================================================

   🔔 نظام ومركز الإشعارات المتكامل للمستخدم (Notification Center)

   ========================================================================== */

let _userNotifications = [];

function loadUserNotifications() {
  try {
    const raw = localStorage.getItem("tasawuq_user_notifications");
    _userNotifications = raw ? JSON.parse(raw) : [];
  } catch(e) {
    _userNotifications = [];
  }

  // جلب الإشعارات الموجهة لي من المستخدمين الآخرين (مثل المتابعات الجديدة)
  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) ? auth.currentUser : null;
  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (sb && me && me.uid) {
    sb.from("feedback")
      .select("*")
      .eq("type", "user_notification")
      .eq("target_uid", me.uid)
      .order("created_at", { ascending: false })
      .limit(20)
      .then(({ data }) => {
        if (data && data.length > 0) {
          let updated = false;
          data.forEach(row => {
            if (!_userNotifications.some(n => n.id === row.id)) {
              _userNotifications.unshift({
                id: row.id,
                type: 'follow',
                title: row.title || 'متابع جديد 👤',
                text: row.message || '',
                senderUid: row.sender_uid,
                senderName: row.sender_name || '',
                timestamp: row.created_at ? new Date(row.created_at).getTime() : Date.now(),
                read: false
              });
              updated = true;
            }
          });
          if (updated) {
            saveUserNotifications();
            if (typeof renderNotificationsList === 'function') renderNotificationsList();
          }
        }
      }).catch(()=>{});
  }

  if (_userNotifications.length === 0) {
    _userNotifications = [
      {
        id: "notif_welcome_reels",
        type: "system",
        title: "🎉 ميزة جديدة في حسابك",
        text: "تم تفعيل شريط الستوريات ونظام الريلز لمقاطع الفيديو حتى 30 ثانية، ومتابعة الحسابات!",
        timestamp: Date.now() - 3600 * 1000,
        read: false
      }
    ];
    saveUserNotifications();
  }

  updateNotificationsBadge();
}

function saveUserNotifications() {

  try {

    localStorage.setItem("tasawuq_user_notifications", JSON.stringify(_userNotifications));

  } catch(e) {}

  updateNotificationsBadge();

}

window.addSystemNotification = function(notif) {
  if (!notif) return;
  const me = (typeof auth !== 'undefined' && auth && auth.currentUser) ? auth.currentUser : null;
  const myUid = me ? me.uid : null;

  // إذا كان الإشعار موجهاً لشخص آخر (مثل متابعة بائع)، يُرسل للشخص الآخر سحابياً ولا يظهر للتابع!
  if (notif.targetUid && myUid && notif.targetUid !== myUid) {
    const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
    if (sb) {
      sb.from("feedback").insert([{
        id: "notif_" + Date.now() + "_" + Math.random().toString(36).substr(2, 6),
        type: "user_notification",
        target_uid: notif.targetUid,
        sender_uid: myUid,
        sender_name: notif.senderName || "",
        title: notif.title || "متابع جديد 👤",
        message: notif.text || "",
        created_at: new Date().toISOString()
      }]).then(()=>{}).catch(()=>{});
    }
    return; // لا يظهر للشخص الذي قام بالمتابعة أبداً!
  }

  const item = {
    id: "notif_" + Date.now() + "_" + Math.random().toString(36).substr(2, 6),
    type: notif.type || "system",
    title: notif.title || "تنبيه جديد 🔔",
    text: notif.text || "",
    senderUid: notif.senderUid || null,
    senderName: notif.senderName || "",
    postId: notif.postId || null,
    timestamp: Date.now(),
    read: false
  };

  _userNotifications.unshift(item);
  if (_userNotifications.length > 50) _userNotifications = _userNotifications.slice(0, 50);
  saveUserNotifications();

  // إرسال الإشعار خارج الشاشة فوراً
  if(typeof showDeviceNotification === 'function'){
    showDeviceNotification(item.title, {
      body: item.text,
      icon: "/icon-192.png",
      tag: item.id,
      data: { url: window.location.origin }
    });
  }

  if (typeof showToast === 'function') {
    showToast(`🔔 ${item.title}: ${item.text}`, "info", 3500);
  }
};

window.openNotificationsCenter = function() {

  if(typeof updateExternalNotifBannerUI === "function") updateExternalNotifBannerUI();

  const overlay = document.getElementById("notificationsOverlay");

  if (overlay) overlay.classList.remove("hidden");

  // تعليم الإشعارات كمقروءة بعد ثانية

  setTimeout(() => {

    _userNotifications.forEach(n => n.read = true);

    saveUserNotifications();

    renderNotificationsList();

  }, 1200);

  renderNotificationsList();

};

window.closeNotificationsCenter = function() {

  const overlay = document.getElementById("notificationsOverlay");

  if (overlay) overlay.classList.add("hidden");

};

window.clearAllNotifications = function() {

  if (!confirm("هل تريد مسح كل الإشعارات؟")) return;

  _userNotifications = [];

  saveUserNotifications();

  renderNotificationsList();

};

function updateNotificationsBadge() {

  const badge = document.getElementById("accountNotifBadge");
  const headerBadge = document.getElementById("headerNotifBadge");
  const smdNotif = document.getElementById("smdNotifBadge");
  const menuDot = document.getElementById("menuNotificationDot");

  const unreadCount = _userNotifications.filter(n => !n.read).length;

  [badge, headerBadge].forEach(b => {
    if (!b) return;
    if (unreadCount > 0) {
      b.textContent = unreadCount;
      b.style.display = "inline-flex";
    } else {
      b.style.display = "none";
    }
  });

  if(smdNotif) {
    smdNotif.textContent = unreadCount;
    smdNotif.style.display = unreadCount > 0 ? "inline-block" : "none";
  }
  if(menuDot) {
    menuDot.style.display = unreadCount > 0 ? "block" : "none";
  }

}

function renderNotificationsList() {

  const list = document.getElementById("notificationsList");

  if (!list) return;

  if (_userNotifications.length === 0) {

    list.innerHTML = `<div class="reportsEmpty" style="padding:40px 20px;text-align:center">📭 لا توجد إشعارات جديدة</div>`;

    return;

  }

  list.innerHTML = _userNotifications.map(n => {

    let icon = "🔔";

    let iconClass = "";

    if (n.type === "follow") { icon = "👤"; iconClass = "follow"; }

    else if (n.type === "like") { icon = "❤️"; iconClass = "like"; }

    else if (n.type === "comment") { icon = "💬"; iconClass = "comment"; }

    const timeAgo = formatTimeAgo(n.timestamp || Date.now());

    const actionAttr = n.senderUid ? `onclick="closeNotificationsCenter();openSeller('${escapeHtml(n.senderUid)}')"` : '';

    return `

      <div class="notifItem ${n.read ? '' : 'unread'}" ${actionAttr}>

        ${n.read ? '' : '<div class="notifUnreadDot"></div>'}

        <div class="notifIconWrap ${iconClass}">${icon}</div>

        <div class="notifBody">

          <div class="notifTitle">${escapeHtml(n.title)}</div>

          <div class="notifText">${escapeHtml(n.text)}</div>

          <div class="notifTime">⏱️ ${timeAgo}</div>

        </div>

      </div>

    `;

  }).join("");

}

function formatTimeAgo(ts) {

  const diffSec = Math.floor((Date.now() - ts) / 1000);

  if (diffSec < 60) return "الآن";

  if (diffSec < 3600) return `منذ ${Math.floor(diffSec / 60)} دقيقة`;

  if (diffSec < 86400) return `منذ ${Math.floor(diffSec / 3600)} ساعة`;

  return `منذ ${Math.floor(diffSec / 86400)} يوم`;

}

