/* ==========================================================================

   🔄 ميزة السحب للأسفل للتحديث (Pull to Refresh - iOS & Android)

   ========================================================================== */

let _ptrStartY = 0;

let _ptrCurrentY = 0;

let _ptrIsPulling = false;

let _ptrIsRefreshing = false;

window.performAppRefresh = async function() {

  if (_ptrIsRefreshing) return;

  _ptrIsRefreshing = true;

  const indicator = document.getElementById("pullToRefreshIndicator");

  const icon = document.getElementById("ptrIcon");

  const text = document.getElementById("ptrText");

  if (indicator) {

    indicator.classList.add("refreshing");

    indicator.classList.add("visible");

    indicator.style.transform = "translateY(65px)";

  }

  if (text) text.textContent = "جاري تحديث المحتوى...";

  try {

    // 1) تحديث الإعلانات

    if (typeof searchServerPosts === "function" && document.getElementById("searchInput")?.value) {

      await searchServerPosts(document.getElementById("searchInput").value.trim());

    }

    if (typeof renderPosts === "function") renderPosts();

    // 2) تحديث الستوريات

    if (typeof renderStoriesBar === "function") renderStoriesBar();

    if ('serviceWorker' in navigator) { navigator.serviceWorker.getRegistrations().then(regs => { regs.forEach(r => r.update()); }).catch(()=>{}); }

    if (typeof fetchCategoryCounts === "function") await fetchCategoryCounts();

    if (typeof renderSuggestedAds === "function") renderSuggestedAds();

    if (typeof renderNearbyUsers === "function") renderNearbyUsers();

    if (typeof renderNearbyAds === "function") renderNearbyAds();

    // 3) تحديث الإشعارات

    if (typeof loadUserNotifications === "function") loadUserNotifications();

    if (typeof showToast === "function") {

      showToast("✅ تم تحديث الإعلانات والمحتوى بنجاح", "success", 2000);

    }

  } catch(e) {

    console.warn("Refresh error:", e);

  } finally {

    setTimeout(() => {

      if (indicator) {

        indicator.style.transform = "translateY(0px)";

        indicator.classList.remove("refreshing");

        setTimeout(() => {

          indicator.classList.remove("visible");

          if (text) text.textContent = "اسحب للأسفل للتحديث...";

          _ptrIsRefreshing = false;

        }, 250);

      } else {

        _ptrIsRefreshing = false;

      }

    }, 600);

  }

};

function initPullToRefresh() {

  const indicator = document.getElementById("pullToRefreshIndicator");

  const icon = document.getElementById("ptrIcon");

  const text = document.getElementById("ptrText");

  if (!indicator) return;

  window.addEventListener("touchstart", (e) => {

    // التفعيل فقط إذا كان المستخدم في أعلى الصفحة تماماً وغير فاتح لنافذة منبثقة

    const scrollTop = window.pageYOffset || document.documentElement.scrollTop || document.body.scrollTop || 0;

    const isAnyModalOpen = document.querySelector(".overlay:not(.hidden)");

    if (scrollTop <= 2 && !isAnyModalOpen && e.touches.length === 1) {

      _ptrStartY = e.touches[0].clientY;

      _ptrIsPulling = true;

    } else {

      _ptrIsPulling = false;

    }

  }, { passive: true });

  window.addEventListener("touchmove", (e) => {

    if (!_ptrIsPulling || _ptrIsRefreshing) return;

    const currentY = e.touches[0].clientY;

    const diff = currentY - _ptrStartY;

    if (diff > 0) {

      // مقاومة مطاطية طبيعية مثل الآيفون

      const pullDistance = Math.min(75, diff * 0.42);

      indicator.classList.add("visible");

      indicator.style.transform = `translateY(${pullDistance}px)`;

      if (pullDistance >= 50) {

        if (text) text.textContent = "اترك الآن للتحديث ✨";

        if (icon) icon.style.transform = "rotate(180deg)";

      } else {

        if (text) text.textContent = "اسحب للأسفل للتحديث...";

        if (icon) icon.style.transform = `rotate(${pullDistance * 3}deg)`;

      }

    }

  }, { passive: true });

  window.addEventListener("touchend", (e) => {

    if (!_ptrIsPulling || _ptrIsRefreshing) return;

    _ptrIsPulling = false;

    const currentY = e.changedTouches[0].clientY;

    const diff = currentY - _ptrStartY;

    const pullDistance = Math.min(75, diff * 0.42);

    if (pullDistance >= 50) {

      performAppRefresh();

    } else {

      indicator.style.transform = "translateY(0px)";

      setTimeout(() => {

        indicator.classList.remove("visible");

        if (icon) icon.style.transform = "rotate(0deg)";

      }, 200);

    }

  }, { passive: true });

}

// تشغيل ميزة السحب للتحديث

if (document.readyState === "loading") {

  document.addEventListener("DOMContentLoaded", initPullToRefresh);

} else {

  initPullToRefresh();

}

/* ========================================================

   🎙️ نظام البحث الصوتي الذكي (Voice Search Recognition)

   ======================================================== */

window.startVoiceSearch = (target) => {

  const SpeechRec = window.SpeechRecognition || window.webkitSpeechRecognition;

  if (!SpeechRec) {

    showToast("⚠️ متصفحك لا يدعم البحث بالصوت، يرجى استخدام متصفح حديث مثل Chrome", "warn");

    return;

  }

  let btn = null;

  if (target === 'cat') btn = document.getElementById("voiceSearchCatBtn");

  else if (target === 'ads') btn = document.getElementById("voiceSearchAdsBtn");

  else if (target === 'ai') btn = document.getElementById("voiceSearchAiBtn");

  try {

    const recognition = new SpeechRec();

    recognition.lang = "ar-LY";

    recognition.interimResults = false;

    recognition.maxAlternatives = 1;

    if (btn) btn.classList.add("recording");

    showToast("🎙️ تفضل، تحدّث الآن للبحث...", "info", 3000);

    recognition.onresult = (event) => {

      const transcript = (event.results && event.results[0] && event.results[0][0] && event.results[0][0].transcript || "").trim();

      if (!transcript) return;

      showToast(`🔍 بحث صوتي: "${transcript}"`, "info", 2000);

      if (target === 'cat') {

        const catInp = document.getElementById("searchInputCat");

        if (catInp) catInp.value = transcript;

        openCategoryDirect('الكل');

        const adsInp = document.getElementById("searchInput");

        if (adsInp) {

          adsInp.value = transcript;

          if (typeof handleSearchInput === 'function') handleSearchInput(transcript);

          else if (typeof filterPosts === 'function') filterPosts();

        }

      } else if (target === 'ads') {

        const adsInp = document.getElementById("searchInput");

        if (adsInp) {

          adsInp.value = transcript;

          if (typeof handleSearchInput === 'function') handleSearchInput(transcript);

          else if (typeof filterPosts === 'function') filterPosts();

        }

      } else if (target === 'ai') {

        const aiInp = document.getElementById("aiChatInput");

        if (aiInp) {

          aiInp.value = transcript;

          aiInp.focus();

        }

      }

    };

    recognition.onerror = (e) => {

      if (e.error !== 'no-speech') {

        console.warn("Speech error:", e.error);

        showToast("⚠️ لم يتم التقاط الصوت بوضوح، جرّب مرة ثانية 🎙️", "warn");

      }

    };

    recognition.onend = () => {

      if (btn) btn.classList.remove("recording");

    };

    recognition.start();

  } catch(err) {

    console.error("SpeechRecognition start error:", err);

    if (btn) btn.classList.remove("recording");

    showToast("⚠️ تعذر تشغيل الميكروفون، يرجى منح الإذن للمتصفح 🎙️", "warn");

  }

};

/* ========================================================

   🎯 نظام تحديد مكان ظهور الفيديو (ستوري / ريلز / كلاهما)

   ======================================================== */

window.setVideoPlacement = function(val) {

  const radio = document.querySelector(`input[name="videoPlacement"][value="${val}"]`);

  if (radio) radio.checked = true;

  const choices = [

    { id: 'placementBothLabel', val: 'both' },

    { id: 'placementStoryLabel', val: 'story' },

    { id: 'placementReelsLabel', val: 'reels' }

  ];

  choices.forEach(c => {

    const el = document.getElementById(c.id);

    if (!el) return;

    if (c.val === val) {

      el.classList.add("active");

      el.style.borderColor = "var(--teal)";

      el.style.background = "var(--teal-light)";

      el.style.borderWidth = "2px";

    } else {

      el.classList.remove("active");

      el.style.borderColor = "var(--border)";

      el.style.background = "var(--bg)";

      el.style.borderWidth = "1.5px";

    }

  });

};

async function uploadPostVideo(file) {
  if (!file) return null;

  const detectedType = file.type || '';
  const ext = (file.name && file.name.includes('.')) ? file.name.split('.').pop().toLowerCase() : '';
  let cleanExt = 'mp4';
  if (detectedType.includes('webm') || ext === 'webm') cleanExt = 'webm';
  else if (detectedType.includes('quicktime') || ext === 'mov' || ext === 'quicktime') cleanExt = 'mov';
  else cleanExt = 'mp4';

  const fileName = `video_${Date.now()}_${Math.random().toString(36).substring(2, 8)}.${cleanExt}`;
  const mimeType = cleanExt === 'webm' ? 'video/webm' : (cleanExt === 'mov' ? 'video/quicktime' : 'video/mp4');

  // 1) خادم المنصة /api/upload-video (يعمل محلياً، على شبكة الواي فاي، والـ localhost بسرعة فائقة)
  try {
    const fd = new FormData();
    fd.append("video", file, fileName);
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 25000);
    const localRes = await fetch("/api/upload-video", {
      method: "POST",
      body: fd,
      signal: controller.signal
    });
    clearTimeout(timeoutId);
    if (localRes.ok) {
      const data = await localRes.json();
      if (data && data.url) {
        console.log("✅ تم رفع الفيديو عبر سيرفر المنصة بنجاح:", data.url);
        return data.url;
      }
    }
  } catch(e) {
    console.warn("Upload to /api/upload-video:", e.message || e);
  }

  // 2) الرفع المباشر عبر REST API إلى Supabase Storage
  const SUPABASE_STORAGE_URL = `https://jtpfpqalibbwdbirzdnk.supabase.co/storage/v1/object/videos/${fileName}`;
  const SUPABASE_PUBLIC_URL = `https://jtpfpqalibbwdbirzdnk.supabase.co/storage/v1/object/public/videos/${fileName}`;
  const SUPABASE_KEY = "sb_publishable_6N_kXZ3e5fB4XM7xKKfT-g_7AHN25Tp";

  try {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 90000); // 90 ثانية كافية للملفات الكبيرة

    const res = await fetch(SUPABASE_STORAGE_URL, {
      method: "POST",
      headers: {
        "apikey": SUPABASE_KEY,
        "Authorization": `Bearer ${SUPABASE_KEY}`,
        "Content-Type": mimeType
      },
      body: file,
      signal: controller.signal
    });
    clearTimeout(timeoutId);

    if (res.ok) {
      console.log("✅ تم رفع الفيديو إلى Supabase Storage بنجاح:", SUPABASE_PUBLIC_URL);
      return SUPABASE_PUBLIC_URL;
    } else {
      const errTxt = await res.text().catch(() => "");
      console.warn("Supabase Storage REST status:", res.status, errTxt);
    }
  } catch(err) {
    console.warn("Supabase Storage REST error:", err);
  }

  // 3) محاولة الرفع عبر SDK كخيار إضافي
  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);
  if (sb && sb.storage) {
    try {
      const { data, error } = await sb.storage.from('videos').upload(fileName, file, {
        cacheControl: '3600',
        upsert: true,
        contentType: mimeType
      });
      if (!error && data) {
        const { data: pData } = sb.storage.from('videos').getPublicUrl(fileName);
        if (pData && pData.publicUrl) {
          console.log("✅ تم رفع الفيديو عبر Supabase SDK:", pData.publicUrl);
          return pData.publicUrl;
        }
      }
    } catch(e) {
      console.warn("Supabase SDK error:", e);
    }
  }

  // 4) التحويل إلى Data URL دائم ومستقر (حتى 25 ميجابايت) لضمان عدم ضياع الفيديو على أي استضافة ثابتة
  return new Promise((resolve) => {
    if (file.size <= 25 * 1024 * 1024) {
      const reader = new FileReader();
      reader.onload = () => {
        console.log("✅ تم تحويل الفيديو إلى DataURL دائم");
        resolve(reader.result);
      };
      reader.onerror = () => {
        console.error("FileReader failed");
        resolve(null);
      };
      reader.readAsDataURL(file);
    } else {
      console.warn("حجم الفيديو كبير جداً ولم ينجح الرفع السحابي");
      resolve(null);
    }
  });
}

window.publishAdAsStory = function() {

  if (!currentStoryPost) return;

  const p = currentStoryPost;

  p.videoUrl = p.videoUrl || p.video || (p.images && p.images[0]) || p.imageUrl || "icon-192.png";

  p.videoPlacement = "story";

  p.createdAt = Date.now();

  const sb = window.supabase || (typeof supabase !== 'undefined' ? supabase : null);

  if (sb) {

    sb.from('posts').update({

      video_url: p.videoUrl,

      video_placement: 'story',

      status: 'approved',

      created_at: Date.now()

    }).eq('id', p.id).then(()=>{}).catch(()=>{});

  }

  if (typeof renderStoriesBar === 'function') renderStoriesBar();

  closeStoryModal();

  showToast("✅ تم نشر الإعلان في شريط الستوريات بنجاح (لمدة 24 ساعة) ⭕", "success", 3000);

};


/* ============================================================
   📱 PRINTABLE STORE QR STAND MODAL SYSTEM
   ============================================================ */
window.switchLuxStoreTab = function(tabName){
  const btnProds = document.getElementById('tabBtnProds');
  const btnBank = document.getElementById('tabBtnBank');
  const btnHours = document.getElementById('tabBtnHours');
  const topBtnBank = document.getElementById('luxTopBtnBank');

  const paneProds = document.getElementById('luxPaneProducts');
  const paneBank = document.getElementById('luxPaneBank');
  const paneHours = document.getElementById('luxPaneHours');

  // If clicking bank while bank pane is already open, toggle back to products
  if(tabName === 'bank' && paneBank && paneBank.style.display === 'block'){
    tabName = 'products';
  }

  [btnProds, btnBank, btnHours, topBtnBank].forEach(b => { if(b) b.classList.remove('active'); });

  if(paneProds) paneProds.style.display = 'none';
  if(paneBank) paneBank.style.display = 'none';
  if(paneHours) paneHours.style.display = 'none';

  if(tabName === 'bank'){
    if(btnBank) btnBank.classList.add('active');
    if(topBtnBank) topBtnBank.classList.add('active');
    if(paneBank){
      paneBank.style.display = 'block';
      try { paneBank.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch(_) {}
    }
  } else if(tabName === 'hours'){
    if(btnHours) btnHours.classList.add('active');
    if(paneHours) paneHours.style.display = 'block';
  } else {
    if(btnProds) btnProds.classList.add('active');
    if(paneProds) paneProds.style.display = 'block';
  }
};

